  id: string;
  filename: string;
  totalSize: number;
  chunkSize: number;
  chunks: ChunkMeta[];
  uploadedCount: number;
  failedChunks: FailedChunk[];
  status: 'pending' | 'uploading' | 'paused' | 'completed' | 'failed';
  createdAt: number;
}

export interface ChunkMeta {
  id: string;
  index: number;
  size: number;
  offset: number;
  uploaded: boolean;
  failed: boolean;
  hash: string;
}

export interface FailedChunk {
  id: string;
  index: number;
  offset: number;
  size: number;
  failedAt: number;
  retryCount: number;
}

export interface UploadProgress {
  total: number;
  uploaded: number;
  failed: number;
  percent: number;
}

export interface UploadResult {
  id: string;
  filename: string;
  size: number;
  url: string;
  hash: string;
}
