## 📦 utils/storage.ts (IndexedDB)

```typescript
const DB_NAME = 'UploadDB';
const DB_VERSION = 1;
const STORE_NAME = 'uploads';

interface IDBOpenDBRequest {
  onupgradeneeded: (e: IDBVersionChangeEvent) => void;
}

interface IDBDatabase {
  transaction: (stores: string[], mode: 'readonly' | 'readwrite') => IDBTransaction;
  objectStore: (name: string, mode?: IDBTransactionMode) => IDBObjectStore;
}

interface IDBTransaction {
  objectStore: (name: string) => IDBObjectStore;
  abort: () => void;
}

interface IDBObjectStore {
  add: (value: any) => IDBRequest;
  get: (key: string) => IDBRequest;
  put: (value: any) => IDBRequest;
  delete: (key: string) => IDBRequest;
  getAll: () => IDBRequest;
  index: (name: string) => IDBIndex;
}

interface IDBIndex {
  getAll: (value: any) => IDBRequest;
}

interface IDBRequest {
  result: any;
  error: any;
}

interface IDBFactory {
  open: (name: string, version?: number) => IDBOpenDBRequest;
}

export class Storage {
  private db: IDBDatabase | null = null;
  private factory: IDBFactory;

  constructor() {
    this.factory = (window as any).indexedDB;
  }

  open() {
    if (this.db) return Promise.resolve(this.db);
    const request = this.factory.open(DB_NAME, DB_VERSION);
    return new Promise<IDBDatabase>((resolve, reject) => {
      request.onerror = () => reject(request.error);
      request.onupgradeneeded = (e) => {
        const db = e.target as IDBOpenDBRequest;
        if (!db.result.objectStoreNames.contains(STORE_NAME)) {
          db.result.createObjectStore(STORE_NAME, { keyPath: 'id' });
        }
      };
      request.onsuccess = () => {
        this.db = request.result;
        resolve(this.db);
      };
    });
  }

  async add(item: UploadState) {
    const db = await this.open();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const req = store.add(item);
    return new Promise<string>((resolve, reject) => {
      req.onsuccess = () => resolve(req.result as string);
      req.onerror = () => reject(req.error);
    });
  }

  async get(id: string) {
    const db = await this.open();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const req = store.get(id);
    return new Promise<UploadState | undefined>((resolve, reject) => {
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve(undefined);
    });
  }

  async getAll() {
    const db = await this.open();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    const req = store.getAll();
    return new Promise<UploadState[]>((resolve, reject) => {
      req.onsuccess = () => resolve(req.result);
      req.onerror = () => resolve([]);
    });
  }

  async update(id: string, partial: Partial<UploadState>) {
    const db = await this.open();
    const item = await this.get(id);
    if (!item) return;
    const merged = { ...item, ...partial };
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const req = store.put(merged);
    return new Promise<void>((resolve, reject) => {
      req.onsuccess = resolve;
      req.onerror = () => reject(req.error);
    });
  }

  async delete(id: string) {
    const db = await this.open();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    const req = store.delete(id);
    return new Promise<void>((resolve, reject) => {
      req.onsuccess = resolve;
      req.onerror = () => reject(req.error);
    });
  }
}
