## 📦 utils/chunk.ts

```typescript
export function splitChunks(file: File, chunkSize: number): ChunkMeta[] {
  const chunks: ChunkMeta[] = [];
  const size = file.size;
  const totalChunks = Math.ceil(size / chunkSize);
  for (let i = 0; i < totalChunks; i++) {
    const start = i * chunkSize;
    const end = Math.min(start + chunkSize, size);
    const chunk = {
      id: `chunk-${file.name}-${i}`,
      index: i,
      size: end - start,
      offset: start,
      uploaded: false,
      failed: false,
      hash: '',
    };
    chunks.push(chunk);
  }
  return chunks;
}

export function calculateHash(buffer: ArrayBuffer): string {
  const u8a = new Uint8Array(buffer);
  let hash = 0;
  for (let i = 0; i < u8a.length; i++) {
    hash = (hash << 5) - hash + u8a[i];
    hash |= 0;
  }
  return hash.toString(36);
}

export function getChunk(file: File, index: number, chunkSize: number): Promise<ArrayBuffer> {
  const start = index * chunkSize;
  const end = Math.min(start + chunkSize, file.size);
  const slice = file.slice(start, end);
  return new Promise((resolve, reject) => {
    slice.arrayBuffer().then(resolve).catch(reject);
  });
}
