import { splitChunks, getChunk, calculateHash } from './chunk';
import { Storage } from './storage';
import { UploadState, ChunkMeta, FailedChunk, UploadProgress } from './types';

const storage = new Storage();
const DEFAULT_CHUNK_SIZE = 4 * 1024 * 1024; // 4MB
const MAX_RETRIES = 3;

interface UploadConfig {
  chunkSize?: number;
  maxConcurrency?: number;
  retryDelay?: number;
}

export class UploadManager {
  private idCounter = 0;
  private running: Map<string, UploadState> = new Map();
  private paused = new Set<string>();
  private abortControllers: Map<string, AbortController> = new Map();

  constructor(private config: UploadConfig = {}) {}

  async start(file: File, onProgress?: (p: UploadProgress) => void) {
    const id = this.generateId();
    const chunkSize = this.config.chunkSize ?? DEFAULT_CHUNK_SIZE;
    const maxConcurrency = this.config.maxConcurrency ?? 4;
    const retryDelay = this.config.retryDelay ?? 1000;

    const chunks = splitChunks(file, chunkSize);
    const state: UploadState = {
      id,
      filename: file.name,
      totalSize: file.size,
      chunkSize,
      chunks,
      uploadedCount: 0,
      failedChunks: [],
      status: 'pending',
      createdAt: Date.now(),
    };

    await storage.add(state);
    this.running.set(id, state);

    const controller = new AbortController();
    this.abortControllers.set(id, controller);

    const abort = () => {
      controller.abort();
      this.abortControllers.delete(id);
      this.running.delete(id);
      this.paused.delete(id);
      onProgress?.({ total: file.size, uploaded: 0, failed: 0, percent: 0 });
    };

    try {
      await this.uploadLoop(state, maxConcurrency, retryDelay, onProgress, abort);
      this.running.delete(id);
      onProgress?.({ total: file.size, uploaded: file.size, failed: 0, percent: 100 });
    } catch (err) {
      if (err.name !== 'AbortError') {
        this.running.delete(id);
        onProgress?.({ total: file.size, uploaded: 0, failed: 0, percent: 0 });
        throw err;
      }
    }
  }

  private generateId() {
    this.idCounter++;
    return `upload-${Date.now()}-${this.idCounter}`;
  }

  async uploadLoop(
    state: UploadState,
    maxConcurrency: number,
    retryDelay: number,
    onProgress: (p: UploadProgress) => void,
    abort: () => void
  ) {
    const active = new Set<string>();
    const queue: Array<{ chunk: ChunkMeta; resolve: (v: any) => void; reject: (e: any) => void }> = [];

    const push = (chunk: ChunkMeta) => {
      return new Promise((resolve, reject) => {
        queue.push({ chunk, resolve, reject });
        processQueue();
      });
    };

    const processQueue = () => {
      while (active.size < maxConcurrency && queue.length) {
        const item = queue.shift();
        if (!item) break;
        active.add(item.chunk.id);
        this.uploadChunk(item.chunk, state, item.resolve, item.reject, abort);
      }
