    const resolveChunk = (chunk: ChunkMeta) => {
      active.delete(chunk.id);
      state.chunks[chunk.index] = chunk;
      state.uploadedCount++;
      state.failedChunks = state.failedChunks.filter((f) => f.id !== chunk.id);
      const total = state.totalSize;
      const uploaded = state.uploadedCount * chunkSize;
      const failed = state.failedChunks.length;
      const percent = total ? (uploaded / total) * 100 : 0;
      onProgress({ total, uploaded, failed, percent });
      processQueue();
    };

    const rejectChunk = (chunk: ChunkMeta, error: any) => {
      active.delete(chunk.id);
      chunk.failed = true;
      chunk.failedAt = Date.now();
      chunk.retryCount = (chunk.retryCount ?? 0) + 1;
      state.failedChunks.push({ id: chunk.id, index: chunk.index, offset: chunk.offset, size: chunk.size, failedAt: Date.now(), retryCount: chunk.retryCount ?? 0 });
      state.uploadedCount--;
      const total = state.totalSize;
      const uploaded = state.uploadedCount * chunkSize;
      const failed = state.failedChunks.length;
      const percent = total ? (uploaded / total) * 100 : 0;
      onProgress({ total, uploaded, failed, percent });
      processQueue();
    };

    // 启动所有已上传的分片
    state.chunks.forEach((chunk) => {
      if (chunk.uploaded) resolveChunk(chunk);
    });

    // 启动未上传的分片
    state.chunks.forEach((chunk) => {
      if (!chunk.uploaded) push(chunk);
    });

    while (active.size > 0 || queue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, 50));
    }

    // 重试失败分片
    while (state.failedChunks.length) {
      const item = state.failedChunks.shift();
      if (!item) break;
      const chunk = state.chunks[item.index];
      if (!chunk) continue;
      const delay = Math.min(retryDelay * (item.retryCount ?? 0), 60000);
      await new Promise((resolve) => setTimeout(resolve, delay));
      push(chunk);
    }

    // 等待所有重试完成
    while (active.size > 0 || queue.length > 0) {
      await new Promise((resolve) => setTimeout(resolve, 50));
