### 📄 `index.html`

```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
<title>Neon Drift: Mission Runner</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<div id="game-wrap">
  <canvas id="game" width="800" height="500"></canvas>

  <!-- HUD -->
  <div id="hud">
    <div class="hud-item"><span class="hud-label">HP</span><span class="hud-value" id="hp">100</span></div>
    <div class="hud-item"><span class="hud-label">AMMO</span><span class="hud-value" id="ammo">∞</span></div>
    <div class="hud-item"><span class="hud-label">MONEY</span><span class="hud-value" id="money">0</span></div>
    <div class="hud-item"><span class="hud-label">MISSION</span><span class="hud-value" id="mission">None</span></div>
  </div>

  <!-- Joystick -->
  <div id="joystick-wrap">
    <div class="joystick" id="joystick">
      <div class="stick"></div>
    </div>
  </div>

  <!-- Vehicle Steering -->
  <div id="steer-wrap">
    <div class="steering" id="steering">
      <div class="steer-left">◀</div>
      <div class="steer-right">▶</div>
    </div>
  </div>

  <!-- Buttons -->
  <div id="buttons">
    <button id="btn-fire" class="btn" disabled>Fire</button>
    <button id="btn-vehicle" class="btn">Vehicle</button>
    <button id="btn-mission" class="btn">Mission</button>
  </div>

  <!-- Vehicle UI -->
  <div id="vehicle-ui" class="hidden">
    <div class="vehicle-info">
      <div><span>VEHICLE</span><span id="v-name">None</span></div>
      <div><span>SPEED</span><span id="v-speed">0</span></div>
      <div><span>FUEL</span><span id="v-fuel">100</span></div>
    </div>
  </div>

  <!-- Mission UI -->
  <div id="mission-ui" class="hidden">
    <div class="mission-info">
      <div><span id="m-title">Mission</span></div>
      <div><span id="m-desc">No mission</span></div>
    </div>
  </div>

  <!-- Inventory -->
  <div id="inventory" class="hidden">
    <div class="inv-item" data-item="ammo">Ammo</div>
    <div class="inv-item" data-item="money">Cash</div>
  </div>

  <!-- Mobile overlay -->
  <div id="mobile-overlay" class="hidden">
    <div class="mobile-hint">Tap joystick to move · Tap fire to shoot</div>
  </div>

  <!-- Controls hint -->
  <div id="controls-hint">
    <div>WASD / Joystick to move · SPACE / Fire to shoot · M to mission</div>
  </div>
</div>

<script src="game.js"></script>
</body>
</html>
```

