```css
body {
  margin: 0;
  padding: 0;
  background: #000;
  overflow: hidden;
  font-family: 'Segoe UI', sans-serif;
  user-select: none;
  -webkit-user-select: none;
  touch-action: none;
}

#game-wrap {
  position: fixed;
  inset: 0;
  background: #000;
  overflow: hidden;
}

#game {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

#hud {
  position: absolute;
  top: 10px;
  left: 10px;
  display: flex;
  gap: 10px;
  font-size: 14px;
  color: #fff;
  text-shadow: 0 1px 4px #000;
  pointer-events: none;
