<body>
<div id="scene">
  <div id="horizon"></div>
  <div id="stars"></div>
  <div id="sun"></div>
  <div id="moon"></div>
  <button id="pause-btn" aria-label="Pause simulation">❚❚</button>
</div>
<div id="info">
  <div class="label">Location</div>
  <div class="value" id="location">Denver, CO</div>
  <div class="label">Date</div>
  <div class="value" id="date">—</div>
  <div class="label">Time</div>
  <div class="value" id="time">—</div>
  <div class="label">Phase</div>
  <div class="value" id="phase">—</div>
  <div class="sub" id="sub">Drag the sky to change the horizon</div>
</div>

<script>
  // ---------- Configuration ----------
  const CONFIG = {
    location: "Denver, CO",
    latitude: 39.7392,
    longitude: -104.9903,
    timezone: -7, // UTC offset in hours (Denver MST)
    starCount: 80,
    starMinSize: 0.8,
    starMaxSize: 2.2,
    sunSize: 140,
    moonSize: 80,
    horizonHeight: 40,
    horizonColor: "#2a1a08",
  };

  // ---------- State ----------
  const state = {
    now: Date.now(),
    elapsed: 0,
    paused: false,
    dragging: false,
    dragStartX: 0,
    dragStartY: 0,
    dragStartHorizon: 0,
  };

  // ---------- DOM ----------
  const scene = document.getElementById("scene");
  const sun = document.getElementById("sun");
  const moon = document.getElementById("moon");
  const starsEl = document.getElementById("stars");
  const pauseBtn = document.getElementById("pause-btn");
  const info = {
    location: document.getElementById("location"),
    date: document.getElementById("date"),
    time: document.getElementById("time"),
    phase: document.getElementById("phase"),
    sub: document.getElementById("sub"),
  };

  // ---------- Utilities ----------
  function pad(n) { return String(n).padStart(2, "0"); }
  function formatTime(date) {
    return `${pad(date.getHours())}:${pad(date.getMinutes())}:${pad(date.getSeconds())}`;
  }
  function formatDateTime(date) {
    return `${date.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" })} · ${date.toLocaleTimeString(undefined, { timeZone: "UTC" })}`;
  }
  function getPhaseLabel(phase) {
    const p = Math.round(phase * 100);
    if (p < 25) return "Night";
    if (p < 60) return "Dawn";
    if (p < 85) return "Day";
    return "Dusk";
  }

  // ---------- Sky color ----------
  // Returns CSS color string for a given "phase" (0.0 = night, 1.0 = day)
  function skyColor(phase) {
    // Blend between night and day
    const t = Math.max(0, Math.min(1, phase));
    const night = "#05050b";
    const dawn = "#1a1a2e";
    const day = "#7fb8ff";
    const dusk = "#ff8a5c";
    const sunrise = "#ff6b3c";

    // Use a smooth blend
    let r, g, b;
    if (t < 0.25) {
      // Night -> dawn
      const k = t / 0.25;
      r = night.r + (dawn.r - night.r) * k;
      g = night.g + (dawn.g - night.g) * k;
      b = night.b + (dawn.b - night.b) * k;
    } else if (t < 0.6) {
      // Dawn -> day
      const k = (t - 0.25) / 0.35;
      r = dawn.r + (day.r - dawn.r) * k;
      g = dawn.g + (day.g - dawn.g) * k;
      b = dawn.b + (day.b - dawn.b) * k;
    } else if (t < 0.85) {
      // Day -> dusk
      const k = (t - 0.6) / 0.25;
      r = day.r + (dusk.r - day.r) * k;
      g = day.g + (dusk.g - day.g) * k;
      b = day.b + (dusk.b - day.b) * k;
    } else {
      // Dusk -> night
      const k = (t - 0.85) / 0.15;
      r = dusk.r + (sunrise.r - dusk.r) * k;
      g = dusk.g + (sunrise.g - dusk.g) * k;
      b = dusk.b + (sunrise.b - dusk.b) * k;
    }

    // Clamp and round
    r = Math.max(0, Math.min(255, Math.round(r)));
    g = Math.max(0, Math.min(255, Math.round(g)));
    b = Math.max(0, Math.min(255, Math.round(b)));
    return `rgb(${r},${g},${b})`;
  }

  // ---------- Sun position ----------
  function sunPosition(phase) {
    // phase: 0.0 = night, 1.0 = day
    const t = Math.max(0, Math.min(1, phase));
    const horizon = CONFIG.horizonHeight;

    // Azimuth: 0 = east, 90 = south, 180 = west
    // Altitude: 0 = horizon, 90 = zenith

    // Phase 0..0.25: night -> dawn (east)
    // Phase 0.25..0.75: day (south)
    // Phase 0.75..1: dusk -> night (west)

    let azimuth, altitude;

    if (t < 0.25) {
      // Dawn: sun rises from east
      const k = t / 0.25;
      const angle = Math.PI / 2 - Math.PI * k; // from 0 (east) to -PI/2 (south)
      azimuth = angle * (180 / Math.PI);
      altitude = Math.sin(angle) * 90;
    } else if (t < 0.75) {
      // Day: sun is in the south
      azimuth = 0;
      // Altitude varies from horizon to zenith back to horizon
      const k = (t - 0.25) / 0.5;
      const top = 0.5 + k * 0.5; // 0.5..1
      altitude = 90 * top;
    } else {
      // Dusk: sun sets in the west
      const k = (t - 0.75) / 0.25;
      const angle = Math.PI * k; // from 0 to PI
      azimuth = -90 + angle * 2; // from -90 (west) to 90 (south)
      altitude = 90 * (1 - k);
    }

    // Clamp altitude to horizon + 10 degrees
    altitude = Math.max(0, Math.min(90, altitude));

    // Convert to screen coordinates
    const cx = window.innerWidth / 2;
    const cy = window.innerHeight / 2;
    const radius = Math.min(cx, cy) * 0.65;
    const x = cx + Math.cos(azimuth * Math.PI / 180) * radius;
    const y = cy - Math.sin(altitude * Math.PI / 180) * radius;
    const size = CONFIG.sunSize * (1 + Math.min(altitude / 90, 1) * 0.3);

    return { x, y, size, altitude, azimuth };
  }

  // ---------- Stars ----------
  function generateStars() {
    starsEl.innerHTML = "";
    for (let i = 0; i < CONFIG.starCount; i++) {
      const s = document.createElement("div");
      s.className = "star";
      const r = 1 + Math.random() * (CONFIG.starMaxSize - CONFIG.starMinSize);
      s.style.width = r + "px";
      s.style.height = r + "px";
      s.style.left = Math.random() * 100 + "%";
      s.style.top = Math.random() * 80 + "%";
      s.style.animationDelay = (Math.random() * 3) + "s";
      s.style.animationDuration = (2 + Math.random() * 4) + "s";
      starsEl.appendChild(s);
    }
  }

  // ---------- Render ----------
  function render() {
    const phase = state.elapsed / (24 * 3600);
    const { x, y, size, altitude, azimuth } = sunPosition(phase);

    // Sky gradient
    const sky = skyColor(phase);
    scene.style.background = sky;

    // Horizon
    const horizon = CONFIG.horizonColor;
    const horizonEl = document.getElementById("horizon");
    horizonEl.style.background = `linear-gradient(to top, ${horizon} 0%, ${horizon} 40%, transparent 100%)`;

    // Sun
    sun.style.left = x + "px";
    sun.style.top = y + "px";
    sun.style.width = size + "px";
    sun.style.height = size + "px";
    sun.style.opacity = Math.min(1, altitude / 90);

    // Moon
    const isNight = phase < 0.25 || phase > 0.75;
    moon.style.opacity = isNight ? 1 : 0;
    moon.style.transform = isNight ? "scale(1)" : "scale(0.3)";
    moon.style.left = x + "px";
    moon.style.top = y + "px";
    moon.style.width = CONFIG.moonSize + "px";
    moon.style.height = CONFIG.moonSize + "px";

    // Info
    const now = new Date(state.now);
    info.date.textContent = now.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" });
    info.time.textContent = formatTime(now);
    info.phase.textContent = getPhaseLabel(phase);
    info.sub.textContent = state.dragging ? "Dragging horizon..." : "Drag the sky to change the horizon";
  }

  // ---------- Animation loop ----------
  function tick() {
    if (!state.paused) {
      state.now = Date.now();
      state.elapsed = (state.now - CONFIG.start) / 1000;
    }
    render();
    requestAnimationFrame(tick);
  }

  // ---------- Drag to change horizon ----------
  function startDrag(e) {
    state.dragging = true;
    state.dragStartX = e.clientX;
    state.dragStartY = e.clientY;
    state.dragStartHorizon = CONFIG.horizonHeight;
  }
  function moveDrag(e) {
    if (!state.dragging) return;
    const dx = e.clientX - state.dragStartX;
    const dy = e.clientY - state.dragStartY;
    // Invert Y so moving up makes horizon shorter
    const newHeight = Math.max(20, Math.min(120, state.dragStartHorizon - dy));
    CONFIG.horizonHeight = newHeight;
    const horizonEl = document.getElementById("horizon");
    horizonEl.style.height = newHeight + "px";
    horizonEl.style.background = `linear-gradient(to top, ${CONFIG.horizonColor} 0%, ${CONFIG.horizonColor} 40%, transparent 100%)`;
    info.sub.textContent = "Dragging horizon...";
  }
  function endDrag() {
    state.dragging = false;
  }

  // ---------- Events ----------
  scene.addEventListener("mousedown", startDrag);
  window.addEventListener("mousemove", moveDrag);
  window.addEventListener("mouseup", endDrag);
  pauseBtn.addEventListener("click", () => {
    state.paused = !state.paused;
    pauseBtn.classList.toggle("active", state.paused);
    pauseBtn.textContent = state.paused ? "▶" : "❚❚";
  });

  // ---------- Init ----------
  CONFIG.start = Date.now();
  generateStars();
  render();
  tick();
</script>
</body>
</html>
```

