}

function sendMessage() {
  const from = getUser().name;
  const compose = document.querySelector('.compose');
  const input = compose.querySelector('input');
  const text = input.value.trim();
  if (!text || !from) return;
  const msgs = get(STORAGE.messages, []);
  msgs.push({ id: Date.now(), from, avatar: getUser().avatar || 'https://i.pravatar.cc/80?img=47', text, time: 'just now' });
  set(STORAGE.messages, msgs);
  renderMessages();
  input.value = '';
}

/* ---------- Avatar helpers ---------- */
function getUser() {
  return get(STORAGE.user, null);
}
function getAvatar(user) {
  if (!user) return 'https://i.pravatar.cc/80?img=47';
  return `https://i.pravatar.cc/80?u=${encodeURIComponent(user.name)}`;
}

/* ---------- Init ---------- */
function init() {
  initTheme();
  renderProfile();
  renderArticles();
  renderPhotos();
  renderVideos();
  renderActivity();
  renderMessages();

  // Nav button handlers
  document.querySelectorAll('[data-nav]').forEach(btn => {
    btn.addEventListener('click', (e) => {
      e.preventDefault();
      const target = btn.getAttribute('data-nav');
      navigate(target);
    });
  });

  // Article list click
  document.querySelectorAll('.card-article').forEach(card => {
    card.addEventListener('click', () => {
      const title = card.querySelector('h3')?.textContent;
      if (title) openArticle(title);
    });
  });

  // Back link
  document.querySelectorAll('.back-link').forEach(b => {
    b.addEventListener('click', (e) => {
      e.preventDefault();
      const target = b.getAttribute('data-nav');
      navigate(target);
    });
  });

  // Messages compose
  const compose = document.querySelector('.compose');
  if (compose) {
    compose.addEventListener('submit', (e) => {
      e.preventDefault();
      sendMessage();
    });
  }

  // Theme toggle
  document.getElementById('themeToggle').addEventListener('click', toggleTheme);

  // Follow button click (demo)
  document.getElementById('followBtn').addEventListener('click', () => {
    const btn = document.getElementById('followBtn');
    if (btn.innerHTML.includes('Unfollow')) {
      btn.innerHTML = '<i class="fa-solid fa-user-plus"></i> Follow';
      btn.style.background = '';
      btn.style.color = '';
    }
  });
}

document.addEventListener('DOMContentLoaded', init);
```

