   ========================================================= */

const STORAGE_KEY = 'furnispace.v1';

const CATEGORIES = {
  all:     { label: 'All',      items: ['sofa','table','chair','bed','desk','decor'] },
  sofa:    { label: 'Sofas',    items: ['sofa'] },
  table:   { label: 'Tables',   items: ['table'] },
