  desk:    { label: 'Desks',    items: ['desk'] },
  decor:   { label: 'Decor',    items: ['decor'] },
};

const FURNITURE = [
  { id: 's1', cat: 'sofa',   name: 'Modern Leather Sofa',      price: 1299,  width: 140, depth: 80, height: 85, img: 'https://images.unsplash.com/photo-1555041469-a586c61ea9bc?w=600&q=80' },
