```javascript
// ---------- Music Theory Data ----------
const SCALES = {
  'C major': {
    name: 'C Major',
    notes: ['C','D','E','F','G','A','B'],
    type: 'major'
  },
  'A minor': {
    name: 'A Minor',
    notes: ['A','B','C','D','E','F','G'],
    type: 'minor'
  },
  'D Dorian': {
    name: 'D Dorian',
    notes: ['D','E','F','G','A','B','C'],
    type: 'dorian'
  },
  'E Phrygian': {
    name: 'E Phrygian',
    notes: ['E','F','G','A','B','C','D'],
    type: 'phrygian'
  },
  'G Lydian': {
    name: 'G Lydian',
    notes: ['G','A','B','C','D','E','F#'],
    type: 'lydian'
  },
  'F Mixolydian': {
    name: 'F Mixolydian',
    notes: ['F','G','A','Bb','C','D','E'],
    type: 'mixolydian'
  },
  'B Locrian': {
    name: 'B Locrian',
    notes: ['B','C','D','E','F','G','A'],
    type: 'locrian'
  }
};

const CHORDS = {
  'C major triad': { root: 'C', notes: ['C','E','G'], type: 'major' },
  'Am minor triad': { root: 'A', notes: ['A','C','E'], type: 'minor' },
  'C diminished triad': { root: 'C', notes: ['C','Eb','Gb'], type: 'diminished' }
};

// ---------- Audio Synthesis ----------
const audioCtx = (() => {
  let ctx = null;
  try { ctx = new (window.AudioContext || window.webkitAudioContext)(); }
  catch (e) { return null; }
  return ctx;
})();

function noteToFreq(note) {
  const [letter, accidental] = note.split(/[b#]/);
  const baseFreq = { C: 261.63, D: 293.66, E: 329.63, F: 346.90, G: 392.00, A: 440.00, B: 493.88 }[letter];
  if (!baseFreq) return null;
  let acc = 0;
  if (accidental === '#') acc = 1;
  else if (accidental === 'b') acc = -1;
  return baseFreq * Math.pow(2, acc / 12);
}

function playNote(note, duration = 0.35, volume = 0.25, attack = 0.05, release = 0.1) {
  if (!audioCtx) return;
  const ctx = audioCtx;
  const freq = noteToFreq(note);
  if (!freq) return;
  const osc = ctx.createOscillator();
  const gain = ctx.createGain();
  osc.type = 'triangle';
  osc.frequency.value = freq;
  gain.gain.setValueAtTime(0, ctx.currentTime);
  gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + attack);
  gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration - release);
  osc.connect(gain).connect(ctx.destination);
  osc.start();
  osc.stop(ctx.currentTime + duration);
}

function playChord(chord, duration = 0.5) {
  chord.notes.forEach(n => playNote(n, duration * 0.6, 0.22));
}

function playScale(scale, duration = 0.5) {
  scale.notes.forEach(n => playNote(n, duration * 0.6, 0.22));
}

function playNotes(notes, duration = 0.5) {
  notes.forEach(n => playNote(n, duration * 0.6, 0.22));
}

// ---------- Navigation ----------
function setActiveNav(page) {
  document.querySelectorAll('.nav a').forEach(a => {
    a.classList.toggle('active', a.dataset.page === page);
  });
}

document.querySelectorAll('.nav a, .audio-btn, .scale-select select').forEach(el => {
  el.addEventListener('click', (e) => {
    e.preventDefault();
    const href = el.getAttribute('href');
    if (href && href.startsWith('#')) {
      const target = document.querySelector(href);
      if (target) target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});

// ---------- Intro Audio ----------
document.querySelectorAll('.audio-btn').forEach(btn => {
  btn.addEventListener('click', () => {
    const key = btn.dataset.scale;
    const scale = SCALES[key];
    if (!scale) return;
    playScale(scale, 1.2);
  });
});

// ---------- Practice ----------
(function initPractice() {
  const keyLabel = document.getElementById('keyLabel');
  const chordLabel = document.getElementById('chordLabel');
  const notesLabel = document.getElementById('notesLabel');
  const n1 = document.getElementById('n1');
  const n2 = document.getElementById('n2');
  const n3 = document.getElementById('n3');
  const checkBtn = document.getElementById('checkBtn');
  const resetBtn = document.getElementById('resetBtn');
  const result = document.getElementById('result');

  const chord = CHORDS['C major triad'];
  keyLabel.textContent = chord.root;
  chordLabel.textContent = chord.type;
  notesLabel.textContent = chord.notes.join(' ');

  const correct = [chord.notes[0], chord.notes[1], chord.notes[2]];

  checkBtn.addEventListener('click', () => {
    const user = [n1.value.trim().toUpperCase(), n2.value.trim().toUpperCase(), n3.value.trim().toUpperCase()];
    if (!user.every(n => n.length === 2)) {
      showError('Please enter all three notes.');
      return;
    }
    const matches = user.map((u, i) => u === correct[i]);
    const allCorrect = matches.every(m => m);
    const score = matches.filter(m => m).length;

    if (allCorrect) {
      showSuccess(`Perfect! You got all 3 notes correct. 🎉`);
      playChord(chord, 0.8);
    } else if (score === 2) {
      showWarning(`Good! You got ${score} out of 3. The missing note is ${correct[matches.indexOf(false)]}.`);
      playNote(correct[matches.indexOf(false)], 1, 0.25);
    } else {
      showError(`Try again. The correct notes are ${correct.join(', ')}.`);
      playChord(chord, 1.2);
    }
  });

  resetBtn.addEventListener('click', () => {
    n1.value = ''; n2.value = ''; n3.value = '';
    result.hidden = true;
    playChord(chord, 0.4);
  });

  function showSuccess(msg) { showResult(msg, 'success'); }
  function showError(msg) { showResult(msg, 'error'); }
  function showWarning(msg) { showResult(msg, 'warning'); }
  function showResult(msg, cls) {
    result.textContent = msg;
    result.className = 'result ' + cls;
    result.hidden = false;
  }

  // Auto-check on Enter
  [n1, n2, n3].forEach(inp => {
    inp.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') checkBtn.click();
    });
  });
})();

// ---------- Scale Practice ----------
(function initScalePractice() {
  const scaleSelect = document.getElementById('scaleSelect');
  const playScaleBtn = document.getElementById('playScaleBtn');
  const playChordBtn = document.getElementById('playChordBtn');
  const scaleResult = document.getElementById('scaleResult');

  playScaleBtn.addEventListener('click', () => {
    const key = scaleSelect.value;
    const scale = SCALES[key];
    if (!scale) return;
    playScale(scale, 1.5);
  });

  playChordBtn.addEventListener('click', () => {
    const key = scaleSelect.value;
    const scale = SCALES[key];
    if (!scale) return;
    const root = scale.notes[0];
    playChord({ root, notes: [root, scale.notes[2], scale.notes[4]], type: 'major' }, 1);
  });

  scaleSelect.addEventListener('change', () => {
    const key = scaleSelect.value;
    const scale = SCALES[key];
    if (!scale) return;
    scaleResult.textContent = `You selected: ${scale.name} (${scale.notes.join(' ')})`;
    scaleResult.hidden = false;
  });
})();

// ---------- Theme Toggle ----------
(function initTheme() {
  const toggle = document.getElementById('themeToggle');
  const saved = localStorage.getItem('theme');
  if (saved) document.documentElement.setAttribute('data-theme', saved);
  else if (window.matchMedia && window.matchMedia('(prefers-color-scheme: light)').matches) {
    document.documentElement.setAttribute('data-theme', 'light');
  }

  toggle.addEventListener('click', () => {
    const cur = document.documentElement.getAttribute('data-theme');
    const next = cur === 'light' ? 'dark' : 'light';
    document.documentElement.setAttribute('data-theme', next);
    localStorage.setItem('theme', next);
  });
})();

// ---------- Smooth scroll for anchor links ----------
document.querySelectorAll('a[href^="#"]').forEach(a => {
  a.addEventListener('click', (e) => {
    const id = a.getAttribute('href');
    if (id.length > 1) {
      const target = document.querySelector(id);
      if (target) {
        e.preventDefault();
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
    }
  });
});
