## 🚀 `app.py`

```python
from flask import Flask, render_template, request, redirect, url_for, flash, send_from_directory, jsonify
from flask_login import LoginManager, login_user, logout_user, login_required, current_user
from flask_wtf.csrf import CSRFProtect
from werkzeug.utils import secure_filename
import os
import uuid
from models import db, User, Category, Dish, Menu
from forms import UploadDishForm, ReviewDishForm

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key-here'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///menu.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
app.config['UPLOAD_FOLDER'] = 'static/images/dishes'
app.config['ALLOWED_EXTENSIONS'] = {'png', 'jpg', 'jpeg', 'gif'}

csrf = CSRFProtect(app)
db.init_app(app)
login_manager = LoginManager(app)
login_manager.login_view = 'login'

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

@app.route('/')
def index():
    categories = Category.query.all()
    return render_template('index.html', categories=categories)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if current_user.is_authenticated:
        return redirect(url_for('dashboard'))
    # In a real app, add form handling
    return render_template('login.html')

@app.route('/dashboard')
@login_required
def dashboard():
    if current_user.role == 'chef':
        pending_count = Dish.query.filter_by(status='pending', uploaded_by=current_user.id).count()
        return render_template('chef_upload.html', pending_count=pending_count)
    elif current_user.role == 'manager':
        return render_template('manager_review.html')
    else:
        return render_template('customer_view.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/api/categories')
def api_categories():
    return jsonify([{'id': c.id, 'name': c.name} for c in Category.query.all()])

@app.route('/api/dishes')
def api_dishes():
    status = request.args.get('status', 'all')
    if status == 'all':
        dishes = Dish.query.all()
    else:
        dishes = Dish.query.filter_by(status=status).all()
    return jsonify([{
        'id': d.id,
        'name': d.name,
        'description': d.description,
        'price': d.price,
        'image': d.image_url,
        'category': d.category.name if d.category else None,
        'status': d.status,
        'approved_at': d.approved_at.isoformat() if d.approved_at else None
    } for d in dishes])

@app.route('/upload', methods=['GET', 'POST'])
@login_required
def upload():
    if current_user.role != 'chef':
        return redirect(url_for('dashboard'))
    form = UploadDishForm()
    categories = Category.query.all()
    if form.validate_on_submit():
        file = form.image.data
        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            unique_filename = str(uuid.uuid4()) + '.' + filename.rsplit('.', 1)[1]
            file_path = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)
            file.save(file_path)
            dish = Dish(
                name=form.name.data,
                description=form.description.data,
                price=form.price.data,
                image_url=url_for('static', filename=f'images/dishes/{unique_filename}'),
                category_id=form.category_id.data,
                uploaded_by=current_user.id,
                status='pending'
            )
            db.session.add(dish)
            db.session.commit()
            flash('Dish uploaded successfully. Awaiting manager approval.', 'success')
        else:
            flash('Invalid file format. Please upload JPG, PNG or GIF.', 'error')
    return render_template('chef_upload.html', form=form, categories=categories)

@app.route('/review')
@login_required
def review():
    if current_user.role != 'manager':
        return redirect(url_for('dashboard'))
    dishes = Dish.query.filter_by(status='pending').all()
    return render_template('manager_review.html', dishes=dishes)

@app.route('/review/<int:dish_id>', methods=['GET', 'POST'])
@login_required
def review_dish(dish_id):
    if current_user.role != 'manager':
        return redirect(url_for('dashboard'))
    dish = Dish.query.get_or_404(dish_id)
    form = ReviewDishForm()
    if form.validate_on_submit():
        dish.status = form.status.data
        if form.status.data == 'rejected':
            dish.rejected_reason = form.reason.data
        else:
            dish.approved_at = datetime.utcnow()
            dish.rejected_reason = None
        db.session.commit()
        flash(f'Dish "{dish.name}" has been {form.status.data.lower()}.', 'success')
        return redirect(url_for('review'))
    return render_template('review_dish.html', form=form, dish=dish)

@app.route('/customer')
@login_required
def customer():
    if current_user.role != 'customer':
        return redirect(url_for('dashboard'))
    categories = Category.query.all()
    return render_template('customer_view.html', categories=categories)

@app.route('/api/search')
def search():
    q = request.args.get('q', '').strip()
    if not q:
        return jsonify([])
    dishes = Dish.query.filter(
        (Dish.name.ilike(f'%{q}%')) |
        (Dish.description.ilike(f'%{q}%')) |
        (Dish.category.has(Category.name.ilike(f'%{q}%')))
    ).all()
    return jsonify([{
        'id': d.id,
        'name': d.name,
        'description': d.description,
        'price': d.price,
        'image': d.image_url,
        'category': d.category.name if d.category else None,
        'status': d.status
    } for d in dishes])

@app.route('/api/menu')
def menu():
    menu = Menu.query.first()
    if not menu:
        menu = Menu(name='Welcome Menu', description='Our curated selection.', image_url=url_for('static', filename='images/default.jpg'))
        db.session.add(menu)
        db.session.commit()
    return jsonify({
        'id': menu.id,
        'name': menu.name,
        'description': menu.description,
        'image': menu.image_url
    })

@app.route('/uploads/<filename>')
def uploaded_file(filename):
    return send_from_directory(app.config['UPLOAD_FOLDER'], filename)

@app.errorhandler(404)
def not_found(e):
    return render_template('404.html'), 404

@app.errorhandler(500)
def internal_error(e):
    return render_template('500.html'), 500

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
        # Seed categories
        categories = ['Starters', 'Mains', 'Desserts', 'Drinks']
        for c in categories:
            db.session.merge(Category(name=c, description=f'{c} category'))
        db.session.commit()
        print('Database initialized.')
    app.run(debug=True)
