### 🧩 Code: `main.py`

```python
import os
import json
import shutil
import uuid
from pathlib import Path
from typing import Dict, List, Optional

# --- Configuration ---
DATA_DIR = "groups"
USERS_FILE = "users.json"
GROUPS_FILE = "groups.json"
ADMIN_USER = "admin"

# --- Persistence helpers ---
def load_users() -> Dict[str, Dict]:
    """Load users from JSON."""
    if not os.path.exists(USERS_FILE):
        return {}
    with open(USERS_FILE, "r", encoding="utf-8") as f:
        return json.load(f)

def save_users(users: Dict[str, Dict]) -> None:
    """Save users to JSON."""
    os.makedirs(os.path.dirname(USERS_FILE), exist_ok=True)
    with open(USERS_FILE, "w", encoding="utf-8") as f:
        json.dump(users, f, indent=2, ensure_ascii=False)

def load_groups() -> Dict[str, Dict]:
    """Load groups from JSON."""
    if not os.path.exists(GROUPS_FILE):
        return {}
    with open(GROUPS_FILE, "r", encoding="utf-8") as f:
        return json.load(f)

def save_groups(groups: Dict[str, Dict]) -> None:
    """Save groups to JSON."""
    os.makedirs(os.path.dirname(GROUPS_FILE), exist_ok=True)
    with open(GROUPS_FILE, "w", encoding="utf-8") as f:
        json.dump(groups, f, indent=2, ensure_ascii=False)

# --- File system helpers ---
def ensure_group_dir(group_id: str) -> Path:
    """Ensure group directory exists."""
    path = Path(DATA_DIR) / group_id / "users"
    path.mkdir(parents=True, exist_ok=True)
    return path

def user_path(group_id: str, username: str) -> Path:
    """Get user's file path within group."""
    return Path(DATA_DIR) / group_id / "users" / username

# --- Core logic ---
class UserGroupFS:
    def __init__(self):
        self.users = load_users()
        self.groups = load_groups()

    def _ensure_admin_exists(self) -> None:
        """Create admin user if missing."""
        if ADMIN_USER not in self.users:
            self.users[ADMIN_USER] = {
                "group": "admin",
                "email": "admin@example.com",
                "created": str(uuid.uuid4()),
            }
            save_users(self.users)

    def _ensure_admin_group_exists(self) -> None:
        """Create admin group if missing."""
        if "admin" not in self.groups:
            self.groups["admin"] = {
                "name": "Administrator Group",
                "created": str(uuid.uuid4()),
            }
            save_groups(self.groups)
            ensure_group_dir("admin")

    def _group_exists(self, group_id: str) -> bool:
        return group_id in self.groups

    def _user_exists(self, username: str) -> bool:
        return username in self.users

    def create_group(self, group_id: str, name: str) -> bool:
        """Create a new group."""
        if self._group_exists(group_id):
            return False
        if not name.strip():
            return False
        self.groups[group_id] = {"name": name.strip(), "created": str(uuid.uuid4())}
        save_groups(self.groups)
        ensure_group_dir(group_id)
        return True

    def delete_group(self, group_id: str) -> bool:
        """Delete a group (admins only)."""
        if not self._group_exists(group_id):
            return False
        # Cannot delete admin group
        if group_id == "admin":
            return False
        # Remove users belonging to this group
        removed_users = []
        for u in self.users:
            if self.users[u].get("group") == group_id:
                removed_users.append(u)
        for u in removed_users:
            self.users[u]["group"] = "admin"  # reassign to admin group
        save_users(self.users)
        # Remove directory
        try:
            shutil.rmtree(Path(DATA_DIR) / group_id)
        except Exception:
            pass
        del self.groups[group_id]
        save_groups(self.groups)
        return True

    def list_groups(self) -> List[Dict]:
        """List all groups."""
        return [{"id": k, "name": v["name"]} for k, v in self.groups.items()]

    def list_users(self) -> List[Dict]:
        """List all users."""
        return [{"username": k, "group": v["group"]} for k, v in self.users.items()]

    def create_user(self, username: str, email: str, group_id: str) -> bool:
        """Create a new user in a group."""
        if self._user_exists(username):
            return False
        if not self._group_exists(group_id):
            return False
        self.users[username] = {
            "group": group_id,
            "email": email,
            "created": str(uuid.uuid4()),
        }
        save_users(self.users)
        return True

    def delete_user(self, username: str) -> bool:
        """Delete a user."""
        if not self._user_exists(username):
            return False
        # Remove user directory
        try:
            user_dir = user_path(self.users[username]["group"], username)
            shutil.rmtree(user_dir)
        except Exception:
            pass
        del self.users[username]
        save_users(self.users)
        return True

    def assign_user_to_group(self, username: str, group_id: str) -> bool:
        """Admin-only: reassign user to a group."""
        if not self._user_exists(username):
            return False
        if not self._group_exists(group_id):
            return False
        if self.users[username].get("group") == group_id:
            return True
        # Admin can reassign to any group
        if self.users[username].get("group") == "admin":
            return False
        self.users[username]["group"] = group_id
        save_users(self.users)
        return True

    def upload_file(self, username: str, filename: str, content: bytes) -> bool:
        """Upload a file for a user."""
        if not self._user_exists(username):
            return False
        group_id = self.users[username]["group"]
        user_dir = user_path(group_id, username)
        user_dir.mkdir(parents=True, exist_ok=True)
        filepath = user_dir / filename
        try:
            filepath.write_bytes(content)
            return True
        except Exception:
            return False

    def download_file(self, username: str, filename: str) -> Optional[bytes]:
        """Download a file for a user."""
        if not self._user_exists(username):
            return None
        group_id = self.users[username]["group"]
        filepath = user_path(group_id, username) / filename
        if not filepath.exists():
            return None
        return filepath.read_bytes()

    def list_user_files(self, username: str) -> List[str]:
        """List files for a user."""
        if not self._user_exists(username):
            return []
        group_id = self.users[username]["group"]
        user_dir = user_path(group_id, username)
        return [f.name for f in user_dir.iterdir() if f.is_file()]

    def list_user_group_files(self, username: str) -> List[str]:
        """List files for a user's group (shared)."""
        if not self._user_exists(username):
            return []
        group_id = self.users[username]["group"]
        group_dir = Path(DATA_DIR) / group_id
        files = []
        for u in self.users:
            if self.users[u]["group"] == group_id:
                user_subdir = user_path(group_id, u)
                for f in user_subdir.iterdir():
                    if f.is_file():
                        files.append(f.name)
        return files

    def list_user_group_users(self, username: str) -> List[str]:
        """List all users in user's group."""
        if not self._user_exists(username):
            return []
        group_id = self.users[username]["group"]
        users = []
        for u in self.users:
            if self.users[u]["group"] == group_id and u != username:
                users.append(u)
        return users

    def user_info(self, username: str) -> Optional[Dict]:
        """Get user info."""
        if not self._user_exists(username):
            return None
        return self.users[username]

    def group_info(self, group_id: str) -> Optional[Dict]:
        """Get group info."""
        if not self._group_exists(group_id):
            return None
        return self.groups[group_id]

    def is_admin(self, username: str) -> bool:
        """Check if user is admin."""
        return username == ADMIN_USER or self.users.get(username, {}).get("group") == "admin"


# --- CLI Interface ---
def main():
    fs = UserGroupFS()
    fs._ensure_admin_exists()
    fs._ensure_admin_group_exists()

    print("=== User Group File Management System ===")
    print("Commands:")
    print("  create_group <id> <name>")
    print("  delete_group <id>")
    print("  list_groups")
    print("  list_users")
    print("  create_user <username> <email> <group_id>")
    print("  delete_user <username>")
    print("  assign_user <username> <group_id>  (admin only)")
    print("  upload <username> <filename> <content>")
    print("  download <username> <filename>")
    print("  list_files <username>")
    print("  list_group_files <username>")
    print("  list_group_users <username>")
    print("  info_user <username>")
    print("  info_group <group_id>")
    print("  is_admin <username>")
    print("  help")
    print("  quit")

    while True:
        try:
            line = input("\n> ").strip()
            if not line:
                continue
            parts = line.split(maxsplit=3)
            cmd = parts[0].lower()
            args = parts[1:]

            if cmd == "create_group":
                if len(args) < 2:
                    print("Usage: create_group <id> <name>")
                    continue
                if fs.create_group(args[0], args[1]):
                    print(f"Group '{args[0]}' created.")
                else:
                    print(f"Group '{args[0]}' already exists.")

            elif cmd == "delete_group":
                if len(args) < 1:
                    print("Usage: delete_group <id>")
                    continue
                if fs.delete_group(args[0]):
                    print(f"Group '{args[0]}' deleted.")
                else:
                    print(f"Group '{args[0]}' does not exist or is admin group.")

            elif cmd == "list_groups":
                groups = fs.list_groups()
                if not groups:
                    print("No groups.")
                else:
                    for g in groups:
                        print(f"  {g['id']} - {g['name']}")

            elif cmd == "list_users":
                users = fs.list_users()
                if not users:
                    print("No users.")
                else:
                    for u in users:
                        print(f"  {u['username']} -> group {u['group']}")

            elif cmd == "create_user":
                if len(args) < 3:
                    print("Usage: create_user <username> <email> <group_id>")
                    continue
                if fs.create_user(args[0], args[1], args[2]):
                    print(f"User '{args[0]}' created in group '{args[2]}'.")
                else:
                    print(f"User '{args[0]}' already exists.")

            elif cmd == "delete_user":
                if len(args) < 1:
                    print("Usage: delete_user <username>")
                    continue
                if fs.delete_user(args[0]):
                    print(f"User '{args[0]}' deleted.")
                else:
                    print(f"User '{args[0]}' does not exist.")

            elif cmd == "assign_user":
                if len(args) < 2:
                    print("Usage: assign_user <username> <group_id>")
                    continue
                if fs.assign_user_to_group(args[0], args[1]):
                    print(f"User '{args[0]}' reassigned to group '{args[1]}'.")
                else:
                    print(f"Cannot reassign user '{args[0]}'.")

            elif cmd == "upload":
                if len(args) < 3:
                    print("Usage: upload <username> <filename> <content>")
                    continue
                content = args[2].encode("utf-8")
                if fs.upload_file(args[0], args[1], content):
                    print(f"File '{args[1]}' uploaded for '{args[0]}'.")
                else:
                    print(f"Upload failed for '{args[0]}'.")

            elif cmd == "download":
                if len(args) < 2:
                    print("Usage: download <username> <filename>")
                    continue
                data = fs.download_file(args[0], args[1])
                if data is None:
                    print(f"File '{args[1]}' not found for '{args[0]}'.")
                else:
                    print(f"Downloaded {len(data)} bytes. (Binary data)")

            elif cmd == "list_files":
                if len(args) < 1:
                    print("Usage: list_files <username>")
                    continue
                files = fs.list_user_files(args[0])
                if not files:
                    print(f"No files for '{args[0]}'.")
                else:
                    for f in files:
                        print(f"  {f}")

            elif cmd == "list_group_files":
                if len(args) < 1:
                    print("Usage: list_group_files <username>")
                    continue
                files = fs.list_user_group_files(args[0])
                if not files:
                    print(f"No group files for '{args[0]}'.")
                else:
                    for f in files:
                        print(f"  {f}")

            elif cmd == "list_group_users":
                if len(args) < 1:
                    print("Usage: list_group_users <username>")
                    continue
                users = fs.list_user_group_users(args[0])
                if not users:
                    print(f"No other users in group for '{args[0]}'.")
                else:
                    for u in users:
                        print(f"  {u}")

            elif cmd == "info_user":
                if len(args) < 1:
                    print("Usage: info_user <username>")
                    continue
                info = fs.user_info(args[0])
                if info is None:
                    print(f"User '{args[0]}' not found.")
                else:
                    print(json.dumps(info, indent=2))

            elif cmd == "info_group":
                if len(args) < 1:
                    print("Usage: info_group <group_id>")
                    continue
                info = fs.group_info(args[0])
                if info is None:
                    print(f"Group '{args[0]}' not found.")
                else:
                    print(json.dumps(info, indent=2))

            elif cmd == "is_admin":
                if len(args) < 1:
                    print("Usage: is_admin <username>")
                    continue
                if fs.is_admin(args[0]):
                    print(f"User '{args[0]}' is admin.")
                else:
                    print(f"User '{args[0]}' is not admin.")

            elif cmd == "help":
                print("See top of script for commands.")

            elif cmd == "quit":
                print("Goodbye!")
                break

            else:
                print(f"Unknown command: {cmd}")

        except KeyboardInterrupt:
            print("\n\nInterrupted. Goodbye!")
            break
        except Exception as e:
            print(f"Error: {e}")


if __name__ == "__main__":
    main()
```

