## 📦 How to Export Real Video (Node.js + FFmpeg)

Install Node.js, then install `ffmpeg-static`:

```bash
npm install ffmpeg-static
```

Then run the demo in a Node.js environment (e.g., create a `server.js`):

```javascript
const { spawn } = require('child_process');
const fs = require('fs').promises;

const ffmpeg = require('ffmpeg-static');

const TOTAL_SECONDS = 120;
const FPS = 30;
const TOTAL_FRAMES = TOTAL_SECONDS * FPS;

const W = 720, H = 405;

const state = {
  clips: [
    { id: 'c1', name: 'Sunset', color: '#ff7755', duration: 30 },
    { id: 'c2', name: 'Ocean', color: '#4a99ff', duration: 45 },
    { id: 'c3', name: 'Mountain', color: '#66cc66', duration: 35 },
    { id: 'c4', name: 'Desert', color: '#e6a84a', duration: 40 },
  ],
  timeline: [
    { id: 'c1', start: 0, end: 30, transition: 'fade', duration: 15 },
    { id: 'c2', start: 30, end: 75, transition: 'dissolve', duration: 20 },
    { id: 'c3', start: 75, end: 110, transition: 'slide', duration: 10 },
    { id: 'c4', start: 110, end: 150, transition: 'wipe', duration: 15 },
  ],
};

async function generateFrames() {
  const dir = 'frames';
  await fs.mkdir(dir, { recursive: true });
  const promises = [];
  for (let f = 0; f < TOTAL_FRAMES; f++) {
    const p = new Promise((resolve, reject) => {
      const canvas = document.createElement('canvas');
      canvas.width = W; canvas.height = H;
      const ctx = canvas.getContext('2d');
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, W, H);

      const clipIdx = state.clips.findIndex(c => f < c.duration);
      const clip = clipIdx >= 0 ? state.clips[clipIdx] : null;
      if (!clip) { ctx.fillStyle = '#000'; ctx.fillRect(0, 0, W, H); }
      else {
        const prevClip = state.clips[clipIdx - 1];
        const nextClip = state.clips[clipIdx + 1];
        const clipStart = prevClip ? prevClip.duration : 0;
        const clipEnd = clip.duration;
        const clipDuration = clipEnd - clipStart;
        const clipRatio = clipDuration / TOTAL_SECONDS;
        const clipWidth = W * clipRatio;
        const clipX = (clipStart / TOTAL_SECONDS) * W;
        const transition = state.timeline.find(t => t.id === clip.id)?.transition;
        const transitionDur = state.timeline.find(t => t.id === clip.id)?.duration || 0;
        const clipStartFrame = clipStart * FPS;
        const clipEndFrame = clipStartFrame + clipDuration * FPS;
        const currentClipFrame = f - clipStartFrame;
        const prevClipStartFrame = prevClip ? prevClip.duration * FPS : -1;
        const prevClipEndFrame = prevClip ? (prevClip.duration + clipDuration) * FPS : -1;
        const prevClipCurrentFrame = f - prevClipStartFrame;

        if (prevClip && prevClipStartFrame < f && f < prevClipEndFrame) {
          const prevRatio = transition ? Math.min(1, currentClipFrame / transitionDur) : 1;
          const prevColor = prevClip.color;
          const prevW = W * (prevClip.duration / TOTAL_SECONDS);
          const prevX = (prevClip.duration / TOTAL_SECONDS) * W;
          const prevY = (H - prevW) / 2;
          const rect = new Path2D();
          rect.rect(prevX, prevY, prevW, prevW);
          ctx.fillStyle = prevColor + (prevRatio < 1 ? '88' : 'ff');
          ctx.fill(rect);
        }
        if (transition) {
          const ratio = Math.min(1, currentClipFrame / transitionDur);
          const rect = new Path2D();
          rect.rect(clipX, (H - clipWidth) / 2, clipWidth, clipWidth);
          ctx.fillStyle = clip.color + (ratio < 1 ? '88' : 'ff');
          ctx.fill(rect);
        }
        if (nextClip && clipEndFrame < f && f < (clipEnd + nextClip.duration) * FPS) {
          const nextRatio = transition ? Math.min(1, (f - clipEndFrame) / transitionDur) : 1;
          const nextColor = nextClip.color;
          const nextW = W * (nextClip.duration / TOTAL_SECONDS);
          const nextX = ((clip.duration + nextClip.duration) / TOTAL_SECONDS) * W;
          const nextY = (H - nextW) / 2;
          const rect = new Path2D();
          rect.rect(nextX, nextY, nextW, nextW);
          ctx.fillStyle = nextColor + (nextRatio < 1 ? '88' : 'ff');
          ctx.fill(rect);
        }
      }
      canvas.toBlob(resolve, 'image/png');
    });
    promises.push(p);
  }
  await Promise.all(promises);
  for (let i = 0; i < promises.length; i++) {
    const blob = await promises[i];
    await fs.writeFile(`${dir}/frame_${String(i).padStart(4, '0')}.png`, await blob.arrayBuffer());
  }
}

async function runFFmpeg() {
  const cmd = [
    ffmpeg,
    '-y',
    '-framerate', String(FPS),
    '-i', 'frames/frame_%04d.png',
    '-c:v', 'libx264',
    '-pix_fmt', 'yuv420p',
    'output.mp4',
  ];
  const proc = spawn(cmd[0], cmd.slice(1));
  proc.stdout.on('data', (d) => process.stdout.write(d));
  proc.stderr.on('data', (d) => process.stderr.write(d));
  proc.on('close', (code) => {
    console.log(`FFmpeg exited with code ${code}`);
  });
}

async function main() {
  await generateFrames();
  await runFFmpeg();
}

main().catch(console.error);
```

---

## ✅ Summary

This editor lets you:

- Add clips (simulated colored rectangles)
- Drag them on a timeline
- Apply transition effects (fade, dissolve, slide, wipe)
- Adjust transition duration
- Preview the sequence frame-by-frame
- Export frames to PNG and stitch with FFmpeg into a real MP4

Perfect for prototyping transitions before committing to real footage!

Let me know if you want a version that actually uses real video files! 🎥

