      <h2 id="modalTitle">Download Annotated Images</h2>
      <p id="modalText">Click "Download" to save all annotated images as PNG files.</p>
      <div class="modal-actions">
        <button class="btn" id="modalCancel">Cancel</button>
        <button class="btn primary" id="modalConfirm"><i class="fa-solid fa-check"></i> Download</button>
