  <script>
    // ---------- State ----------
    const state = {
      images: [],          // { id, file, url, annotations: [{id, text, x, y, w, h}] }
      nextId: 1,
      nextAnnotId: 1,
    };

    // ---------- DOM ----------
    const $ = (sel) => document.querySelector(sel);
    const uploadArea = $('#uploadArea');
    const fileInput = $('#fileInput');
    const imageGrid = $('#imageGrid');
    const emptyState = $('#emptyState');
    const clearBtn = $('#clearBtn');
    const downloadBtn = $('#downloadBtn');
    const modalBackdrop = $('#modalBackdrop');
    const modalTitle = $('#modalTitle');
    const modalText = $('#modalText');
    const modalConfirm = $('#modalConfirm');
    const modalCancel = $('#modalCancel');
    const toast = $('#toast');

    // ---------- Helpers ----------
    const uid = () => 'a_' + (state.nextAnnotId++);
    const imgId = () => 'img_' + (state.nextId++);

    const showToast = (msg) => {
      toast.textContent = msg;
      toast.classList.add('show');
      clearTimeout(showToast._t);
      showToast._t = setTimeout(() => toast.classList.remove('show'), 2200);
    };

    const setStatus = () => {
      $('#statusCount').textContent = state.images.length;
    };

    // ---------- Image loading ----------
    const loadImage = (file) => {
      return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = (e) => {
          const img = new Image();
          img.onload = () => resolve(img);
          img.onerror = () => reject(new Error('Failed to decode image'));
          img.src = e.target.result;
        };
        reader.onerror = () => reject(reader.error);
        reader.readAsDataURL(file);
      });
    };

    const addImage = async (file) => {
      if (!file.type.startsWith('image/')) {
        showToast('Please upload a valid image file.');
        return;
      }
      if (file.size > 10 * 1024 * 1024) {
        showToast('Image exceeds 10MB limit.');
        return;
      }
      try {
        const img = await loadImage(file);
        const id = imgId();
        state.images.push({
          id,
          file,
          url: img.src,
          annotations: [],
        });
        render();
      } catch (err) {
        showToast('Failed to load image: ' + err.message);
      }
    };

    // ---------- Rendering ----------
    const render = () => {
      imageGrid.innerHTML = '';
      if (state.images.length === 0) {
        emptyState.style.display = 'grid';
        return;
      }
      emptyState.style.display = 'none';
      state.images.forEach((img) => imageGrid.appendChild(createImageCard(img)));
      setStatus();
      clearBtn.disabled = state.images.length === 0;
      downloadBtn.disabled = state.images.length === 0;
    };

    const createImageCard = (img) => {
      const card = document.createElement('article');
      card.className = 'image-card';
      card.dataset.id = img.id;
      card.draggable = true;
      card.innerHTML = `
        <div class="image-actions">
          <button class="btn" title="Delete image" data-action="delete"><i class="fa-solid fa-trash"></i></button>
          <button class="btn" title="Move image" data-action="move"><i class="fa-solid fa-arrows"></i></button>
        </div>
        <div class="image-preview">
          <img src="${img.url}" alt="Image preview" />
          <div class="annotation-layer" id="layer_${img.id}"></div>
        </div>
      `;

      // Delete
      card.querySelector('[data-action="delete"]').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteImage(img.id);
      });

      // Move (drag image between cards)
      card.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', img.id);
        e.dataTransfer.effectAllowed = 'move';
        card.classList.add('dragging');
      });
      card.addEventListener('dragend', () => card.classList.remove('dragging'));

      // Reorder on drop
      card.addEventListener('dragover', (e) => {
        e.preventDefault();
        e.dataTransfer.dropEffect = 'move';
      });
      card.addEventListener('drop', (e) => {
        e.preventDefault();
        const draggedId = e.dataTransfer.getData('text/plain');
        if (draggedId !== img.id) {
          const fromIdx = state.images.findIndex(i => i.id === draggedId);
          const toIdx = state.images.findIndex(i => i.id === img.id);
          if (fromIdx >= 0 && toIdx >= 0 && fromIdx !== toIdx) {
            state.images.splice(toIdx, 1);
            state.images.splice(fromIdx, 0, img);
            render();
          }
        }
      });

      // Annotations
      img.annotations.forEach((a) => {
        const layer = card.querySelector(`#layer_${img.id}`);
        const el = document.createElement('div');
        el.className = 'annotation';
        el.dataset.annotId = a.id;
        el.textContent = a.text;
        el.style.left = a.x + 'px';
        el.style.top = a.y + 'px';
        el.style.width = a.w + 'px';
        el.style.height = a.h + 'px';
        el.innerHTML += `<span class="handle"></span>`;
        el.addEventListener('mousedown', (e) => {
          e.stopPropagation();
          startDragAnnotation(el, a, e);
        });
        layer.appendChild(el);
      });

      // Add annotation button
      card.querySelector('.image-preview').addEventListener('click', (e) => {
        if (e.target.closest('.annotation') || e.target.closest('.image-actions')) return;
        addAnnotationToCard(img.id);
      });

      return card;
    };

    // ---------- Annotations ----------
    const addAnnotationToCard = (imgId) => {
      const img = state.images.find(i => i.id === imgId);
      if (!img) return;
      const a = { id: uid(), text: 'Annotation', x: 20, y: 20, w: 120, h: 30 };
      img.annotations.push(a);
      render();
      setTimeout(() => {
        const card = imageGrid.querySelector(`[data-id="${imgId}"]`);
        const layer = card.querySelector(`#layer_${imgId}`);
        const el = layer.querySelector(`[data-annot-id="${a.id}"]`);
        if (el) el.scrollIntoView({ block: 'center', behavior: 'smooth' });
      }, 100);
    };

    const deleteImage = (imgId) => {
      state.images = state.images.filter(i => i.id !== imgId);
      render();
      showToast('Image deleted');
    };

    const deleteAnnotation = (imgId, annotId) => {
      const img = state.images.find(i => i.id === imgId);
      if (!img) return;
      img.annotations = img.annotations.filter(a => a.id !== annotId);
      render();
    };

    const startDragAnnotation = (el, a, e) => {
      const startX = e.clientX;
      const startY = e.clientY;
      const origX = a.x;
      const origY = a.y;

      const move = (ev) => {
        const dx = ev.clientX - startX;
        const dy = ev.clientY - startY;
        a.x = Math.max(0, origX + dx);
        a.y = Math.max(0, origY + dy);
        el.style.left = a.x + 'px';
        el.style.top = a.y + 'px';
      };

      const up = (ev) => {
        document.removeEventListener('mousemove', move);
        document.removeEventListener('mouseup', up);
        render();
      };

      document.addEventListener('mousemove', move);
      document.addEventListener('mouseup', up);
    };

    // ---------- Download ----------
    const downloadAnnotatedImages = async () => {
      if (state.images.length === 0) return;
      modalTitle.textContent = 'Preparing download';
      modalText.textContent = 'Generating annotated PNG files. This may take a moment.';
      modalConfirm.disabled = true;
      modalConfirm.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Preparing...';

      const images = await Promise.all(state.images.map(async (img) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        const imgEl = new Image();
        imgEl.src = img.url;
        await new Promise((res, rej) => { imgEl.onload = res; imgEl.onerror = rej; });

        // Auto-fit canvas to image
        const dpr = window.devicePixelRatio || 1;
        canvas.width = imgEl.width * dpr;
        canvas.height = imgEl.height * dpr;
        canvas.style.width = imgEl.width + 'px';
        canvas.style.height = imgEl.height + 'px';
        canvas.getContext('2d').setTransform(dpr, 0, 0, dpr, 0, 0);

        ctx.drawImage(imgEl, 0, 0);

        img.annotations.forEach((a) => {
          ctx.fillStyle = '#1e293b';
          ctx.strokeStyle = 'rgba(255,255,255,0.15)';
          ctx.lineWidth = 1.5;
          ctx.font = '12px system-ui, sans-serif';
          ctx.textAlign = 'left';
          ctx.textBaseline = 'top';
          ctx.fillRect(a.x, a.y, a.w, a.h);
          ctx.strokeRect(a.x, a.y, a.w, a.h);
          ctx.fillStyle = '#ffffff';
          ctx.fillText(a.text, a.x + 6, a.y + 14);
        });

        return canvas;
      }));

      modalTitle.textContent = 'Ready to download';
      modalText.textContent = 'Click "Download" to save all annotated images as PNG files.';
      modalConfirm.disabled = false;
      modalConfirm.innerHTML = '<i class="fa-solid fa-check"></i> Download';

      setTimeout(() => {
        downloadImages(images);
      }, 400);
    };

    const downloadImages = (canvases) => {
      const zip = new JSZip();
      canvases.forEach((canvas, i) => {
        const blob = canvas.toBlob();
        zip.file(`annotated-${String(i + 1).padStart(3, '0')}.png`, blob, { base64: true });
      });
      zip.generateAsync({ type: 'blob' }).then((blob) => {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `batch-annotations-${new Date().toISOString().slice(0, 10)}.zip`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
        showToast('Download started');
      });
    };

    // ---------- Modal ----------
    const openModal = () => { modalBackdrop.hidden = false; };
    const closeModal = () => { modalBackdrop.hidden = true; };

    // ---------- Upload ----------
    const handleFiles = (files) => {
      Array.from(files).forEach((file) => addImage(file));
    };

    uploadArea.addEventListener('click', () => fileInput.click());
    uploadArea.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); fileInput.click(); }
    });
    fileInput.addEventListener('change', (e) => handleFiles(e.target.files));
    ['dragenter', 'dragover'].forEach((ev) => {
      uploadArea.addEventListener(ev, (e) => {
        e.preventDefault();
        e.stopPropagation();
        uploadArea.classList.add('dragover');
      });
    });
    ['dragleave', 'drop'].forEach((ev) => {
      uploadArea.addEventListener(ev, (e) => {
        e.preventDefault();
        e.stopPropagation();
        uploadArea.classList.remove('dragover');
      });
    });
    uploadArea.addEventListener('drop', (e) => {
      handleFiles(e.dataTransfer.files);
    });

    imageGrid.addEventListener('dragover', (e) => {
      e.preventDefault();
      e.dataTransfer.dropEffect = 'move';
    });
    imageGrid.addEventListener('drop', (e) => {
      e.preventDefault();
      const id = e.dataTransfer.getData('text/plain');
      if (id) {
        const fromIdx = state.images.findIndex(i => i.id === id);
        if (fromIdx >= 0) {
          const moved = state.images.splice(fromIdx, 1)[0];
          state.images.push(moved);
          render();
        }
      }
    });

    clearBtn.addEventListener('click', () => {
      if (state.images.length === 0) return;
      if (!confirm('Delete all images and annotations?')) return;
      state.images = [];
      render();
      showToast('All cleared');
    });

    downloadBtn.addEventListener('click', downloadAnnotatedImages);
    modalConfirm.addEventListener('click', () => {
      downloadAnnotatedImages();
      closeModal();
    });
    modalCancel.addEventListener('click', closeModal);
    modalBackdrop.addEventListener('click', (e) => {
      if (e.target === modalBackdrop) closeModal();
    });
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && !modalBackdrop.hidden) closeModal();
    });

    // ---------- Init ----------
    render();
  </script>

  <!-- JSZip required for download -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script>
</body>
</html>
```

Creating a professional **video subtitle adding tool** with timeline markers, customizable fonts/colors/positions, and embedded subtitle export requires a combination of a frontend (HTML/CSS/JS) for the UI and a backend (Node.js) for handling uploads and video processing. Below is a **complete end-to-end implementation** using **Electron** (desktop app) for cross-platform desktop delivery, with **FFmpeg** for video processing and **WebVTT** for subtitle embedding.

---

## ✅ Features

- Upload a video file.
- Drag-drop or browse to select a video.
- Add multiple captions using a timeline with markers (start/end time).
- Customize font, color, position, and background opacity per subtitle.
- Preview the video with subtitles overlaid.
- Export final video with embedded subtitles (WebVTT).
- Save/export project as `.zip` with video + `.vtt` file.

---

## 📦 Tech Stack

- **Frontend**: HTML, CSS, JavaScript (vanilla + Web Audio API for seeking)
- **Backend**: Node.js + Express + FFmpeg
- **Electron**: Desktop wrapper
- **FFmpeg**: Video processing
- **WebVTT**: Subtitle format
- **WebVTT.js** (optional): WebVTT parser for preview
- **Electron-Webview** or **Electron-Renderer** for video preview

