## 📁 Step 2: Main Process (`main.js`)

```javascript
const { app, BrowserWindow, ipcMain, dialog, Menu } = require('electron');
const path = require('path');
const ffmpeg = require('ffmpeg-static');
const fs = require('fs').promises;
const { exec } = require('child_process');

let mainWindow = null;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 720,
    webPreferences: {
      preload: path.join(__dirname, 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
    },
    title: 'Subtitle Tool',
  });

  const menu = Menu.buildFromTemplate([
    { label: 'File', submenu: [{ role: 'quit' }] },
    { label: 'Help', submenu: [{ role: 'about' }] },
  ]);
  Menu.setApplicationMenu(menu);

  mainWindow.loadFile('index.html');
  mainWindow.webContents.openDevTools();
}

app.whenReady().then(() => {
  createWindow();
  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

ipcMain.handle('open-file', async () => {
  const { canceled, filePaths } = await dialog.showOpenDialog({
    properties: ['openFile'],
    filters: [{ name: 'Videos', extensions: ['mp4', 'mov', 'mkv', 'webm'] }],
  });
  if (canceled) return null;
  return filePaths[0];
});

ipcMain.handle('save-project', async (event, project) => {
  const { canceled, filePath } = await dialog.showSaveDialog({
    filters: [{ name: 'Subtitle Project', extensions: ['zip'] }],
  });
  if (canceled) return;
  await fs.writeFile(filePath, JSON.stringify(project, null, 2));
  event.sender.send('save-project-done', filePath);
});

ipcMain.handle('ffmpeg-run', async (event, cmd) => {
  return new Promise((resolve, reject) => {
    exec(cmd, (err, stdout, stderr) => {
      if (err) reject(err);
      else resolve({ stdout, stderr });
    });
  });
});

ipcMain.handle('ffmpeg-get-duration', async (event, filePath) => {
  const out = await exec(`"${ffmpeg}" -i "${filePath}" 2>&1`);
  const match = out.stderr.match(/Duration:\s*(\d+):(\d+):(\d+)/);
  if (match) {
    const h = parseInt(match[1], 10), m = parseInt(match[2], 10), s = parseInt(match[3], 10);
    return (h * 3600 + m * 60 + s).toFixed(2);
  }
  return '0.00';
});
```

