## 📁 Step 7: App Logic (`app.js`)

```javascript
(() => {
  'use strict';

  const state = {
    videoPath: null,
    subtitles: [],
    currentSubtitleIndex: -1,
    videoDuration: 0,
    videoEl: null,
    overlayEl: null,
    playbackRate: 1,
  };

  const fontFamilies = [
    'Arial', 'Helvetica', 'Impact', 'Georgia', 'Courier New',
    'Verdana', 'Tahoma', 'Roboto', 'Segoe UI', 'Nunito',
    'Inter', 'Open Sans', 'Lato', 'Poppins', 'Montserrat',
    'Oswald', 'Rajdhani', 'Cormorant Garamond',
  ];

  // ---------- File handling ----------
  document.getElementById('btn-upload').addEventListener('click', async () => {
    const path = await window.electronAPI.openFile();
    if (!path) return;
    state.videoPath = path;
    document.getElementById('file-name').textContent = path.split('/').pop().split('\\').pop();
    const dur = await window.electronAPI.ffmpegGetDuration(path);
    document.getElementById('file-duration').textContent = dur;
    state.videoDuration = parseFloat(dur);
    await loadVideo(path);
    document.getElementById('btn-export').disabled = false;
    renderSubtitles();
  });

  async function loadVideo(path) {
    state.videoEl = document.getElementById('video');
    state.overlayEl = document.getElementById('subtitle-overlay');
    state.videoEl.src = path;
    state.videoEl.load();
    await new Promise((r) => state.videoEl.addEventListener('loadedmetadata', r, { once: true }));
    state.videoEl.playbackRate = state.playbackRate;
    state.videoEl.currentTime = 0;
    renderSubtitles();
  }

  // ---------- Subtitle management ----------
  function addSubtitle() {
    const idx = state.subtitles.length;
    state.subtitles.push({
      id: Date.now() + '-' + Math.random().toString(36).slice(2, 7),
      start: 0,
      end: state.videoDuration || 60,
      text: '',
      font: 'Inter',
      color: '#ffffff',
      position: 'bottom-center',
      opacity: 80,
      background: true,
    });
    state.currentSubtitleIndex = idx;
    renderSubtitles();
    state.videoEl.currentTime = 0;
    state.videoEl.playbackRate = state.playbackRate;
    state.videoEl.play();
  }

  document.getElementById('btn-add').addEventListener('click', addSubtitle);

  function deleteSubtitle(id) {
    state.subtitles = state.subtitles.filter(s => s.id !== id);
    if (state.currentSubtitleIndex >= state.subtitles.length) state.currentSubtitleIndex = Math.max(0, state.subtitles.length - 1);
    renderSubtitles();
  }

  function updateSubtitle(id, field, value) {
    const s = state.subtitles.find(x => x.id === id);
    if (!s) return;
    s[field] = value;
    renderSubtitles();
  }

  function renderSubtitles() {
    const list = document.getElementById('subtitle-list');
    list.innerHTML = '';
    state.subtitles.forEach((s, i) => {
      const el = document.createElement('div');
      el.className = 'subtitle-item' + (i === state.currentSubtitleIndex ? ' selected' : '');
      el.innerHTML = `
        <span class="time">${formatTime(s.start)} → ${formatTime(s.end)}</span>
        <span class="text">${escapeHtml(s.text || 'Click to edit')}</span>
      `;
      el.addEventListener('click', () => selectSubtitle(i));
      list.appendChild(el);
    });
  }

  function selectSubtitle(i) {
    state.currentSubtitleIndex = i;
    renderSubtitles();
  }

  // ---------- UI bindings ----------
  const fontSelect = document.getElementById('font-select');
  fontFamilies.forEach(f => fontSelect.add(new Option(f, f)));

  const colorSelect = document.getElementById('color-select');
  colorSelect.addEventListener('input', (e) => updateSubtitle(state.subtitles[state.currentSubtitleIndex].id, 'color', e.target.value));

  const positionSelect = document.getElementById('position-select');
  positionSelect.addEventListener('change', (e) => updateSubtitle(state.subtitles[state.currentSubtitleIndex].id, 'position', e.target.value));

  const opacitySlider = document.getElementById('opacity-slider');
  const opacityValue = document.getElementById('opacity-value');
  opacitySlider.addEventListener('input', (e) => {
    updateSubtitle(state.subtitles[state.currentSubtitleIndex].id, 'opacity', parseInt(e.target.value, 10));
    opacityValue.textContent = e.target.value + '%';
  });

  // ---------- Preview rendering ----------
  function formatTime(sec) {
    const h = Math.floor(sec / 3600);
    const m = Math.floor((sec % 3600) / 60);
    const s = Math.floor(sec % 60);
    return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;
  }

  function escapeHtml(str) {
    return String(str).replace(/[&<>"']/g, c => ({
      '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
    }[c]));
  }

  function renderOverlay() {
    const now = state.videoEl.currentTime;
    const active = state.subtitles.find(s => now >= s.start && now < s.end);
    if (!active) {
      state.overlayEl.innerHTML = '';
      return;
    }
    const s = active;
    const rect = state.videoEl.getBoundingClientRect();
    const size = rect.width;
    const topOffset = 24;
    const bottomOffset = 24;
    const lineH = 36;

    const position = s.position;
    let left = 0, top = 0;
    if (position.startsWith('top')) {
      top = topOffset;
    } else {
      top = rect.height - bottomOffset - lineH;
    }
    if (position.includes('left')) {
      left = 24;
    } else if (position.includes('center')) {
      left = (rect.width - size * 0.9) / 2;
    } else {
      left = rect.width - size * 0.9 - 24;
    }

    const sub = document.createElement('div');
    sub.className = 'sub';
    sub.style.left = left + 'px';
    sub.style.top = top + 'px';
    sub.style.fontSize = 'clamp(18px, 3vw, 26px)';
    sub.style.fontFamily = s.font;
    sub.style.color = s.color;
    sub.style.opacity = (s.opacity / 100).toFixed(2);
    sub.style.textShadow = '0 2px 8px rgba(0,0,0,0.5)';
    sub.style.background = s.background ? `rgba(0,0,0,${s.opacity / 1000})` : 'transparent';
    sub.style.padding = '10px 16px';
    sub.style.borderRadius = '6px';
    sub.style.lineHeight = '1.3';
    sub.textContent = s.text;
    state.overlayEl.appendChild(sub);
  }

  state.videoEl.addEventListener('timeupdate', renderOverlay);
  state.videoEl.addEventListener('play', () => state.playbackRate = state.videoEl.playbackRate);
  state.videoEl.addEventListener('ratechange', () => state.playbackRate = state.videoEl.playbackRate);
  state.videoEl.addEventListener('ended', () => {
    state.videoEl.currentTime = 0;
    state.videoEl.playbackRate = state.playbackRate;
    state.videoEl.play();
  });

  // ---------- Export ----------
  document.getElementById('btn-export').addEventListener('click', async () => {
    if (!state.videoPath) return;
    const vtt = generateVTT();
    const outPath = state.videoPath.replace(/\.[^.]+$/, '') + '_subtitles.vtt';
    await window.electronAPI.ffmpegRun([
      `"${ffmpeg}"`,
      '-i', `"${state.videoPath}"`,
      '-vf', `"drawtext=text='${escapeHtml(vtt)}':fontfile=DejaVuSans.ttf:fontsize=24:fontcolor=white:shadowcolor=black:shadowx=2:shadowy=2:box=1:boxcolor=black@0.5:boxborderw=2:x=(w-text_w)/2:y=(h-text_h)/2"`,
      '-c:a', 'copy',
      outPath,
    ].join(' '));
    const project = {
      video: state.videoPath,
      subtitles: state.subtitles,
      createdAt: new Date().toISOString(),
    };
    const zipPath = await window.electronAPI.saveProject(project);
    alert(`Exported: ${outPath}\nProject saved: ${zipPath}`);
  });

  function generateVTT() {
    const subs = state.subtitles.map(s => {
      const t = formatTime(s.start);
      return `${t} --> ${formatTime(s.end)}\n${escapeHtml(s.text)}\n`;
    }).join('\n');
    return `WEBVTT\n\n${subs}`;
  }

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Delete' && state.currentSubtitleIndex >= 0) {
      deleteSubtitle(state.subtitles[state.currentSubtitleIndex].id);
      e.preventDefault();
    }
  });
})();
```

