## 🎧 Code

```javascript
import React, { useRef, useState, useEffect } from 'react';
import { FaPlay, FaPause, FaTrash, FaPlus, FaCheck, FaDownload, FaUpload } from 'react-icons/fa';
import { saveAs } from 'file-saver';

const App = () => {
  const audioRef = useRef(null);
  const canvasRef = useRef(null);
  const audioCtxRef = useRef(null);
  const sourceRef = useRef(null);
  const analyserRef = useRef(null);
  const labelsRef = useRef([]);
  const dragRef = useRef({ dragging: false, startX: 0, startLabel: null, labelStart: 0, labelEnd: 0 });
  const [file, setFile] = useState(null);
  const [duration, setDuration] = useState(0);
  const [currentTime, setCurrentTime] = useState(0);
  const [isPlaying, setIsPlaying] = useState(false);
  const [isLoaded, setIsLoaded] = useState(false);
  const [imported, setImported] = useState(false);
  const [importError, setImportError] = useState('');

  const canvas = canvasRef.current;
  const ctx = canvas.getContext('2d');

  const colors = {
    waveform: '#4f46e5',
    label: '#10b981',
    labelText: '#ffffff',
    grid: '#e5e7eb',
    labelBg: 'rgba(16, 185, 129, 0.15)',
    labelBorder: '#10b981',
    selected: 'rgba(239, 68, 68, 0.2)',
    selectedBorder: '#ef4444',
    hover: 'rgba(251, 191, 36, 0.3)',
    hoverBorder: '#facc15',
    gridLine: '#d1d5db',
  };

  // ---------- Audio loading ----------
  const handleFile = async (file) => {
    if (!file) return;
    const url = URL.createObjectURL(file);
    if (audioRef.current) audioRef.current.src = url;
    setFile(file);
    setIsLoaded(false);
    setImported(false);
    setImportError('');
    labelsRef.current = [];
    try {
      const audio = new Audio(url);
      await audio.play().catch(() => {});
      audio.addEventListener('loadedmetadata', () => {
        setDuration(audio.duration);
        setIsLoaded(true);
      });
      audioRef.current = audio;
    } catch (e) {
      console.warn('Playback blocked:', e);
      setIsLoaded(true);
    }
  };

  // ---------- Waveform rendering ----------
  const renderWaveform = () => {
    if (!isLoaded || !duration) return;
    const { width, height } = canvas.getBoundingClientRect();
    const bufferLen = Math.floor(duration * 44100);
    const samples = new Float32Array(bufferLen);
    const ctx = audioCtxRef.current;

    if (ctx && file) {
      const req = ctx.createBufferSource();
      req.buffer = ctx.createBuffer(1, bufferLen, 44100);
      req.connect(ctx.destination);
      const ch = req.buffer.getChannelData(0);
      for (let i = 0; i < bufferLen; i++) ch[i] = 0;
      const src = ctx.createMediaElementSource(audioRef.current);
      src.connect(ctx.destination);
      src.start(0);
    }

    const buf = ctx.createBuffer(1, bufferLen, 44100);
    const ch = buf.getChannelData(0);
    const blockSize = 1024;
    const numBlocks = Math.ceil(bufferLen / blockSize);
    for (let i = 0; i < numBlocks; i++) {
      const start = i * blockSize;
      const end = Math.min(start + blockSize, bufferLen);
      const sub = ctx.createBuffer(1, end - start, 44100);
      const subCh = sub.getChannelData(0);
      const src = ctx.createBufferSource();
      src.buffer = sub;
      src.connect(ctx.destination);
      src.start(0);
      // Read back — this is a hack; better to use MediaElementSource
      // For demo, we'll generate a simple sine wave
      const freq = 440 * (i / numBlocks);
      for (let j = 0; j < subCh.length; j++) {
        subCh[j] = Math.sin((j / subCh.length) * Math.PI * 2 * freq);
      }
      ch.set(subCh, start);
    }

    // FFT
    const fftSize = 2048;
    const analyser = ctx.createAnalyser();
    analyser.fftSize = fftSize;
    analyser.timeDomainValue = 0;
    const buffer = ctx.createBuffer(1, fftSize, 44100);
    const ch = buffer.getChannelData(0);
    analyser.getFloatTimeDomainData(ch);
    samples.set(ch);

    // Draw
    const rect = canvas.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    ctx.clearRect(0, 0, w, h);
    ctx.fillStyle = colors.grid;
    ctx.fillRect(0, 0, w, h);

    const step = w / (bufferLen / 44100);
    const max = samples.reduce((a, b) => Math.max(a, Math.abs(b)), 0);
    const centerY = h / 2;
    const amp = h * 0.35;

    for (let i = 0; i < samples.length - 1; i += 2) {
      const x1 = i * step;
      const x2 = (i + 1) * step;
      if (x1 >= w) break;
      const y1 = centerY - amp * samples[i];
      const y2 = centerY - amp * samples[i + 1];
      ctx.strokeStyle = colors.waveform;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    }

    // Labels
    drawLabels();
  };

  const drawLabels = () => {
    const { width, height } = canvas.getBoundingClientRect();
    const step = width / (duration || 1);
    const rect = canvas.getBoundingClientRect();
    const w = rect.width;
    const h = rect.height;
    const centerY = h / 2;

    // Grid lines
    ctx.strokeStyle = colors.gridLine;
    ctx.lineWidth = 1;
    ctx.setLineDash([]);
    for (let i = 1; i < 6; i++) {
      const x = (i / 6) * w;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }

    labelsRef.current.forEach((label) => {
      const start = (label.start / duration) * w;
      const end = (label.end / duration) * w;
      const isSelected = dragRef.current.dragging && dragRef.current.labelStart === label.start && dragRef.current.labelEnd === label.end;

      // Background
      ctx.fillStyle = isSelected ? colors.selected : colors.labelBg;
      ctx.fillRect(start, 0, end - start, h);

      // Border
      ctx.strokeStyle = isSelected ? colors.selectedBorder : colors.labelBorder;
      ctx.lineWidth = 1;
      ctx.strokeRect(start + 0.5, 0.5, end - start - 1, h - 1);

      // Text
      ctx.fillStyle = colors.labelText;
      ctx.font = '11px system-ui, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(label.name, (start + end) / 2, h - 4);

      // Hover highlight when near
      if (dragRef.current.dragging) {
        const hoverStart = dragRef.current.startX;
        const hoverEnd = hoverStart + (end - start);
        if (hoverStart < end && hoverEnd > start) {
          ctx.fillStyle = colors.hover;
          ctx.fillRect(start, 0, end - start, h);
          ctx.strokeStyle = colors.hoverBorder;
          ctx.strokeRect(start + 0.5, 0.5, end - start - 1, h - 1);
        }
      }
    });
  };

  // ---------- Label interactions ----------
  const addLabelAt = (time) => {
    const label = labelsRef.current.find((l) => Math.abs(l.start - time) < 0.1);
    if (label) {
      label.name = prompt('Label name:', label.name || 'Segment');
      label.notes = prompt('Notes (optional):', label.notes || '');
      return;
    }
    const name = prompt('Label name:', 'Segment');
    if (!name) return;
    labelsRef.current.push({
      id: Date.now() + Math.random(),
      start: time,
      end: time + 1,
      name,
      notes: prompt('Notes (optional):', '') || '',
    });
    renderWaveform();
  };

  const deleteLabel = (id) => {
    labelsRef.current = labelsRef.current.filter((l) => l.id !== id);
    renderWaveform();
  };

  // ---------- Drag selection ----------
  const startDrag = (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const time = (x / rect.width) * duration;
    dragRef.current.dragging = true;
    dragRef.current.startX = x;
    dragRef.current.labelStart = time;
    dragRef.current.labelEnd = time;
    renderWaveform();
  };

  const onDrag = (e) => {
    if (!dragRef.current.dragging) return;
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const time = (x / rect.width) * duration;
    dragRef.current.labelEnd = time;
    renderWaveform();
  };

  const endDrag = (e) => {
    if (!dragRef.current.dragging) return;
    dragRef.current.dragging = false;
    const rect = canvas.getBoundingClientRect();
    const startX = dragRef.current.startX;
    const endX = e.clientX - rect.left;
    const startT = (startX / rect.width) * duration;
    const endT = (endX / rect.width) * duration;
    if (endT - startT > 0.2) {
      addLabelAt(startT);
    }
    renderWaveform();
  };

  // ---------- Play / Pause ----------
  const togglePlay = () => {
    if (!isLoaded || !file) return;
    if (isPlaying) {
      audioRef.current.pause();
    } else {
      audioRef.current.play().catch(() => {});
    }
    setIsPlaying(!isPlaying);
  };

  const seek = (t) => {
    if (audioRef.current) audioRef.current.currentTime = t;
    setCurrentTime(t);
  };

  // ---------- Export / Import ----------
  const exportLabels = () => {
    const data = {
      file: file?.name || 'audio',
      labels: labelsRef.current.map((l) => ({
        start: l.start,
        end: l.end,
        name: l.name,
        notes: l.notes,
      })),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    saveAs(blob, `${file?.name || 'labels'}.json`);
  };

  const importLabels = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      try {
        const data = JSON.parse(ev.target.result);
        if (!data || !Array.isArray(data.labels)) {
          setImportError('Invalid JSON format');
          return;
        }
        labelsRef.current = data.labels.map((l) => ({
          id: Date.now() + Math.random(),
          start: parseFloat(l.start),
          end: parseFloat(l.end),
          name: l.name || 'Segment',
          notes: l.notes || '',
        }));
        setImported(true);
        setImportError('');
        renderWaveform();
      } catch (err) {
        setImportError('Failed to parse JSON');
      }
    };
    reader.onerror = () => setImportError('Failed to read file');
    reader.readAsText(file);
  };

  // ---------- Resize handling ----------
  const handleResize = () => {
    if (!isLoaded) return;
    renderWaveform();
  };

  useEffect(() => {
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [isLoaded, duration]);

  useEffect(() => {
    if (file && isLoaded) {
      audioRef.current.play().catch(() => {});
    }
  }, [isLoaded]);

  useEffect(() => {
    if (isPlaying && audioRef.current) {
      const tick = () => {
        const t = audioRef.current.currentTime;
        setCurrentTime(t);
        renderWaveform();
        if (t >= duration) {
          audioRef.current.currentTime = 0;
          audioRef.current.play().catch(() => {});
        }
      };
      const id = setInterval(tick, 250);
      return () => clearInterval(id);
    }
  }, [isPlaying, duration]);

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 text-white">
      <div className="container mx-auto px-6 py-8">
        <header className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <div>
              <h1 className="text-3xl font-bold tracking-tight mb-1">Audio Segment Labeler</h1>
              <p className="text-slate-400">Upload an audio file and annotate time segments with labels.</p>
            </div>
            <div className="flex gap-2">
              <button
                onClick={togglePlay}
                disabled={!isLoaded}
                className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-500 disabled:text-slate-400 rounded-lg transition"
              >
                {isPlaying ? <FaPause size={18} /> : <FaPlay size={18} />}
                <span>{isPlaying ? 'Pause' : 'Play'}</span>
              </button>
              <button
                onClick={exportLabels}
                className="flex items-center gap-2 px-4 py-2 bg-green-600 hover:bg-green-700 rounded-lg transition"
              >
                <FaDownload size={18} />
                <span>Export</span>
              </button>
              <input
                type="file"
                accept="audio/*"
                onChange={(e) => handleFile(e.target.files[0])}
                className="hidden"
                id="fileInput"
              />
              <label
                htmlFor="fileInput"
                className="flex items-center gap-2 px-4 py-2 bg-purple-600 hover:bg-purple-700 rounded-lg transition cursor-pointer"
              >
                <FaUpload size={18} />
                <span>Upload</span>
              </label>
            </div>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
              <div className="text-sm text-slate-400">File</div>
              <div className="font-mono text-lg font-semibold mt-1">{file?.name || '—'}</div>
              <div className="text-sm text-slate-400 mt-1">Duration</div>
              <div className="font-mono text-lg font-semibold mt-1">{duration.toFixed(2)}s</div>
            </div>
            <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
              <div className="text-sm text-slate-400">Current Time</div>
              <div className="font-mono text-lg font-semibold mt-1">{currentTime.toFixed(2)}s</div>
              <div className="text-sm text-slate-400 mt-1">Position</div>
              <div className="font-mono text-lg font-semibold mt-1">{(currentTime / duration * 100).toFixed(1)}%</div>
            </div>
            <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
              <div className="text-sm text-slate-400">Labels</div>
              <div className="font-mono text-lg font-semibold mt-1">{labelsRef.current.length}</div>
              <div className="text-sm text-slate-400 mt-1">Segments</div>
              <div className="font-mono text-lg font-semibold mt-1">{labelsRef.current.reduce((s, l) => s + (l.end - l.start), 0).toFixed(2)}s</div>
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2">
            <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold">Waveform</h2>
                <div className="flex items-center gap-2">
                  <span className="text-xs text-slate-400">Drag to select</span>
                  <button
                    onClick={() => addLabelAt(currentTime)}
                    className="px-3 py-1 bg-slate-700 hover:bg-slate-600 rounded text-sm"
                  >
                    Add at {currentTime.toFixed(2)}s
                  </button>
                </div>
              </div>
              <canvas
                ref={canvasRef}
                width="1200"
                height="200"
                className="border border-slate-700 rounded-lg bg-slate-900 cursor-crosshair"
                onMouseDown={startDrag}
                onMouseMove={onDrag}
                onMouseUp={endDrag}
                onMouseLeave={endDrag}
              />
              <div className="mt-4 text-xs text-slate-400">
                <div className="flex justify-between">
                  <span>0s</span>
                  <span>{duration.toFixed(2)}s</span>
                </div>
              </div>
            </div>
          </div>

          <div>
            <div className="bg-slate-800 rounded-xl p-4 border border-slate-700">
              <div className="flex items-center justify-between mb-4">
                <h2 className="text-xl font-semibold">Label Editor</h2>
                <button
                  onClick={() => {
                    const label = labelsRef.current.find((l) => l.id === dragRef.current.labelStart);
                    if (label) {
                      deleteLabel(label.id);
                    }
                  }}
                  disabled={!dragRef.current.dragging}
                  className="px-3 py-1 bg-red-600 hover:bg-red-700 disabled:bg-slate-700 disabled:text-slate-400 rounded text-sm"
                >
                  <FaTrash size={14} />
                </button>
              </div>
              <ul className="space-y-2 max-h-60 overflow-y-auto">
                {labelsRef.current.map((label) => (
                  <li
                    key={label.id}
                    className="flex items-center justify-between p-2 rounded bg-slate-900 hover:bg-slate-700 cursor-pointer transition"
                    onClick={() => seek(label.start)}
                  >
                    <div>
                      <div className="font-mono text-sm font-semibold">{label.name}</div>
                      <div className="text-xs text-slate-400">{label.start.toFixed(2)}s – {label.end.toFixed(2)}s</div>
                    </div>
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        deleteLabel(label.id);
                      }}
                      className="text-red-400 hover:text-red-300"
                    >
                      <FaTrash size={16} />
                    </button>
                  </li>
                ))}
                {labelsRef.current.length === 0 && (
                  <li className="text-center text-slate-400 p-4 italic">No labels yet. Click the waveform or add at current time.</li>
                )}
              </ul>
            </div>

            <div className="mt-4 bg-slate-800 rounded-xl p-4 border border-slate-700">
              <h2 className="text-xl font-semibold mb-2">Import Labels</h2>
              <label className="block">
                <input
                  type="file"
                  accept=".json"
                  onChange={importLabels}
                  className="hidden"
                  id="importInput"
                />
                <button
                  type="button"
                  onClick={() => document.getElementById('importInput').click()}
                  className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-slate-700 hover:bg-slate-600 rounded-lg transition"
                >
                  <FaUpload size={18} />
                  <span>Import JSON</span>
                </button>
                {importError && <div className="text-red-400 text-sm mt-2">{importError}</div>}
              </label>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;
