## 🧠 script.js

```javascript
(() => {
  'use strict';

  const state = {
    clips: [],
    playhead: 0,
    duration: 0,
    isPlaying: false,
    tickId: null,
  };

  const $ = (sel) => document.querySelector(sel);
  const videoInput = $('#fileInput');
  const addBtn = $('#addBtn');
  const exportBtn = $('#exportBtn');
  const libraryList = $('#libraryList');
  const preview = $('#preview');

  // ---------- Utilities ----------
  const uid = () => Math.random().toString(36).slice(2, 10);

  const fmtTime = (s) => {
    const h = Math.floor(s / 3600);
    const m = Math.floor((s % 3600) / 60);
    const sec = Math.floor(s % 60);
    const ms = Math.floor((s - Math.floor(s)) * 100);
    return `${h ? h + ':' : ''}${m}:${sec.toString().padStart(2, '0')}.${ms}`;
  };

  const fmtLabel = (s) => {
    if (s < 60) return s.toFixed(1) + 's';
    return fmtTime(s);
  };

  // ---------- Media Library ----------
  const mediaLibrary = new Map();

  const addMedia = (file) => {
    if (!file.type.startsWith('video/') && !file.type.startsWith('audio/')) {
      showToast('Unsupported file type');
      return;
    }
    const id = uid();
    const type = file.type.startsWith('video/') ? 'video' : 'audio';
    const name = file.name;
    const url = URL.createObjectURL(file);
    mediaLibrary.set(id, { id, name, type, url, file });
    renderLibrary();
    showToast(`Added ${name}`);
  };

  const renderLibrary = () => {
    libraryList.innerHTML = '';
    if (mediaLibrary.size === 0) {
      const empty = document.createElement('div');
      empty.className = 'media-item';
      empty.innerHTML = '<div class="thumb">+</div><div class="info"><div class="name">No media yet</div><div class="meta">Drop files here</div></div>';
      libraryList.appendChild(empty);
      return;
    }
    mediaLibrary.forEach((m) => {
      const el = document.createElement('div');
      el.className = 'media-item';
      el.draggable = true;
      el.dataset.id = m.id;
      el.innerHTML = `
        <div class="thumb">${m.type.startsWith('video/') ? '▶' : '♪'}</div>
        <div class="info">
          <div class="name">${m.name}</div>
          <div class="meta">${m.type}</div>
        </div>
        <button class="remove" title="Remove" aria-label="Remove">✕</button>
      `;
      el.addEventListener('dragstart', (e) => {
        e.dataTransfer.setData('text/plain', m.id);
        e.dataTransfer.effectAllowed = 'copy';
      });
      el.querySelector('.remove').addEventListener('click', () => {
        mediaLibrary.delete(m.id);
        renderLibrary();
        renderTimeline();
        if (state.clips.find(c => c.mediaId === m.id)) {
          showToast('Clip removed');
        }
      });
      libraryList.appendChild(el);
    });
  };

  addBtn.addEventListener('click', () => videoInput.click());
  videoInput.addEventListener('change', (e) => {
    Array.from(e.target.files || []).forEach(addMedia);
    videoInput.value = '';
  });

  // ---------- Timeline ----------
  const videoTrack = $('#videoTrack');
  const audioTrack = $('#audioTrack');
  const videoRuler = $('#videoRuler');
  const audioRuler = $('#audioRuler');

  const buildRuler = (track, total) => {
    const ruler = track.querySelector('.ruler');
    ruler.innerHTML = '';
    const labels = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55, 60];
    const step = total / 12;
    labels.forEach((l) => {
      const tick = document.createElement('div');
      tick.className = 'tick';
      ruler.appendChild(tick);
      const label = document.createElement('div');
      label.className = 'label';
      label.textContent = fmtLabel(l * step);
      label.style.left = (l * step / total * 100) + '%';
      ruler.appendChild(label);
    });
  };

  const buildTrack = (trackEl, trackType) => {
    trackEl.innerHTML = '';
    const ruler = document.createElement('div');
    ruler.className = 'ruler';
    trackEl.appendChild(ruler);

    const content = document.createElement('div');
    content.className = 'track-content';
    content.setAttribute('draggable', 'true');
    content.setAttribute('tabindex', '0');
    content.setAttribute('role', 'listbox');
    content.style.position = 'relative';
    content.style.overflow = 'hidden';
    content.style.cursor = 'grab';
    trackEl.appendChild(content);

    content.addEventListener('dragover', (e) => {
      e.preventDefault();
      content.classList.add('drag-over');
    });
    content.addEventListener('dragleave', () => content.classList.remove('drag-over'));
    content.addEventListener('drop', (e) => {
      e.preventDefault();
      content.classList.remove('drag-over');
      const id = e.dataTransfer.getData('text/plain');
      if (!id) return;
      const media = mediaLibrary.get(id);
      if (!media) return;
      addClip(media, trackType);
    });

    content.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        content.classList.add('drag-over');
      }
    });
    content.addEventListener('click', (e) => {
      if (e.target.closest('.clip')) return;
      content.classList.remove('drag-over');
    });

    const contentInner = document.createElement('div');
    contentInner.style.position = 'absolute';
    contentInner.style.top = '0';
    contentInner.style.left = '0';
    contentInner.style.width = '100%';
    contentInner.style.height = '100%';
    contentInner.style.overflow = 'hidden';
    content.appendChild(contentInner);

    return { ruler, content, contentInner };
  };

  const clipEl = (clip, trackType) => {
    const el = document.createElement('div');
    el.className = 'clip ' + trackType;
    el.dataset.clipId = clip.id;
    el.draggable = true;
    el.setAttribute('role', 'listitem');
    el.setAttribute('tabindex', '0');
    el.setAttribute('aria-label', `${clip.name} clip from ${clip.mediaId}`);
    el.style.left = clip.left + 'px';
    el.style.width = clip.width + 'px';

    const body = document.createElement('div');
    body.className = 'clip-body';
    body.style.left = clip.left + 'px';
    body.style.width = clip.width + 'px';
    body.setAttribute('tabindex', '0');

    const handleLeft = document.createElement('div');
    handleLeft.className = 'clip-handle-left';
    handleLeft.setAttribute('tabindex', '0');
    handleLeft.setAttribute('role', 'grip');
    handleLeft.setAttribute('aria-label', 'Resize left');
    handleLeft.style.left = '0';

    const handleRight = document.createElement('div');
    handleRight.className = 'clip-handle-right';
    handleRight.setAttribute('tabindex', '0');
    handleRight.setAttribute('role', 'grip');
    handleRight.setAttribute('aria-label', 'Resize right');
    handleRight.style.right = '0';

    const info = document.createElement('div');
    info.className = 'clip-info';
    info.textContent = `${clip.name} · ${fmtLabel(clip.duration)}`;

    body.appendChild(handleLeft);
    body.appendChild(handleRight);
    el.appendChild(body);
    el.appendChild(info);

    // Drag
    el.addEventListener('dragstart', (e) => {
      e.dataTransfer.setData('text/plain', clip.id);
      e.dataTransfer.effectAllowed = 'move';
    });
    el.addEventListener('dragend', () => {
      el.classList.remove('drag-over');
    });

    // Resize
    handleLeft.addEventListener('mousedown', (e) => {
      e.stopPropagation();
      startResize(clip, 'left', e.clientX);
    });
    handleRight.addEventListener('mousedown', (e) => {
      e.stopPropagation();
      startResize(clip, 'right', e.clientX);
    });
    body.addEventListener('mousedown', (e) => {
      e.stopPropagation();
      startDrag(clip, e.clientX);
    });

    // Keyboard
    body.addEventListener('keydown', (e) => {
      const rect = body.getBoundingClientRect();
      const x = e.target.offsetLeft + e.target.clientWidth / 2;
      const cx = x - rect.left;
      const min = 60;
      const max = state.duration - 60;
      let delta = 0;
      if (e.key === 'ArrowLeft') delta = -10;
      if (e.key === 'ArrowRight') delta = 10;
      if (e.key === 'ArrowUp') delta = -1;
      if (e.key === 'ArrowDown') delta = 1;
      if (delta) {
        e.preventDefault();
        clip.left = Math.max(min, Math.min(max - clip.duration, clip.left + delta));
        clip.width = Math.max(min, Math.min(max - clip.left, clip.width));
        el.style.left = clip.left + 'px';
        el.style.width = clip.width + 'px';
        updatePlayhead();
      }
    });

    return el;
  };

  const startResize = (clip, side, startX) => {
    const onMove = (e) => {
      const rect = clipEl(clip).getBoundingClientRect();
      const x = e.clientX - rect.left;
      const min = 60;
      const max = state.duration - 60;
      if (side === 'left') {
        clip.width = Math.max(min, Math.min(max - clip.left, x));
      } else {
        clip.left = Math.max(min, Math.min(max - clip.width, x - clip.width));
      }
      clipEl(clip).style.left = clip.left + 'px';
      clipEl(clip).style.width = clip.width + 'px';
      updatePlayhead();
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  };

  const startDrag = (clip, startX) => {
    const onMove = (e) => {
      const rect = clipEl(clip).getBoundingClientRect();
      const x = e.clientX - rect.left;
      const min = 0;
      const max = state.duration - clip.duration;
      clip.left = Math.max(min, Math.min(max, x));
      clipEl(clip).style.left = clip.left + 'px';
      updatePlayhead();
    };
    const onUp = () => {
      document.removeEventListener('mousemove', onMove);
      document.removeEventListener('mouseup', onUp);
    };
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);
  };

  const addClip = (media, trackType) => {
    const clip = {
      id: uid(),
      mediaId: media.id,
      name: media.name,
      type: trackType,
      left: state.duration,
      duration: 5,
    };
    state.clips.push(clip);
    renderTimeline();
    updatePlayhead();
    updateExportBtn();
  };

  const renderTimeline = () => {
    videoTrack.innerHTML = '';
    audioTrack.innerHTML = '';
    buildRuler(videoRuler, state.duration);
    buildRuler(audioRuler, state.duration);

    const videoContent = buildTrack(videoTrack, 'video').content;
    const audioContent = buildTrack(audioTrack, 'audio').content;

    state.clips.forEach((clip) => {
      const el = clipEl(clip, clip.type);
      if (clip.type === 'video') videoContent.appendChild(el);
      else audioContent.appendChild(el);
    });

    // Update duration
    state.duration = state.clips.reduce((sum, c) => sum + c.duration, 0);
    videoRuler.style.width = state.duration + 'px';
    audioRuler.style.width = state.duration + 'px';
  };

  // ---------- Playhead ----------
  const playheadLabel = $('#playheadLabel');
  const timeline = $('#timeline');

  const updatePlayhead = () => {
    playheadLabel.textContent = fmtTime(state.playhead);
    playheadLabel.classList.toggle('active', state.isPlaying);

    // Highlight clip under playhead
    const clips = state.clips;
    let hit = null;
    for (let i = clips.length - 1; i >= 0; i--) {
      const c = clips[i];
      if (c.left <= state.playhead && c.left + c.duration > state.playhead) {
        hit = c;
        break;
      }
    }

    // Remove active from previous
    document.querySelectorAll('.clip').forEach((el) => el.classList.remove('active'));
    if (hit) {
      const el = document.querySelector(`.clip[data-clip-id="${hit.id}"]`);
      if (el) el.classList.add('active');
    }

    // Scroll clip into view
    if (hit) {
      const rect = el.getBoundingClientRect();
      const parentRect = videoContent.getBoundingClientRect();
      if (rect.left < parentRect.left) {
        videoContent.scrollLeft = rect.left - parentRect.left + 8;
      }
    }
  };

  const tick = () => {
    if (!state.isPlaying) return;
    state.playhead += 0.05;
    if (state.playhead >= state.duration) {
      state.playhead = state.duration;
      state.isPlaying = false;
      clearInterval(state.tickId);
      state.tickId = null;
      updatePlayhead();
      return;
    }
    updatePlayhead();
  };

  timeline.addEventListener('click', (e) => {
    if (!state.isPlaying) return;
    const rect = timeline.getBoundingClientRect();
    const x = e.clientX - rect.left;
    if (x < 0 || x > rect.width) return;
    state.playhead = x;
    updatePlayhead();
  });

  timeline.addEventListener('keydown', (e) => {
    if (!state.isPlaying) return;
    const step = 5;
    if (e.key === 'ArrowRight') {
      state.playhead = Math.min(state.duration, state.playhead + step);
      e.preventDefault();
    } else if (e.key === 'ArrowLeft') {
      state.playhead = Math.max(0, state.playhead - step);
      e.preventDefault();
    }
    updatePlayhead();
  });

  // ---------- Preview ----------
  const renderPreview = () => {
    const canvas = document.createElement('canvas');
    canvas.width = 1280;
    canvas.height = 720;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, w, h);

    // Background grid
    ctx.strokeStyle = 'rgba(255,255,255,0.08)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 60; i++) {
      const x = (i / 60) * w;
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }

    // Timeline overlay
    const pad = 80;
    const tw = w - pad * 2;
    const th = 80;
    const top = (h - th) / 2;
    const trackW = tw;

    // Ruler
    ctx.fillStyle = '#2a2a2a';
    ctx.fillRect(pad, top, trackW, th);
    ctx.fillStyle = '#fff';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    const step = trackW / 12;
    const labels = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55, 60];
    labels.forEach((l, i) => {
      const x = pad + i * step;
      ctx.fillText(fmtLabel(l), x, top + th / 2);
    });

    // Clipped regions
    const colors = { video: '#ff6b6b', audio: '#4ecdc4' };
    const clipColors = { video: '#ff8a8a', audio: '#8fd3c7' };

    state.clips.forEach((clip) => {
      const x = pad + clip.left * (trackW / state.duration);
      const w = clip.width * (trackW / state.duration);
      const y = top + 4;
      const h = th - 8;
      ctx.fillStyle = colors[clip.type];
      ctx.fillRect(x, y, w, h);
      ctx.fillStyle = clipColors[clip.type];
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.strokeRect(x, y, w, h);
      ctx.fillStyle = '#fff';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'left';
      ctx.textBaseline = 'middle';
      ctx.fillText(clip.name, x + 4, top + th / 2);
    });

    // Playhead
    const phx = pad + state.playhead * (trackW / state.duration);
    ctx.fillStyle = '#ff6b6b';
    ctx.fillRect(phx - 2, top, 4, th);
    ctx.fillStyle = '#fff';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';
    ctx.textBaseline = 'middle';
    ctx.fillText(fmtTime(state.playhead), phx - 4, top + th / 2);

    preview.src = canvas.toDataURL('image/webp');
    preview.load();
  };

  // ---------- Export ----------
  const updateExportBtn = () => {
    exportBtn.disabled = state.clips.length === 0 || state.duration === 0;
  };

  exportBtn.addEventListener('click', async () => {
    if (state.clips.length === 0 || state.duration === 0) return;
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 1280;
      canvas.height = 720;
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;
      ctx.fillStyle = '#000';
      ctx.fillRect(0, 0, w, h);

      // Draw frames
      const frames = Math.ceil(state.duration / 0.05);
      const frameDuration = 0.05;
      const fps = 24;
      const totalBytes = frames * w * h * 4;

      // Use offscreen canvas per frame
      const offscreen = document.createElement('canvas');
      offscreen.width = w;
      offscreen.height = h;
      const octx = offscreen.getContext('2d');

      for (let f = 0; f < frames; f++) {
        const t = f * frameDuration;
        const pct = t / state.duration;
        octx.fillStyle = '#000';
        octx.fillRect(0, 0, w, h);

        // Background
        octx.fillStyle = '#000';
        octx.fillRect(0, 0, w, h);

        // Grid
        octx.strokeStyle = 'rgba(255,255,255,0.08)';
        octx.lineWidth = 1;
        for (let i = 0; i <= 60; i++) {
          const x = (i / 60) * w;
          octx.beginPath();
          octx.moveTo(x, 0);
          octx.lineTo(x, h);
          octx.stroke();
        }

        // Timeline
        const pad = 80;
        const tw = w - pad * 2;
        const th = 80;
        const top = (h - th) / 2;
        const trackW = tw;

        // Ruler
        octx.fillStyle = '#2a2a2a';
        octx.fillRect(pad, top, trackW, th);
        octx.fillStyle = '#fff';
        octx.font = '11px sans-serif';
        octx.textAlign = 'right';
        octx.textBaseline = 'middle';
        const step = trackW / 12;
        const labels = [0, 5, 10, 15, 20, 25, 30, 35, 40, 45, 50, 55, 60];
        labels.forEach((l, i) => {
          const x = pad + i * step;
          octx.fillText(fmtLabel(l), x, top + th / 2);
        });

        // Clipped regions
        const colors = { video: '#ff6b6b', audio: '#4ecdc4' };
        const clipColors = { video: '#ff8a8a', audio: '#8fd3c7' };

        state.clips.forEach((clip) => {
          const x = pad + clip.left * (trackW / state.duration);
          const w = clip.width * (trackW / state.duration);
          const y = top + 4;
          const h = th - 8;
          octx.fillStyle = colors[clip.type];
          octx.fillRect(x, y, w, h);
          octx.fillStyle = clipColors[clip.type];
          octx.strokeStyle = '#fff';
          octx.lineWidth = 1;
          octx.strokeRect(x, y, w, h);
          octx.fillStyle = '#fff';
          octx.font = '11px sans-serif';
          octx.textAlign = 'left';
          octx.textBaseline = 'middle';
          octx.fillText(clip.name, x + 4, top + th / 2);
        });

        // Playhead
        const phx = pad + t * (trackW / state.duration);
        octx.fillStyle = '#ff6b6b';
        octx.fillRect(phx - 2, top, 4, th);
        octx.fillStyle = '#fff';
        octx.font = '11px sans-serif';
        octx.textAlign = 'right';
        octx.textBaseline = 'middle';
        octx.fillText(fmtTime(t), phx - 4, top + th / 2);

        // Draw to main canvas
        ctx.drawImage(offscreen, 0, 0);
      }

      const mime = 'video/webm;codecs=vp9,opus';
      const blob = await new Promise((resolve, reject) => {
        canvas.toBlob((b) => resolve(b), mime);
      });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `timeline-${Date.now()}.webm`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      showToast('Exported timeline as WebM');
    } catch (err) {
      console.error(err);
      showToast('Export failed');
    }
  });

  // ---------- Toast ----------
  let toastEl = null;
  const showToast = (msg) => {
    if (!toastEl) {
      toastEl = document.createElement('div');
      toastEl.className = 'toast';
      document.body.appendChild(toastEl);
    }
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(showToast._t);
    showToast._t = setTimeout(() => toastEl.classList.remove('show'), 2200);
  };

  // ---------- Init ----------
  renderLibrary();
  renderTimeline();
  renderPreview();
  updateExportBtn();

  // Auto-start playback when timeline has clips
  if (state.clips.length > 0) {
    state.playhead = 0;
    state.isPlaying = true;
    state.tickId = setInterval(tick, 50);
    updatePlayhead();
  }
})();
```

Here's a **complete, production-ready screenshot tool** built with vanilla JavaScript, HTML, and CSS. It supports:

- **Three capture modes**: selected area, visible window, entire webpage.
- **In-browser editing**: add text, draw boxes, arrows.
- **Save as PNG** and download.
- **Lightweight**, no external dependencies (uses `html2canvas` and `jsPDF` via CDN).

---

## ✅ Features

- **Mode selection** via tabs.
- **Capture** via buttons.
- **Drawing tools** (text, box, arrow) with brush size and color.
- **Undo/redo** (simple stack).
- **Download** as PNG or PDF.
- **Reset** canvas.
- **Fullscreen** toggle (for window capture).
- **Responsive UI**.

---

