      <div id="colors" class="colors"></div>
    </div>
    <div class="section">
      <h3>Preview</h3>
      <div id="preview" class="preview"></div>
    </div>
  </aside>

  <main id="main">
    <header id="toolbar">
      <div>
        <span id="mode-label" class="mode-btn active">Selected Area</span>
        <span class="mode-btn" data-mode="window">Visible Window</span>
        <span class="mode-btn" data-mode="fullpage">Entire Page</span>
      </div>
      <div style="margin-left:auto; display:flex; gap:8px;">
        <button id="btn-fullscreen" class="action-btn" title="Toggle fullscreen"><i class="fa-solid fa-expand"></i> Fullscreen</button>
        <button id="btn-reset" class="action-btn" title="Reset"><i class="fa-solid fa-rotate-left"></i> Reset</button>
        <button id="btn-download" class="action-btn" title="Download"><i class="fa-solid fa-download"></i> Download</button>
      </div>
    </header>

    <section id="canvas-wrap" class="canvas-wrap"></section>

    <footer id="actions">
      <button id="btn-undo" class="action-btn" title="Undo" disabled><i class="fa-solid fa-rotate-left"></i> Undo</button>
      <button id="btn-redo" class="action-btn" title="Redo" disabled><i class="fa-solid fa-rotate-right"></i> Redo</button>
      <span id="stat" style="margin-left:auto; color:#64748b; font-size:13px;">0 drawings</span>
    </footer>
  </main>
