<script>
// ---------- State ----------
const state = {
  mode: 'area',
  tool: 'select',
  color: '#ffffff',
  size: 3,
  drawings: [],
  current: null,
  history: [],
  redoStack: [],
  previewCanvas: null,
  previewCtx: null,
  previewImg: null,
  fullscreen: false,
};

const MODES = ['area', 'window', 'fullpage'];
const TOOLS = ['select', 'text', 'box', 'arrow'];

// ---------- DOM ----------
const $ = (id) => document.getElementById(id);
const modesEl = $('modes');
const toolsEl = $('tools');
const colorsEl = $('colors');
const previewEl = $('preview');
const canvasWrap = $('canvas-wrap');
const canvasEl = $('canvas');
const statEl = $('stat');

// ---------- Build UI ----------
MODES.forEach(m => {
  const b = document.createElement('button');
  b.className = 'mode-btn' + (m === state.mode ? ' active' : '');
  b.textContent = modeLabel(m);
  b.dataset.mode = m;
  b.addEventListener('click', () => setMode(m));
  modesEl.appendChild(b);
});

TOOLS.forEach(t => {
  const b = document.createElement('button');
  b.className = 'btn' + (t === state.tool ? ' active' : '');
  b.textContent = toolLabel(t);
  b.dataset.tool = t;
  b.addEventListener('click', () => setTool(t));
  toolsEl.appendChild(b);
});

const colorPalette = ['#ffffff', '#ff6b6b', '#ffd93d', '#22d3ee', '#34d399', '#a78bfa', '#f472b6', '#60a5fa', '#fbbf24', '#8b5cf6'];
colorPalette.forEach(c => {
  const s = document.createElement('div');
  s.className = 'color-swatch' + (c === state.color ? ' active' : '');
  s.style.background = c;
  s.addEventListener('click', () => setColor(c));
  colorsEl.appendChild(s);
});

// ---------- Labels ----------
function modeLabel(m) {
  return { area: 'Selected Area', window: 'Visible Window', fullpage: 'Entire Page' }[m];
}
function toolLabel(t) {
  return { select: 'Select', text: 'Text', box: 'Box', arrow: 'Arrow' }[t];
}

// ---------- Mode helpers ----------
function setMode(m) {
  state.mode = m;
  MODES.forEach(m2 => {
    const b = modesEl.querySelector(`[data-mode="${m2}"]`);
    b.classList.toggle('active', m2 === m);
  });
  $('mode-label').textContent = modeLabel(m);
  render();
}

function setTool(t) {
  state.tool = t;
  TOOLS.forEach(t2 => {
    const b = toolsEl.querySelector(`[data-tool="${t2}"]`);
    b.classList.toggle('active', t2 === t);
  });
  if (state.tool === 'select') {
    canvasEl.style.cursor = 'default';
  } else {
    canvasEl.style.cursor = 'crosshair';
  }
  render();
}

function setColor(c) {
  state.color = c;
  colorsEl.querySelectorAll('.color-swatch').forEach(s => {
    s.classList.toggle('active', s.style.background === c);
  });
  render();
}

// ---------- Drawing ----------
function startDraw(x, y) {
  state.current = { x, y, tool: state.tool, color: state.color, size: state.size, points: [], text: '', textX: 0, textY: 0 };
}

function moveDraw(x, y) {
  if (!state.current) return;
  const c = state.current;
  if (c.tool === 'select') {
    // no-op for select
  } else if (c.tool === 'text') {
    c.textX = x; c.textY = y;
  } else {
    c.points.push({ x, y });
  }
}

function endDraw() {
  if (!state.current) return;
  const c = state.current;
  if (c.tool === 'text' && c.text) {
    state.drawings.push({ type: 'text', text: c.text, x: c.textX, y: c.textY, color: c.color, size: c.size });
  } else if (c.tool === 'box' || c.tool === 'arrow') {
    state.drawings.push({ type: c.tool, x: c.points[0].x, y: c.points[0].y, x2: c.points[c.points.length - 1].x, y2: c.points[c.points.length - 1].y, color: c.color, size: c.size });
  }
  state.current = null;
  pushHistory();
  render();
}

// ---------- Canvas rendering ----------
function render() {
  if (!state.previewCanvas) {
    state.previewCanvas = document.createElement('canvas');
    state.previewCanvas.width = 800;
    state.previewCanvas.height = 600;
    state.previewCtx = state.previewCanvas.getContext('2d');
    previewEl.appendChild(state.previewCanvas);
  }
  state.previewCtx.clearRect(0, 0, 800, 600);
  state.drawings.forEach(d => drawOnPreview(d));
  updateStats();
}

function drawOnPreview(d) {
  state.previewCtx.save();
  state.previewCtx.strokeStyle = d.color;
  state.previewCtx.fillStyle = d.color;
  state.previewCtx.lineWidth = d.size;
  if (d.type === 'text') {
    state.previewCtx.font = `${d.size * 2}px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
    state.previewCtx.fillText(d.text, d.x, d.y);
  } else {
    state.previewCtx.beginPath();
    state.previewCtx.moveTo(d.x, d.y);
    state.previewCtx.lineTo(d.x2, d.y2);
    state.previewCtx.stroke();
  }
  state.previewCtx.restore();
}

function updateStats() {
  statEl.textContent = `${state.drawings.length} drawing${state.drawings.length === 1 ? '' : 's'}`;
}

// ---------- Capture ----------
async function capture() {
  const opts = {
    backgroundColor: null,
    width: 1200,
    height: 900,
    scale: 2,
    useCORS: true,
    logging: false,
  };
  let canvas = null;
  if (state.mode === 'area') {
    const rect = canvasWrap.getBoundingClientRect();
    opts.width = rect.width;
    opts.height = rect.height;
    opts.x = rect.left;
    opts.y = rect.top;
    opts.canvas = document.createElement('canvas');
    opts.canvas.width = rect.width;
    opts.canvas.height = rect.height;
    canvas = opts.canvas;
  } else if (state.mode === 'window') {
    canvas = await html2canvas(window, opts);
  } else {
    canvas = await html2canvas(document.body, {
      ...opts,
      windowWidth: window.innerWidth,
      windowHeight: window.innerHeight,
      backgroundColor: '#ffffff',
    });
  }
  // Draw drawings on top
  const ctx = canvas.getContext('2d');
  state.drawings.forEach(d => drawOnCanvas(ctx, d));
  canvasWrap.appendChild(canvas);
  pushHistory();
  render();
}

function drawOnCanvas(ctx, d) {
  ctx.save();
  ctx.strokeStyle = d.color;
  ctx.fillStyle = d.color;
  ctx.lineWidth = d.size;
  if (d.type === 'text') {
    ctx.font = `${d.size * 2}px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif`;
    ctx.fillText(d.text, d.x, d.y);
  } else {
    ctx.beginPath();
    ctx.moveTo(d.x, d.y);
    ctx.lineTo(d.x2, d.y2);
    ctx.stroke();
  }
  ctx.restore();
}

// ---------- History ----------
function pushHistory() {
  state.history.push(JSON.stringify(state.drawings));
  if (state.history.length > 50) state.history.shift();
  state.redoStack = [];
}

function undo() {
  if (state.history.length === 0) return;
  const last = state.history.pop();
  const prev = state.redoStack.length ? JSON.parse(state.redoStack[state.redoStack.length - 1]) : [];
  state.redoStack.push(JSON.stringify(state.drawings));
  state.drawings = prev;
  render();
  $('btn-undo').disabled = state.history.length === 0;
  $('btn-redo').disabled = state.redoStack.length === 0;
}

function redo() {
  if (state.redoStack.length === 0) return;
  const next = JSON.parse(state.redoStack.pop());
  state.history.push(JSON.stringify(state.drawings));
  state.drawings = next;
  render();
  $('btn-undo').disabled = state.history.length === 0;
  $('btn-redo').disabled = state.redoStack.length === 0;
}

// ---------- Download ----------
function download() {
  if (!canvasWrap.firstChild) return;
  const canvas = canvasWrap.firstChild;
  const link = document.createElement('a');
  link.download = `screenshot-${Date.now()}.png`;
  link.href = canvas.toDataURL('image/png');
  link.click();
}

// ---------- Fullscreen ----------
function toggleFullscreen() {
  if (!document.fullscreenElement) {
    canvasWrap.requestFullscreen?.();
    state.fullscreen = true;
  } else {
    document.exitFullscreen?.();
    state.fullscreen = false;
  }
}

// ---------- Event listeners ----------
canvasEl.addEventListener('mousedown', (e) => {
  if (state.tool === 'select') {
    startDraw(e.clientX, e.clientY);
  }
});
canvasEl.addEventListener('mousemove', (e) => {
  if (state.current) {
    moveDraw(e.clientX, e.clientY);
  }
});
canvasEl.addEventListener('mouseup', (e) => {
  if (state.current) {
    endDraw();
  }
});
canvasEl.addEventListener('mouseleave', () => {
  if (state.current) endDraw();
});

$('btn-undo').addEventListener('click', undo);
$('btn-redo').addEventListener('click', redo);
$('btn-download').addEventListener('click', download);
$('btn-reset').addEventListener('click', reset);
$('btn-fullscreen').addEventListener('click', toggleFullscreen);

function reset() {
  state.drawings = [];
  state.history = [];
  state.redoStack = [];
  canvasWrap.innerHTML = '';
  render();
  $('btn-undo').disabled = true;
  $('btn-redo').disabled = true;
}

// ---------- Keyboard ----------
document.addEventListener('keydown', (e) => {
  if (e.key === 'z' && (e.ctrlKey || e.metaKey) && !e.shiftKey) {
    e.preventDefault();
    undo();
  } else if (e.key === 'y' && (e.ctrlKey || e.metaKey)) {
    e.preventDefault();
    redo();
  } else if (e.key === 'Escape') {
    reset();
  }
});

// ---------- Init ----------
function init() {
  // Default mode buttons
  const mBtns = document.querySelectorAll('#toolbar .mode-btn');
  mBtns.forEach(b => {
    b.addEventListener('click', () => {
      state.mode = b.dataset.mode;
      setMode(state.mode);
      capture();
    });
  });
  setMode('area');
  capture();
  $('btn-undo').disabled = true;
  $('btn-redo').disabled = true;
}
init();
</script>

</body>
</html>
```

