```javascript
// ============================================================
// Equestrian Show Jumping Game
// ============================================================
// A browser-based HTML5 Canvas game where the player guides a horse
// through an obstacle course, jumping over rails and water pits.
// Use arrow keys to steer, spacebar to jump.
// ============================================================

(() => {
  'use strict';

  // ---------- Configuration ----------
  const CONFIG = {
    GRAVITY: 0.6,
    JUMP_VELOCITY: -12,
    MOVE_SPEED: 5,
    MAX_FALL: 14,
    OBSTACLE_INTERVAL_MIN: 180,
    OBSTACLE_INTERVAL_MAX: 260,
    FINISH_X: 1000,
    FINISH_Y: 400,
    RAIL_HEIGHT: 40,
    RAIL_WIDTH: 140,
    RAIL_GAP: 120,
    WATER_HEIGHT: 60,
    WATER_WIDTH: 180,
    WATER_GAP: 140,
    OBSTACLE_CHANCE: 0.45,
    OBSTACLE_TYPES: ['rail', 'water'],
    POINTS_PER_OBSTACLE: 10,
    HIT_PENALTY: 5,
    START_X: 100,
    START_Y: 360,
  };

  // ---------- State ----------
  const state = {
    width: 0,
    height: 0,
    obstacles: [],
    particles: [],
    finish: null,
    score: 0,
    hitCount: 0,
    gameOver: false,
    keys: {},
    lastTime: 0,
    horse: {
      x: CONFIG.START_X,
      y: CONFIG.START_Y,
      vx: 0,
      vy: 0,
      onGround: true,
      angle: 0,
      jumpCooldown: 0,
    },
    camera: { x: 0, y: 0 },
  };

  // ---------- Obstacle ----------
  class Obstacle {
    constructor(type, x, y) {
      this.type = type;
      this.x = x;
      this.y = y;
      this.width = type === 'rail' ? CONFIG.RAIL_WIDTH : CONFIG.WATER_WIDTH;
      this.height = type === 'rail' ? CONFIG.RAIL_HEIGHT : CONFIG.WATER_HEIGHT;
      this.gap = type === 'rail' ? CONFIG.RAIL_GAP : CONFIG.WATER_GAP;
      this.hit = false;
      this.passed = false;
    }

    update(dt) {
      this.x -= dt * 4;
      if (this.x + this.width < 0) {
        this.x = state.width + 200;
      }
    }

    hitByHorse(horse) {
      if (this.hit || this.passed) return false;
      if (horse.x + 40 < this.x || horse.x > this.x + this.width) return false;
      if (horse.y + 40 < this.y || horse.y > this.y + this.height) return false;
      this.hit = true;
      this.passed = true;
      return true;
    }

    draw(ctx) {
      ctx.save();
      ctx.translate(this.x, this.y);

      if (this.hit) {
        ctx.fillStyle = '#ff4d4d';
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
      } else {
        if (this.type === 'rail') {
          ctx.fillStyle = '#b8860b';
          ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
          ctx.fillStyle = '#5a3a00';
          ctx.fillRect(-this.width / 2, -this.height / 2, this.width, 4);
          ctx.fillRect(-this.width / 2, -this.height / 2 + this.height - 4, this.width, 4);
          ctx.fillStyle = '#8b4513';
          ctx.fillRect(-this.width / 2, -this.height / 2 + 2, this.width, 2);
          ctx.fillRect(-this.width / 2, -this.height / 2 + this.height - 6, this.width, 2);
        } else {
          // Water pit with ripples
          ctx.fillStyle = '#1e90ff';
          ctx.beginPath();
          ctx.moveTo(-this.width / 2, -this.height / 2);
          ctx.lineTo(-this.width / 2, this.height / 2);
          ctx.quadraticCurveTo(0, -this.height / 2 + this.height * 0.3, this.width / 2, this.height / 2);
          ctx.lineTo(this.width / 2, -this.height / 2);
          ctx.quadraticCurveTo(0, -this.height / 2 - this.height * 0.3, -this.width / 2, -this.height / 2);
          ctx.closePath();
          ctx.fill();
          ctx.fillStyle = '#fff';
          ctx.strokeStyle = '#fff';
          ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.arc(0, 0, this.height * 0.2, 0, Math.PI * 2);
          ctx.stroke();
          ctx.beginPath();
          ctx.arc(0, 0, this.height * 0.3, 0, Math.PI * 2);
          ctx.stroke();
          ctx.beginPath();
          ctx.arc(0, 0, this.height * 0.4, 0, Math.PI * 2);
          ctx.stroke();
        }
      }

      ctx.restore();
    }
  }

  // ---------- Particle ----------
  class Particle {
    constructor(x, y, vx, vy, color, life = 120) {
      this.x = x;
      this.y = y;
      this.vx = vx;
      this.vy = vy;
      this.color = color;
      this.life = life;
      this.maxLife = life;
    }

    update(dt) {
      this.x += this.vx * dt;
      this.y += this.vy * dt;
      this.vx *= 0.96;
      this.vy *= 0.96;
      this.vy += 0.25; // gravity
      this.life -= dt * 16;
    }

    draw(ctx) {
      ctx.save();
      ctx.globalAlpha = Math.max(0, this.life / this.maxLife);
      ctx.fillStyle = this.color;
      ctx.fillRect(this.x - 2, this.y - 2, 4, 4);
      ctx.restore();
    }
  }

  // ---------- Rider ----------
  class Rider {
    constructor() {
      this.x = CONFIG.START_X;
      this.y = CONFIG.START_Y - 60;
      this.width = 30;
      this.height = 40;
      this.speed = 5;
    }

    update(dt) {
      if (state.keys['ArrowLeft'] || state.keys['a']) this.x -= this.speed * dt;
      if (state.keys['ArrowRight'] || state.keys['d']) this.x += this.speed * dt;
      this.x = Math.max(20, Math.min(state.width - 50, this.x));
    }

    draw(ctx) {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(state.horse.angle);
      ctx.fillStyle = '#2c1810';
      // body
      ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
      // helmet
      ctx.fillStyle = '#4a2a10';
      ctx.fillRect(-12, -this.height / 2 - 10, 24, 14);
      ctx.fillStyle = '#8b4513';
      ctx.fillRect(-10, -this.height / 2 - 10, 20, 10);
      // face
      ctx.fillStyle = '#fff';
      ctx.fillRect(-4, -4, 8, 8);
      // eyes
      ctx.fillStyle = '#000';
      ctx.fillRect(-3, -3, 2, 2);
      ctx.fillRect(1, -3, 2, 2);
      // arms
      ctx.fillStyle = '#2c1810';
      ctx.fillRect(-14, 0, 4, 10);
      ctx.fillRect(10, 0, 4, 10);
      ctx.fillStyle = '#8b4513';
      ctx.fillRect(-14, 0, 2, 10);
      ctx.fillRect(10, 0, 2, 10);
      ctx.restore();
    }
  }

  // ---------- Horse ----------
  class Horse {
    constructor() {
      this.x = CONFIG.START_X;
      this.y = CONFIG.START_Y;
      this.vx = 0;
      this.vy = 0;
      this.width = 70;
      this.height = 70;
      this.onGround = true;
      this.angle = 0;
      this.jumpCooldown = 0;
      this.jumpBuffer = 0;
    }

    update(dt) {
      // horizontal movement
      if (state.keys['ArrowLeft'] || state.keys['a']) {
        this.vx -= CONFIG.MOVE_SPEED * dt;
      } else if (state.keys['ArrowRight'] || state.keys['d']) {
        this.vx += CONFIG.MOVE_SPEED * dt;
      } else {
        this.vx *= 0.85;
      }
      this.vx = Math.max(-8, Math.min(8, this.vx));

      // jump
      if (!this.onGround && this.jumpCooldown > 0) {
        this.jumpCooldown -= dt;
      }
      if (state.keys[' '] && this.jumpCooldown <= 0 && this.onGround) {
        this.vy = CONFIG.JUMP_VELOCITY;
        this.onGround = false;
        this.jumpCooldown = 0.3;
        this.jumpBuffer = 0.15;
      } else if (state.keys[' '] && this.jumpBuffer > 0) {
        this.jumpBuffer -= dt;
      }

      // gravity
      if (!this.onGround) {
        this.vy += CONFIG.GRAVITY * dt;
        this.vy = Math.min(CONFIG.MAX_FALL, this.vy);
        if (this.vy > 0) this.onGround = true;
      }

      this.x += this.vx * dt;
      this.y += this.vy * dt;

      // angle based on velocity
      this.angle = Math.atan2(this.vy, this.vx) + Math.PI / 2;
      this.angle = Math.max(-0.7, Math.min(0.7, this.angle));

      // keep in bounds
      this.x = Math.max(40, Math.min(state.width - 60, this.x));
      this.y = Math.max(40, Math.min(state.height - 120, this.y));

      // camera follows horse
      state.camera.x = this.x - state.width / 2 + 60;
      state.camera.y = this.y - state.height / 2 + 40;
    }

    draw(ctx) {
      ctx.save();
      ctx.translate(this.x, this.y);
      ctx.rotate(this.angle);

      // mane
      ctx.fillStyle = '#8b4513';
      ctx.fillRect(-25, -60, 50, 10);
      ctx.fillRect(-30, -55, 60, 5);

      // body
      ctx.fillStyle = '#6b4423';
      ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);

      // belly
      ctx.fillStyle = '#a06d3a';
      ctx.fillRect(-this.width / 2 + 10, -this.height / 2 + 10, this.width - 20, this.height - 20);

      // legs
      ctx.fillStyle = '#3d2a10';
      ctx.fillRect(-18, 10, 10, 30);
      ctx.fillRect(6, 10, 10, 30);
      ctx.fillRect(-18, 30, 10, 30);
      ctx.fillRect(6, 30, 10, 30);

      // hooves
      ctx.fillStyle = '#8b4513';
      ctx.fillRect(-18, 40, 10, 8);
      ctx.fillRect(6, 40, 10, 8);
      ctx.fillRect(-18, 58, 10, 8);
      ctx.fillRect(6, 58, 10, 8);

      // tail
      ctx.fillStyle = '#3d2a10';
      ctx.fillRect(20, -30, 10, 30);

      // eyes
      ctx.fillStyle = '#fff';
      ctx.fillRect(-12, -18, 4, 4);
      ctx.fillRect(-4, -18, 4, 4);
      ctx.fillStyle = '#000';
      ctx.fillRect(-13, -19, 2, 2);
      ctx.fillRect(-5, -19, 2, 2);

      ctx.restore();
    }
  }

  // ---------- Finish ----------
  class Finish {
    constructor() {
      this.x = CONFIG.FINISH_X;
      this.y = CONFIG.FINISH_Y;
      this.width = 180;
      this.height = 80;
      this.hit = false;
    }

    draw(ctx) {
      ctx.save();
      ctx.translate(this.x, this.y);
      if (!this.hit) {
        ctx.fillStyle = '#228b22';
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
        ctx.fillStyle = '#115511';
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, 6);
        ctx.fillRect(-this.width / 2, -this.height / 2 + this.height - 6, this.width, 6);
        ctx.fillStyle = '#008000';
        ctx.fillRect(-this.width / 2, -this.height / 2 + 2, this.width, 2);
        ctx.fillRect(-this.width / 2, -this.height / 2 + this.height - 8, this.width, 2);
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('FINISH', 0, 12);
      } else {
        ctx.fillStyle = '#ff4d4d';
        ctx.fillRect(-this.width / 2, -this.height / 2, this.width, this.height);
        ctx.fillStyle = '#fff';
        ctx.font = 'bold 24px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('FINISHED', 0, 12);
      }
      ctx.restore();
    }
  }

  // ---------- Game ----------
  class Game {
    constructor(canvas) {
      this.canvas = canvas;
      this.ctx = canvas.getContext('2d');
      this.w = canvas.width;
      this.h = canvas.height;
      this.horse = new Horse();
      this.rider = new Rider();
      this.finish = new Finish();
      this.score = 0;
      this.hitCount = 0;
      this.gameOver = false;
      this.lastTime = performance.now();
      this.spawnTimer = 0;
      this.spawnInterval = CONFIG.OBSTACLE_INTERVAL_MIN + Math.random() * (CONFIG.OBSTACLE_INTERVAL_MAX - CONFIG.OBSTACLE_INTERVAL_MIN);
      this.obstacles = [];
      this.particles = [];
      this.font = 'bold 28px sans-serif';
      this.fontSmall = 'bold 18px sans-serif';
      this.startScreen = true;
      this.lastFrame = performance.now();
      this.frameCount = 0;
      this.fps = 0;
      this.fpsTimer = performance.now();

      this.resize();
      window.addEventListener('resize', () => this.resize());

      canvas.addEventListener('keydown', (e) => {
        state.keys[e.key.toLowerCase()] = true;
        if (e.key === 'Enter' && this.startScreen) {
          this.startScreen = false;
          this.gameLoop();
        }
      });
      canvas.addEventListener('keyup', (e) => {
        state.keys[e.key.toLowerCase()] = false;
      });

      // Touch support
      canvas.addEventListener('touchstart', (e) => {
        const t = e.touches[0];
        const rect = canvas.getBoundingClientRect();
        const x = t.clientX - rect.left;
        const y = t.clientY - rect.top;
        if (x > rect.width * 0.5) {
          state.keys['ArrowRight'] = true;
        } else {
          state.keys['ArrowLeft'] = true;
        }
      }, { passive: true });
      canvas.addEventListener('touchend', (e) => {
        state.keys['ArrowRight'] = false;
        state.keys['ArrowLeft'] = false;
      }, { passive: true });
    }

    resize() {
      const rect = this.canvas.getBoundingClientRect();
      this.w = rect.width;
      this.h = rect.height;
      this.canvas.width = this.w;
      this.canvas.height = this.h;
      CONFIG.FINISH_X = this.w * 0.9;
      CONFIG.FINISH_Y = this.h * 0.6;
    }

    spawnObstacle() {
      const type = CONFIG.OBSTACLE_TYPES[Math.floor(Math.random() * CONFIG.OBSTACLE_TYPES.length)];
      const x = this.w + 50;
      const y = this.h * 0.35 + Math.random() * (this.h * 0.3);
      this.obstacles.push(new Obstacle(type, x, y));
    }

    update(dt) {
      if (this.startScreen) return;

      // Update horse
      this.horse.update(dt);

      // Update rider
      this.rider.update(dt);

      // Update obstacles
      for (let i = this.obstacles.length - 1; i >= 0; i--) {
        const o = this.obstacles[i];
        o.update(dt);
        if (o.hitByHorse(this.horse)) {
          this.hitCount++;
          this.particles.push(
            new Particle(o.x, o.y, -4 + Math.random() * 8, -4 + Math.random() * 8, '#ff4d4d', 60),
            new Particle(o.x, o.y, -2 + Math.random() * 4, -2 + Math.random() * 4, '#ff8a8a', 40),
          );
        }
        if (o.x + o.width < -50) {
          this.obstacles.splice(i, 1);
        }
      }

      // Update particles
      for (let i = this.particles.length - 1; i >= 0; i--) {
        this.particles[i].update(dt);
        if (this.particles[i].life <= 0) this.particles.splice(i, 1);
      }

      // Spawn new obstacles
      this.spawnTimer -= dt;
      if (this.spawnTimer <= 0 && Math.random() < CONFIG.OBSTACLE_CHANCE) {
        this.spawnObstacle();
        this.spawnTimer = CONFIG.OBSTACLE_INTERVAL_MIN + Math.random() * (CONFIG.OBSTACLE_INTERVAL_MAX - CONFIG.OBSTACLE_INTERVAL_MIN);
      }

      // Check finish
      if (!this.finish.hit && this.horse.x > CONFIG.FINISH_X - 100 && this.horse.y > CONFIG.FINISH_Y - 60 && this.horse.y < CONFIG.FINISH_Y + 60) {
        this.finish.hit = true;
      }

      // Game over conditions
      if (this.hitCount >= 3) {
        this.gameOver = true;
        this.score = Math.max(0, this.score - this.hitCount * CONFIG.HIT_PENALTY);
      }
    }

    draw() {
      // Background
      this.ctx.fillStyle = '#87ceeb';
      this.ctx.fillRect(0, 0, this.w, this.h);

      // Grass stripes
      this.ctx.fillStyle = '#3cb371';
      for (let i = 0; i < 6; i++) {
        this.ctx.fillRect(0, this.h * 0.15 + i * (this.h * 0.35 / 6), this.w, this.h * 0.35 / 6);
      }

      // Fence posts
      this.ctx.fillStyle = '#2f4f4f';
      for (let x = 0; x < this.w; x += 100) {
        this.ctx.fillRect(x, this.h * 0.95, 2, 20);
      }

      // Obstacles
      for (const o of this.obstacles) {
        o.draw(this.ctx);
      }

      // Finish
      this.finish.draw(this.ctx);

      // Horse
      this.horse.draw(this.ctx);

      // Rider
      this.rider.draw(this.ctx);

      // Particles
      for (const p of this.particles) {
        p.draw(this.ctx);
      }

      // UI
      this.drawUI();
    }

    drawUI() {
      // Camera offset
      const camX = state.camera.x;
      const camY = state.camera.y;

      // Score
      this.ctx.save();
      this.ctx.fillStyle = '#fff';
      this.ctx.font = this.font;
      this.ctx.textAlign = 'left';
      this.ctx.textBaseline = 'top';
      this.ctx.fillText(`Score: ${this.score}`, 20 + camX, 20 + camY);
      this.ctx.fillText(`Hits: ${this.hitCount}`, 20 + camX, 60 + camY);

      // Instructions
      this.ctx.fillStyle = '#fff';
      this.ctx.font = this.fontSmall;
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'top';
      this.ctx.fillText('Use ← → to steer', this.w / 2 + camX, this.h - 100 + camY);
      this.ctx.fillText('Space to jump', this.w / 2 + camX, this.h - 70 + camY);
      this.ctx.fillText('Hit obstacles = penalty', this.w / 2 + camX, this.h - 40 + camY);
      this.ctx.fillText('Finish = win', this.w / 2 + camX, this.h - 10 + camY);

      this.ctx.restore();
    }

    startScreen() {
      this.ctx.fillStyle = '#fff';
      this.ctx.font = 'bold 48px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'middle';
      this.ctx.fillText('EQUESTRIAN SHOW JUMPING', this.w / 2, this.h / 2 - 40);
      this.ctx.font = 'bold 24px sans-serif';
      this.ctx.fillText('Guide the horse through the course', this.w / 2, this.h / 2 + 10);
      this.ctx.fillText('Avoid obstacles and reach the finish!', this.w / 2, this.h / 2 + 40);
      this.ctx.fillText('Press ENTER to start', this.w / 2, this.h / 2 + 100);
    }

    gameLoop() {
      const now = performance.now();
      const dt = Math.min(0.05, (now - this.lastTime) / 1000);
      this.lastTime = now;

      this.update(dt);
      this.draw();

      this.frameCount++;
      if (now - this.fpsTimer >= 1000) {
        this.fps = this.frameCount;
        this.frameCount = 0;
        this.fpsTimer = now;
      }

      if (!this.gameOver && !this.finish.hit) {
        requestAnimationFrame((t) => this.gameLoop(t));
      } else {
        this.endScreen();
      }
    }

    endScreen() {
      this.ctx.fillStyle = 'rgba(0,0,0,0.7)';
      this.ctx.fillRect(0, 0, this.w, this.h);
      this.ctx.fillStyle = '#fff';
      this.ctx.font = 'bold 36px sans-serif';
      this.ctx.textAlign = 'center';
      this.ctx.textBaseline = 'middle';
      if (this.finish.hit) {
        this.ctx.fillText('FINISHED!', this.w / 2, this.h / 2 - 20);
        this.ctx.font = 'bold 24px sans-serif';
        this.ctx.fillText(`Final Score: ${this.score}`, this.w / 2, this.h / 2 + 30);
      } else {
        this.ctx.fillText('GAME OVER', this.w / 2, this.h / 2 - 20);
        this.ctx.font = 'bold 20px sans-serif';
        this.ctx.fillText(`You hit ${this.hitCount} obstacle(s)`, this.w / 2, this.h / 2 + 30);
        this.ctx.fillText(`Final Score: ${this.score}`, this.w / 2, this.h / 2 + 60);
      }
      this.ctx.font = 'bold 18px sans-serif';
      this.ctx.fillText(`FPS: ${this.fps}`, this.w - 120 + state.camera.x, 40 + state.camera.y);
      this.ctx.fillText('Press ENTER to restart', this.w / 2, this.h - 20 + state.camera.y);
    }

    run() {
      this.startScreen();
      requestAnimationFrame((t) => this.gameLoop(t));
    }
  }

  // ---------- Entry ----------
  const canvas = document.getElementById('game');
  if (canvas) {
    const game = new Game(canvas);
    game.run();
  } else {
    console.error('Canvas not found');
  }
})();
```

Creating a **sandbox-style shooting game editor** involves several components:

1. **Scene Editor** — Drag-and-drop placement of entities (enemies, obstacles, props).
2. **Properties Panel** — Adjust properties per entity (health, speed, spawn rate, etc.).
3. **Level Objectives** — Define win/lose conditions (e.g., kill 10 enemies, reach flag).
4. **Preview Mode** — Test the level in real time.
5. **Save/Load** — Export/import level data (JSON).
6. **UI** — Toolbars, panels, inspector, viewport.

---

## ✅ Tech Stack

We'll use **HTML5 Canvas + vanilla JS** for simplicity and cross-browser compatibility. No external frameworks (though Phaser or Three.js could scale this up).

---

## 🧩 Features

- **Viewport** with grid snap (40px units).
- **Drag & drop** entities from a palette.
- **Inspector** panel to edit selected entity.
- **Preview** mode with keyboard controls.
- **Save/Load** as JSON.
- **Entity types**: Player, Enemy, Obstacle, Prop, Flag.

