## 🧠 script.js

```javascript
(() => {
  'use strict';

  const canvas = document.getElementById('mainCanvas');
  const ctx = canvas.getContext('2d');
  const canvasWrap = document.getElementById('canvasWrap');
  const emptyState = document.getElementById('emptyState');
  const fileInput = document.getElementById('fileInput');
  const undoBtn = document.getElementById('undoBtn');
  const redoBtn = document.getElementById('redoBtn');
  const exportGifBtn = document.getElementById('exportGifBtn');
  const exportVideoBtn = document.getElementById('exportVideoBtn');
  const addStickerBtn = document.getElementById('addStickerBtn');
  const clearAllBtn = document.getElementById('clearAllBtn');
  const copyBtn = document.getElementById('copyBtn');
  const pasteBtn = document.getElementById('pasteBtn');
  const stickersList = document.getElementById('stickersList');

  const animSel = document.getElementById('animSel');
  const speedR = document.getElementById('speedR');
  const speedV = document.getElementById('speedV');
  const sizeR = document.getElementById('sizeR');
  const sizeV = document.getElementById('sizeV');
  const rotR = document.getElementById('rotR');
  const rotV = document.getElementById('rotV');
  const opacR = document.getElementById('opacR');
  const opacV = document.getElementById('opacV');
  const colorR = document.getElementById('colorR');

  const sizeMeta = document.getElementById('sizeMeta');
  const resMeta = document.getElementById('resMeta');

  // State
  let image = null;
  let stickers = [];
  let history = [];
  let historyIndex = -1;
  let lastFrame = 0;
  let isRecording = false;
  let videoBlob = null;
  let videoUrl = null;

  // ---------- Utilities ----------
  const uid = () => Math.random().toString(36).slice(2, 10);

  function loadImage(file) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = (e) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = reject;
        img.src = e.target.result;
      };
      reader.onerror = reject;
      reader.readAsDataURL(file);
    });
  }

  function resizeCanvas() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  }

  function fitImageToCanvas(img) {
    const rect = canvasWrap.getBoundingClientRect();
    const w = img.naturalWidth || img.width;
    const h = img.naturalHeight || img.height;
    const scale = Math.min(rect.width / w, rect.height / h, 1);
    const cw = w * scale;
    const ch = h * scale;
    const x = (rect.width - cw) / 2;
    const y = (rect.height - ch) / 2;
    ctx.drawImage(img, x, y, cw, ch);
    return { w: cw, h: ch, x, y };
  }

  function addSticker(type = 'emoji', initial = {}) {
    const defaults = {
      id: uid(),
      type,
      x: 0.5, y: 0.5, // normalized
      scale: 0.8,
      rotation: 0,
      color: '#ff4500',
      text: type === 'text' ? 'Hello' : '✨',
      fontSize: 60,
      fontWeight: 700,
      fontFamily: 'Arial, sans-serif',
      animation: 'none',
      animationSpeed: 50,
      opacity: 100,
      shadow: false,
      shadowBlur: 10,
      shadowColor: 'rgba(0,0,0,0.4)'
    };
    const s = { ...defaults, ...initial };
    stickers.push(s);
    render();
    renderList();
    history.push(JSON.parse(JSON.stringify(stickers)));
    historyIndex = history.length - 1;
    return s;
  }

  function updateSticker(id, props) {
    const idx = stickers.findIndex(s => s.id === id);
    if (idx < 0) return;
    stickers[idx] = { ...stickers[idx], ...props };
    render();
    renderList();
    history.push(JSON.parse(JSON.stringify(stickers)));
    historyIndex = history.length - 1;
  }

  function removeSticker(id) {
    const idx = stickers.findIndex(s => s.id === id);
    if (idx < 0) return;
    stickers.splice(idx, 1);
    history.push(JSON.parse(JSON.stringify(stickers)));
    historyIndex = history.length - 1;
    render();
    renderList();
  }

  function clearAll() {
    if (stickers.length === 0) return;
    if (!confirm('Clear all stickers?')) return;
    stickers = [];
    history.push(JSON.parse(JSON.stringify(stickers)));
    historyIndex = history.length - 1;
    render();
    renderList();
  }

  function undo() {
    if (historyIndex <= 0) return;
    historyIndex--;
    stickers = JSON.parse(JSON.stringify(history[historyIndex]));
    render();
    renderList();
  }

  function redo() {
    if (historyIndex >= history.length - 1) return;
    historyIndex++;
    stickers = JSON.parse(JSON.stringify(history[historyIndex]));
    render();
    renderList();
  }

  function copySticker(id) {
    const s = stickers.find(x => x.id === id);
    if (!s) return;
    try {
      const blob = new Blob([JSON.stringify(s, null, 2)], { type: 'application/json' });
      navigator.clipboard.write([new ClipboardItem({ 'text/plain': blob })]);
    } catch (e) { /* ignore */ }
  }

  function pasteSticker() {
    navigator.clipboard.readText().then(text => {
      try {
        const s = JSON.parse(text);
        if (s.id) delete s.id;
        addSticker(s.type || 'emoji', s);
      } catch (e) { /* ignore */ }
    });
  }

  // ---------- Rendering ----------
  function render() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    ctx.clearRect(0, 0, rect.width, rect.height);

    if (image) {
      const { w, h, x, y } = fitImageToCanvas(image);
      ctx.drawImage(image, x, y, w, h);
    }

    stickers.forEach(s => drawSticker(s, rect.width, rect.height));
  }

  function drawSticker(s, w, h) {
    const x = s.x * w;
    const y = s.y * h;
    const scale = s.scale;
    const rot = s.rotation * Math.PI / 180;

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.rotate(rot);

    if (s.shadow) {
      ctx.shadowColor = s.shadowColor;
      ctx.shadowBlur = s.shadowBlur;
    } else {
      ctx.shadowBlur = 0;
    }

    if (s.type === 'emoji') {
      drawEmoji(s.text, s.fontSize, s.color, s.opacity / 100);
    } else if (s.type === 'text') {
      drawText(s.text, s.fontSize, s.color, s.fontWeight, s.fontFamily, s.opacity / 100);
    } else if (s.type === 'shape') {
      drawShape(s.shape, s.color, s.opacity / 100);
    }

    ctx.restore();
  }

  function drawEmoji(text, size, color, alpha) {
    ctx.globalAlpha = alpha;
    ctx.font = `bold ${size}px Segoe UI, Emoji, Noto Color Emoji, sans-serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 0, 0);
  }

  function drawText(text, size, color, weight, family, alpha) {
    ctx.globalAlpha = alpha;
    ctx.font = `${weight} ${size}px ${family}`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 0, 0);
  }

  function drawShape(shape, color, alpha) {
    ctx.globalAlpha = alpha;
    ctx.fillStyle = color;
    ctx.beginPath();
    if (shape === 'circle') {
      ctx.arc(0, 0, 60, 0, Math.PI * 2);
    } else if (shape === 'square') {
      ctx.rect(-30, -30, 60, 60);
    } else if (shape === 'triangle') {
      ctx.moveTo(0, -60);
      ctx.lineTo(60, 60);
      ctx.lineTo(-60, 60);
      ctx.closePath();
    } else if (shape === 'star') {
      const spikes = 5;
      const outerR = 60, innerR = 30;
      ctx.beginPath();
      for (let i = 0; i < spikes * 2; i++) {
        const r = i % 2 === 0 ? outerR : innerR;
        const a = (i * Math.PI) / spikes - Math.PI / 2;
        const x = Math.cos(a) * r;
        const y = Math.sin(a) * r;
        if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
      }
      ctx.closePath();
    }
    ctx.fill();
  }

  // ---------- Animated rendering ----------
  function animate() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    ctx.clearRect(0, 0, rect.width, rect.height);

    if (image) {
      const { w, h, x, y } = fitImageToCanvas(image);
      ctx.drawImage(image, x, y, w, h);
    }

    const t = performance.now() / 1000;
    stickers.forEach(s => drawAnimatedSticker(s, rect.width, rect.height, t));
  }

  function drawAnimatedSticker(s, w, h, t) {
    const x = s.x * w;
    const y = s.y * h;
    const scale = s.scale;
    const rot = s.rotation * Math.PI / 180;

    ctx.save();
    ctx.translate(x, y);
    ctx.scale(scale, scale);
    ctx.rotate(rot);

    const anim = s.animation;
    const speed = s.animationSpeed / 100;
    const phase = t * speed;
    let offsetX = 0, offsetY = 0, scaleOffset = 1, rotOffset = 0;

    if (anim === 'bounce') {
      offsetX = Math.sin(phase * 4) * 20;
      offsetY = Math.sin(phase * 3) * 10;
    } else if (anim === 'pulse') {
      const pulse = 0.8 + Math.sin(phase * 3) * 0.2;
      scaleOffset = pulse;
    } else if (anim === 'spin') {
      rotOffset = phase * 2;
    } else if (anim === 'wiggle') {
      offsetX = Math.sin(phase * 6) * 15;
      offsetY = Math.sin(phase * 8) * 8;
    }

    ctx.translate(offsetX, offsetY);
    ctx.rotate(rotOffset);

    if (s.shadow) {
      ctx.shadowColor = s.shadowColor;
      ctx.shadowBlur = s.shadowBlur;
    }

    if (s.type === 'emoji') {
      drawEmoji(s.text, s.fontSize, s.color, s.opacity / 100);
    } else if (s.type === 'text') {
      drawText(s.text, s.fontSize, s.color, s.fontWeight, s.fontFamily, s.opacity / 100);
    } else if (s.type === 'shape') {
      drawShape(s.shape, s.color, s.opacity / 100);
    }

    ctx.restore();
  }

  // ---------- List UI ----------
  function renderList() {
    stickersList.innerHTML = '';
    stickers.forEach(s => {
      const el = document.createElement('div');
      el.className = 'sticker-item';
      el.dataset.id = s.id;
      el.style.setProperty('--swatch', s.color);
      el.innerHTML = `
        <div class="swatch"></div>
        <div class="info">
          <div class="name">${s.text}</div>
          <div class="meta">${s.type} · ${s.animation}</div>
        </div>
        <div class="actions">
          <button title="Edit" data-act="edit"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.121 2.121 0 1 1 3 3L7 19l-4 1 1-4 12.5-12.5z"/></svg></button>
          <button title="Delete" data-act="delete"><svg viewBox="0 0 24 24" width="14" height="14" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18"/><path d="M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/><path d="M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg></button>
        </div>
      `;
      el.addEventListener('click', (e) => {
        const act = e.target.dataset.act;
        if (act === 'edit') openEditor(s.id);
        else if (act === 'delete') removeSticker(s.id);
      });
      stickersList.appendChild(el);
    });
  }

  function openEditor(id) {
    const s = stickers.find(x => x.id === id);
    if (!s) return;
    animSel.value = s.animation;
    speedR.value = s.animationSpeed;
    speedV.textContent = s.animationSpeed;
    sizeR.value = Math.round(s.scale * 100);
    sizeV.textContent = Math.round(s.scale * 100) + '%';
    rotR.value = s.rotation;
    rotV.textContent = s.rotation + '°';
    opacR.value = s.opacity;
    opacV.textContent = s.opacity + '%';
    colorR.value = s.color;
    if (s.type === 'text') {
      addStickerBtn.textContent = 'Edit Text';
      addStickerBtn.style.display = 'none';
    }
  }

  // ---------- Export ----------
  async function exportGif() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    // Render frames
    const frames = [];
    const frameCount = 60;
    const delay = 40; // ms
    const w = canvas.width, h = canvas.height;

    for (let i = 0; i < frameCount; i++) {
      ctx.clearRect(0, 0, w, h);
      if (image) {
        const { w: iw, h: ih, x, y } = fitImageToCanvas(image);
        ctx.drawImage(image, x, y, iw, ih);
      }
      stickers.forEach(s => drawAnimatedSticker(s, w, h, i * (delay / 1000)));
      frames.push(canvas.toDataURL('image/png'));
    }

    // GIF
    const gif = new GIF({
      workers: 2,
      quality: 8,
      width: w,
      height: h
    });
    frames.forEach((frame, i) => gif.addFrame(frame, { delay, copy: true }));
    gif.on('finished', blob => {
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'sticker.gif';
      a.click();
      URL.revokeObjectURL(url);
    });
    gif.on('error', err => console.error(err));
    gif.render();
  }

  async function exportVideo() {
    const rect = canvasWrap.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
    canvas.style.width = rect.width + 'px';
    canvas.style.height = rect.height + 'px';
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

    const w = canvas.width, h = canvas.height;
    const frameCount = 120;
    const fps = 30;
    const duration = frameCount / fps;

    const stream = canvas.captureStream(fps);
    const track = stream.getVideoTracks()[0];
    const rec = new MediaRecorder(stream, { mimeType: 'video/webm;codecs=vp9' });
    const chunks = [];
    rec.ondataavailable = e => chunks.push(e.data);
    rec.onstop = () => {
      const blob = new Blob(chunks, { type: 'video/webm' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'sticker.webm';
      a.click();
      URL.revokeObjectURL(url);
    };

    rec.start();
    videoUrl = URL.createObjectURL(blob);
    videoBlob = blob;

    const start = performance.now();
    const loop = () => {
      const elapsed = (performance.now() - start) / 1000;
      if (elapsed < duration) {
        ctx.clearRect(0, 0, w, h);
        if (image) {
          const { w: iw, h: ih, x, y } = fitImageToCanvas(image);
          ctx.drawImage(image, x, y, iw, ih);
        }
        stickers.forEach(s => drawAnimatedSticker(s, w, h, elapsed));
        rec.pause();
        setTimeout(() => {
          rec.resume();
          animate();
        }, 50);
      } else {
        rec.stop();
      }
    };
    animate();
    loop();
  }

  // ---------- Events ----------
  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) handleFile(file);
  });

  document.getElementById('fileInput').addEventListener('click', (e) => {
    e.target.value = '';
  });

  function handleFile(file) {
    loadImage(file).then(img => {
      image = img;
      stickers = [];
      history = [{ stickers: [] }];
      historyIndex = 0;
      emptyState.style.display = 'none';
      addSticker('emoji');
      render();
    }).catch(err => {
      alert('Failed to load image: ' + err.message);
    });
  }

  undoBtn.addEventListener('click', undo);
  redoBtn.addEventListener('click', redo);
  exportGifBtn.addEventListener('click', exportGif);
  exportVideoBtn.addEventListener('click', exportVideo);
  addStickerBtn.addEventListener('click', () => addSticker('emoji'));
  clearAllBtn.addEventListener('click', clearAll);
  copyBtn.addEventListener('click', () => {
    const s = stickers[0];
    if (s) copySticker(s.id);
  });
  pasteBtn.addEventListener('click', pasteSticker);

  animSel.addEventListener('change', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.animation = e.target.value;
    });
    render();
    renderList();
  });
  speedR.addEventListener('input', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.animationSpeed = parseInt(e.target.value, 10);
    });
    speedV.textContent = e.target.value;
    render();
  });
  sizeR.addEventListener('input', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.scale = parseFloat(e.target.value) / 100;
    });
    sizeV.textContent = e.target.value + '%';
    render();
  });
  rotR.addEventListener('input', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.rotation = parseInt(e.target.value, 10);
    });
    rotV.textContent = e.target.value + '°';
    render();
  });
  opacR.addEventListener('input', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.opacity = parseInt(e.target.value, 10);
    });
    opacV.textContent = e.target.value + '%';
    render();
  });
  colorR.addEventListener('input', (e) => {
    stickers.forEach(s => {
      if (s.id === stickers[0]?.id) s.color = e.target.value;
    });
    render();
    renderList();
  });

  canvasWrap.addEventListener('click', (e) => {
    const rect = canvasWrap.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    const w = rect.width, h = rect.height;
    const nx = x / w;
    const ny = y / h;
    addSticker('emoji', { x: nx, y: ny });
  });

  window.addEventListener('resize', () => {
    resizeCanvas();
    if (image) render();
  });

  // Keyboard shortcuts
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key === 'z') { e.preventDefault(); undo(); }
    if ((e.ctrlKey || e.metaKey) && (e.key === 'y' || (e.key === 'z' && !e.shiftKey))) { e.preventDefault(); redo(); }
    if (e.key === 'Delete' || e.key === 'Backspace') { if (stickers.length) removeSticker(stickers[0].id); }
  });

  // Init
  resizeCanvas();
  render();
})();
```

---

## 📦 How to Run

1. Save as `index.html`, `styles.css`, `script.js`.
2. Open in a modern browser (Chrome, Edge, Firefox).
3. Upload an image → add stickers → adjust → export.

---

## ⚠️ Limitations

- GIF export uses `gif.js` — works in most browsers.
- Video export uses MediaRecorder — **only works in browsers that support canvas captureStream** (Chrome, Edge, Firefox).
- Animated emojis are drawn with canvas text — limited to system fonts. For true animated emojis, consider a WebGL shader pass.
- Undo/redo is per-sticker state; full snapshot-based undo would require a more complex history system.

---

