  <script>
    (function () {
      const audio = document.getElementById('audio');
      const audioBtn = document.getElementById('audioBtn');
      const lrcBtn = document.getElementById('lrcBtn');
      const audioInfo = document.getElementById('audioInfo');
      const lrcInfo = document.getElementById('lrcInfo');
      const playBtn = document.getElementById('playBtn');
      const pauseBtn = document.getElementById('pauseBtn');
      const stopBtn = document.getElementById('stopBtn');
      const seekBack = document.getElementById('seekBack');
      const seekFwd = document.getElementById('seekFwd');
      const offsetInput = document.getElementById('offset');
      const offsetValue = document.getElementById('offsetValue');
      const progressBar = document.getElementById('progressBar');
      const statusEl = document.getElementById('status');
      const lyricsEl = document.getElementById('lyrics');
      const exportBtn = document.getElementById('exportBtn');

      let currentOffset = 0;
      let playing = false;
      let timer = null;
      let lyricsData = [];
      let currentLineIndex = -1;
      let currentWordIndex = -1;
      let currentWordStart = 0;
      let currentWordEnd = 0;
      let currentWordText = '';
      let lastPlayed = 0;
      let lastSeek = 0;

      // LRC format: [mm]:ss.xx text
      function parseLrc(text) {
        const lines = text.trim().split(/\r?\n/);
        const parsed = [];
        for (const line of lines) {
          const m = line.match(/^\[(\d{2}):(\d{2})(\.(\d{1,3}))?\]\s*(.*)$/);
          if (!m) continue;
          const mm = parseInt(m[1], 10);
          const ss = parseInt(m[2], 10);
          const ms = m[4] ? parseFloat('0.' + m[4]) * 100 : 0;
          const total = mm * 60 + ss + ms / 100;
          parsed.push({ time: total, text: m[5].trim() });
        }
        return parsed;
      }

      function formatTime(sec) {
        sec = Math.max(0, Math.floor(sec));
        const mm = String(Math.floor(sec / 60)).padStart(2, '0');
        const ss = String(sec % 60).padStart(2, '0');
        return `${mm}:${ss}`;
      }

      function getAudioDuration() {
        if (audio.duration && !isNaN(audio.duration)) return audio.duration;
        return 0;
      }

      function updateStatus() {
        const dur = getAudioDuration();
        const pos = audio.currentTime || 0;
        const pct = dur > 0 ? (pos / dur) * 100 : 0;
        progressBar.style.width = pct + '%';
        offsetValue.textContent = currentOffset.toFixed(2);
        statusEl.innerHTML = `<strong>${formatTime(pos)}</strong> / ${formatTime(dur)} · Offset: ${currentOffset.toFixed(2)}s`;
      }

      function renderLyrics() {
        lyricsEl.innerHTML = '';
        if (!lyricsData.length) {
          lyricsEl.innerHTML = '<span style="color:var(--text-dim);font-size:14px;">No lyrics loaded.</span>';
          return;
        }

        // Split into words
        const wordLines = [];
        for (const l of lyricsData) {
          const words = splitIntoWords(l.text);
          wordLines.push({ line: l, words });
        }

        for (const wl of wordLines) {
          const lineEl = document.createElement('div');
          lineEl.className = 'line';
          for (const w of wl.words) {
            const span = document.createElement('span');
            span.className = 'word';
            span.textContent = w;
            lineEl.appendChild(span);
          }
          lyricsEl.appendChild(lineEl);
        }
      }

      function splitIntoWords(text) {
        const words = [];
        const re = /\s+/g;
        const tokens = text.split(re);
        for (const t of tokens) {
          if (!t) continue;
          // Try to split on punctuation attached to words
          const split = t.match(/[A-Za-z0-9\u4e00-\u9fff]+|[^A-Za-z0-9\u4e00-\u9fff]+/g) || [t];
          for (const s of split) {
            if (s.trim()) words.push(s.trim());
          }
        }
        return words;
      }

      function updateHighlight() {
        const dur = getAudioDuration();
        if (!dur || dur < 0.5) return;

        const now = audio.currentTime || 0;
        const adjusted = now + currentOffset;

        // Find the word line that contains the current time
        let found = false;
        for (let i = 0; i < lyricsData.length; i++) {
          const line = lyricsData[i];
          const words = lyricsData[i].words;
          if (!words.length) continue;

          // Find the word range that contains adjusted time
          let left = 0, right = words.length - 1;
          while (left <= right) {
            const mid = Math.floor((left + right) / 2);
            const midStart = line.times[mid];
            const midEnd = mid === words.length - 1
              ? dur + 20
              : line.times[mid + 1];

            if (adjusted >= midStart && adjusted < midEnd) {
              currentLineIndex = i;
              currentWordIndex = mid;
              currentWordStart = midStart;
              currentWordEnd = midEnd;
              currentWordText = words[mid];
              found = true;
              break;
            }
            if (adjusted < midStart) right = mid - 1;
            else left = mid + 1;
          }
          if (found) break;
        }

        if (!found) {
          currentLineIndex = -1;
          currentWordIndex = -1;
          currentWordStart = 0;
          currentWordEnd = dur + 20;
          currentWordText = '';
        }

        // Apply highlight
        const words = lyricsEl.querySelectorAll('.word');
        let idx = 0;
        words.forEach((w, i) => {
          const lineIdx = i % (lyricsData[i] ? lyricsData[i].words.length : 0);
          const line = lyricsData[i];
          const wordsInLine = line ? line.words : [];
          if (lineIdx >= wordsInLine.length) return;
          const wText = wordsInLine[lineIdx];
          const wStart = line.times[lineIdx];
          const wEnd = lineIdx === wordsInLine.length - 1
            ? dur + 20
            : line.times[lineIdx + 1];

          if (wText === currentWordText) {
            w.classList.add('highlight');
          } else if (adjusted < wStart || adjusted >= wEnd) {
            w.classList.remove('highlight');
          }
          idx++;
        });
      }

      function applyOffsetToLrc() {
        const modified = lyricsData.map(l => {
          return {
            time: l.time + currentOffset,
            text: l.text,
            words: l.words,
            times: l.times
          };
        });
        return modified;
      }

      function exportLrc() {
        const modified = applyOffsetToLrc();
        const header = `[ ${new Date().toISOString().slice(0,10)} ]\n`;
        const lines = modified.map(l => `[${formatTime(l.times[0])}] ${l.text}`).join('\n');
        const blob = new Blob([header + lines], { type: 'text/plain;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `karaoke-synced-${Date.now()}.lrc`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(url), 1000);
      }

      function handleFile(file, infoEl) {
        if (!file) return;
        const reader = new FileReader();
        reader.onload = () => {
          infoEl.innerHTML = `<strong>${file.name}</strong> · ${formatBytes(file.size)} · ${file.type || 'unknown'}`;
        };
        reader.readAsText(file);
      }

      function formatBytes(b) {
        if (b < 1024) return b + ' B';
        if (b < 1024 * 1024) return (b / 1024).toFixed(1) + ' KB';
        return (b / (1024 * 1024)).toFixed(2) + ' MB';
      }

      audioBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = 'audio/*';
        input.onchange = (ev) => {
          const f = ev.target.files[0];
          if (f) {
            audio.src = URL.createObjectURL(f);
            audioInfo.innerHTML = `<strong>${f.name}</strong> · ${formatBytes(f.size)} · ${f.type || 'audio'} · ${formatTime(getAudioDuration())}`;
          }
        };
        input.click();
      });

      lrcBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        const input = document.createElement('input');
        input.type = 'file';
        input.accept = '.lrc';
        input.onchange = (ev) => {
          const f = ev.target.files[0];
          if (f) {
            lrcInfo.innerHTML = `<strong>${f.name}</strong> · ${formatBytes(f.size)}`;
            const text = f.text();
            lyricsData = parseLrc(text);
            renderLyrics();
            // Build times array for each word
            for (const l of lyricsData) {
              l.words = splitIntoWords(l.text);
              l.times = [];
              for (let i = 0; i < l.words.length; i++) {
                l.times.push(l.time + (i / l.words.length) * (lyricsData[lyricsData.indexOf(l)].time - l.time));
              }
            }
            // Update controls
            const dur = getAudioDuration();
            if (dur > 0) {
              playBtn.disabled = false;
              pauseBtn.disabled = true;
              stopBtn.disabled = false;
              seekBack.disabled = false;
              seekFwd.disabled = false;
              exportBtn.disabled = false;
            }
          }
        };
        input.click();
      });

      playBtn.addEventListener('click', () => {
        if (!audio.src || !audio.duration) return;
        playing = true;
        audio.play().then(() => {
          playBtn.disabled = true;
          pauseBtn.disabled = false;
          updateHighlight();
          updateStatus();
          if (timer) clearInterval(timer);
          timer = setInterval(() => {
            updateHighlight();
            updateStatus();
          }, 150);
        }).catch(() => {
          alert('Unable to play audio. Please check your browser permissions.');
        });
      });

      pauseBtn.addEventListener('click', () => {
        if (!audio.src) return;
        playing = false;
        audio.pause();
        playBtn.disabled = false;
        pauseBtn.disabled = true;
      });

      stopBtn.addEventListener('click', () => {
        if (!audio.src) return;
        audio.pause();
        audio.currentTime = 0;
        currentOffset = 0;
        offsetInput.value = 0;
        offsetValue.textContent = '0.00';
        playing = false;
        playBtn.disabled = false;
        pauseBtn.disabled = true;
        updateHighlight();
        updateStatus();
        if (timer) clearInterval(timer);
      });

      seekBack.addEventListener('click', () => {
        if (!audio.src) return;
        audio.currentTime = Math.max(0, audio.currentTime - 10);
        lastSeek = audio.currentTime;
        updateHighlight();
      });

      seekFwd.addEventListener('click', () => {
        if (!audio.src) return;
        audio.currentTime = Math.min(audio.duration || 0, audio.currentTime + 10);
        lastSeek = audio.currentTime;
        updateHighlight();
      });

      offsetInput.addEventListener('input', () => {
        currentOffset = parseFloat(offsetInput.value);
        offsetValue.textContent = currentOffset.toFixed(2);
        updateHighlight();
      });

      audio.addEventListener('timeupdate', () => {
        if (!playing) return;
        updateHighlight();
        updateStatus();
      });

      audio.addEventListener('ended', () => {
        playing = false;
        audio.currentTime = 0;
        currentOffset = 0;
        offsetInput.value = 0;
        offsetValue.textContent = '0.00';
        playBtn.disabled = false;
        pauseBtn.disabled = true;
        updateHighlight();
        updateStatus();
        if (timer) clearInterval(timer);
      });

      audio.addEventListener('loadedmetadata', () => {
        const dur = getAudioDuration();
        if (dur > 0) {
          playBtn.disabled = false;
          pauseBtn.disabled = true;
          stopBtn.disabled = false;
          seekBack.disabled = false;
          seekFwd.disabled = false;
          exportBtn.disabled = false;
        }
      });

      audio.addEventListener('error', () => {
        playBtn.disabled = true;
        pauseBtn.disabled = true;
        stopBtn.disabled = true;
        seekBack.disabled = true;
        seekFwd.disabled = true;
        exportBtn.disabled = true;
      });

      exportBtn.addEventListener('click', exportLrc);

      // Keyboard shortcuts
      document.addEventListener('keydown', (e) => {
        if (e.target.tagName === 'INPUT') return;
        if (e.code === 'Space') {
          e.preventDefault();
          if (audio.paused) playBtn.click(); else pauseBtn.click();
        } else if (e.key === 'ArrowLeft') seekBack.click();
        else if (e.key === 'ArrowRight') seekFwd.click();
      });

      // Initial render
      renderLyrics();
    })();
  </script>
</body>
</html>
```

---

## How It Works

1. **File Upload**:
   - Audio: any supported format (MP3, OGG, WAV, etc.).
   - LRC: plain text with `[mm]:ss.xx text` format.

2. **Parsing**:
   - LRC lines are parsed into `{ time, text }` pairs.
   - Each line is split into words for per-word highlighting.

3. **Timing**:
   - Current audio time + offset is used to find the active word.
   - Words are highlighted with a fade animation via CSS transition.

4. **Offset**:
   - Applied by shifting the `time` value of each line.
   - Exported LRC reflects the new timing.

5. **Playback**:
   - Real-time highlighting via `setInterval`.
   - Smooth seek with `lastSeek` to avoid jumps.

---

## Limitations & Notes

- LRC timing is **per-line**, not per-word. The tool splits lines into words for highlighting, but the timing is still line-based. For true per-word sync, you'd need per-word LRC (rare).
- Audio duration must be loaded before controls become active.
- Exported LRC uses the same `[mm]:ss.xx` format.
- Works best with modern browsers supporting the `<audio>` element.

