  triangle: { label: 'Triangle', group: 'triangleGroup', inputs: ['t-a','t-b','t-c'], params: ['a','b','c'], formulas: { area: 'A = √[s(s−a)(s−b)(s−c)] (Heron)', perimeter: 'P = a + b + c', volume: 'Not applicable', surface: 'Not applicable' } },
  polygon: { label: 'Regular Polygon', group: 'polygonGroup', inputs: ['polySides','polySide'], params: ['n','s'], formulas: { area: 'A = (n·s²)/(4·tan(π/n))', perimeter: 'P = n·s', volume: 'Not applicable', surface: 'Not applicable' } },
  rectangle: { label: 'Rectangle', group: 'rectangleGroup', inputs: ['r-length','r-width'], params: ['l','w'], formulas: { area: 'A = l·w', perimeter: 'P = 2(l + w)', volume: 'Not applicable', surface: 'Not applicable' } },
  sphere: { label: 'Sphere', group: 'sphereGroup', inputs: ['s-radius'], params: ['r'], formulas: { area: 'A = 4πr²', perimeter: 'Not applicable', volume: 'V = (4/3)πr³', surface: 'A = 4πr²' } },
  cylinder: { label: 'Cylinder', group: 'cylinderGroup', inputs: ['cy-radius','cy-height'], params: ['r','h'], formulas: { area: 'A = 2πr(h + r)', perimeter: 'Not applicable', volume: 'V = πr²h', surface: 'A = 2πr(h + r)' } },
  cone: { label: 'Cone', group: 'coneGroup', inputs: ['co-radius','co-height'], params: ['r','h'], formulas: { area: 'A = πr(r + √(r² + h²))', perimeter: 'Not applicable', volume: 'V = (1/3)πr²h', surface: 'A = πr(r + √(r² + h²))' } },
  prism: { label: 'Rectangular Prism', group: 'prismGroup', inputs: ['pr-base','pr-width','pr-height'], params: ['l','w','h'], formulas: { area: 'A = 2(lw + lh + wh)', perimeter: 'Not applicable', volume: 'V = l·w·h', surface: 'A = 2(lw + lh + wh)' } }
};

const CHIPS = ['area','perimeter','volume','surface'];

// ---------- State ----------
const state = {
  shape: 'circle',
  params: {},
  results: { area: 0, perimeter: 0, volume: 0, surface: 0 },
  formulas: {}
};

// ---------- DOM ----------
const $ = (id) => document.getElementById(id);
const canvas = $('preview');
const ctx = canvas.getContext('2d');
const canvasWrap = $('canvasWrap');
const canvasEmpty = $('canvasEmpty');
const shapeSelect = $('shapeSelect');
const resultGrid = $('resultGrid');
const formulaList = $('formulaList');
const showFormulas = $('showFormulas');
const toast = $('toast');

// ---------- Build UI ----------
Object.keys(SHAPES).forEach((key) => {
  const sh = SHAPES[key];
  const opt = document.createElement('option');
  opt.value = key;
  opt.textContent = sh.label;
  shapeSelect.appendChild(opt);
});

// ---------- Helpers ----------
function showToast(msg) {
  toast.textContent = msg;
  toast.classList.add('show');
  clearTimeout(showToast._t);
  showToast._t = setTimeout(() => toast.classList.remove('show'), 2400);
}

function validateInputs() {
  const sh = SHAPES[state.shape];
  let ok = true;
  sh.inputs.forEach(id => {
    const el = document.getElementById(id);
    const val = parseFloat(el.value);
    const valid = !isNaN(val) && val >= 0;
    el.classList.toggle('valid', valid);
    el.classList.toggle('invalid', !valid);
    if (!valid) ok = false;
  });
  return ok;
}

function parseParams() {
  const sh = SHAPES[state.shape];
  const params = {};
  sh.inputs.forEach(id => {
    const val = parseFloat(document.getElementById(id).value);
    params[sh.params[sh.inputs.indexOf(id)]] = val;
  });
  return params;
}

function compute(shapeKey, params) {
  const sh = SHAPES[shapeKey];
  const { area, perimeter, volume, surface } = sh.formulas;
  let out = { area: 0, perimeter: 0, volume: 0, surface: 0 };

  if (shapeKey === 'circle') {
    const r = params.r;
    out.area = Math.PI * r * r;
    out.perimeter = 2 * Math.PI * r;
  } else if (shapeKey === 'triangle') {
    const a = params.a, b = params.b, c = params.c;
    const s = (a + b + c) / 2;
    const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));
    out.area = area;
    out.perimeter = a + b + c;
  } else if (shapeKey === 'polygon') {
    const n = params.n, s = params.s;
    out.area = (n * s * s) / (4 * Math.tan(Math.PI / n));
    out.perimeter = n * s;
  } else if (shapeKey === 'rectangle') {
    const l = params.l, w = params.w;
    out.area = l * w;
    out.perimeter = 2 * (l + w);
  } else if (shapeKey === 'sphere') {
    const r = params.r;
    out.area = 4 * Math.PI * r * r;
    out.volume = (4/3) * Math.PI * r * r * r;
    out.surface = 4 * Math.PI * r * r;
  } else if (shapeKey === 'cylinder') {
    const r = params.r, h = params.h;
    out.area = 2 * Math.PI * r * (h + r);
    out.volume = Math.PI * r * r * h;
    out.surface = 2 * Math.PI * r * (h + r);
  } else if (shapeKey === 'cone') {
    const r = params.r, h = params.h;
    const slant = Math.sqrt(r * r + h * h);
    out.area = Math.PI * r * (r + slant);
    out.volume = (1/3) * Math.PI * r * r * h;
    out.surface = Math.PI * r * (r + slant);
  } else if (shapeKey === 'prism') {
    const l = params.l, w = params.w, h = params.h;
    out.area = 2 * (l * w + l * h + w * h);
    out.volume = l * w * h;
    out.surface = 2 * (l * w + l * h + w * h);
  }

  return out;
}

function renderResults() {
  const sh = SHAPES[state.shape];
  const params = parseParams();
  const vals = compute(state.shape, params);
  state.results = vals;

  resultGrid.innerHTML = '';
  const chipMap = {
    area: 'Area',
    perimeter: 'Perimeter',
    volume: 'Volume',
    surface: 'Surface Area'
  };
  CHIPS.forEach(chip => {
    const val = vals[chip];
    const card = document.createElement('div');
    card.className = 'result-card';
    card.innerHTML = `
      <div class="result-label">${chipMap[chip]}</div>
      <div class="result-value">${val.toFixed(2)} cm²</div>
    `;
    resultGrid.appendChild(card);
  });
}

function renderFormulas() {
  const sh = SHAPES[state.shape];
  const show = showFormulas.checked;
  const list = document.getElementById('formulaList');
  list.innerHTML = '';
  Object.entries(sh.formulas).forEach(([key, formula]) => {
    const li = document.createElement('div');
    li.className = 'formula';
    li.innerHTML = `<strong>${key}:</strong> ${formula}`;
    list.appendChild(li);
  });
  $('formulaSection').classList.toggle('show', show);
}

function renderPreview() {
  const sh = SHAPES[state.shape];
  const params = parseParams();
  const chip = document.querySelector('.chip.active');
  const chipKey = chip ? chip.dataset.chip : 'area';

  const W = canvasWrap.clientWidth;
  const H = canvasWrap.clientHeight;
  const scale = Math.min(W / 400, H / 400) * 0.9;
  const pad = 40;
  const cx = W / 2;
  const cy = H / 2;
  const maxR = Math.min(W, H) / 2 - pad;

  ctx.clearRect(0, 0, W, H);

  // Background grid
  ctx.save();
  ctx.strokeStyle = 'rgba(148,163,184,0.15)';
  ctx.lineWidth = 1;
  const gridStep = 20;
  for (let x = -maxR; x <= maxR; x += gridStep) {
    ctx.beginPath();
    ctx.moveTo(cx + x, pad);
    ctx.lineTo(cx + x, H - pad);
    ctx.stroke();
  }
  for (let y = pad; y <= H - pad; y += gridStep) {
    ctx.beginPath();
    ctx.moveTo(pad, cy + y);
    ctx.lineTo(W - pad, cy + y);
    ctx.stroke();
  }
  ctx.restore();

  // Draw shape
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);

  const draw = {
    circle: () => {
      const r = params.r;
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.strokeStyle = '#4a6cf7';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = 'rgba(74,108,247,0.12)';
      ctx.fill();
      // Label
      ctx.fillStyle = '#1e293b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('r', 0, r + 6);
    },
    triangle: () => {
      const a = params.a, b = params.b, c = params.c;
      const s = (a + b + c) / 2;
      const area = Math.sqrt(s * (s - a) * (s - b) * (s - c));
      const angleB = Math.acos((a*a + c*c - b*b) / (2*a*c));
      const angleC = Math.acos((a*a + b*b - c*c) / (2*a*b));
      const angleA = Math.PI - angleB - angleC;
      const h = c * Math.sin(angleA);
      const x = (a * Math.cos(angleA)) + (b * Math.cos(angleC));
      const y = (a * Math.sin(angleA)) + (b * Math.sin(angleC));
      ctx.beginPath();
      ctx.moveTo(0, 0);
      ctx.lineTo(x, y);
      ctx.lineTo(b * Math.cos(angleC), b * Math.sin(angleC));
      ctx.closePath();
      ctx.strokeStyle = '#0ea5e9';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = 'rgba(14,165,233,0.12)';
      ctx.fill();
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('a', x/2, y/2 + 4);
      ctx.fillText('b', b*Math.cos(angleC)/2, b*Math.sin(angleC)/2 + 4);
      ctx.fillText('c', x/2, y/2 + 4);
    },
    polygon: () => {
      const n = params.n, s = params.s;
      const R = s / (2 * Math.sin(Math.PI / n));
      const pts = [];
      for (let i = 0; i < n; i++) {
        pts.push({ x: Math.cos(i * Math.PI * 2 / n) * R, y: Math.sin(i * Math.PI * 2 / n) * R });
      }
      ctx.beginPath();
      ctx.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < n; i++) ctx.lineTo(pts[i].x, pts[i].y);
      ctx.closePath();
      ctx.strokeStyle = '#0ea5e9';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = 'rgba(14,165,233,0.12)';
      ctx.fill();
      // Center label
      ctx.fillStyle = '#1e293b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('n=' + n, 0, 0);
    },
    rectangle: () => {
      const l = params.l, w = params.w;
      ctx.strokeRect(-l/2, -w/2, l, w);
      ctx.fillRect(-l/2, -w/2, l, w);
      ctx.fillStyle = 'rgba(74,108,247,0.12)';
      ctx.fill();
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('l', 0, w/2 + 4);
      ctx.fillText('w', l/2 + 4, 0);
    },
    sphere: () => {
      const r = params.r;
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.strokeStyle = '#4a6cf7';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.fillStyle = 'rgba(74,108,247,0.12)';
      ctx.fill();
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('r', 0, r + 6);
    },
    cylinder: () => {
      const r = params.r, h = params.h;
      ctx.save();
      ctx.translate(0, -h/2);
      ctx.scale(1, 0.6);
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.stroke();
      ctx.restore();
      ctx.strokeStyle = '#0ea5e9';
      ctx.lineWidth = 2;
      ctx.strokeRect(-r, -h/2, r*2, h);
      ctx.fillStyle = 'rgba(14,165,233,0.12)';
      ctx.fillRect(-r, -h/2, r*2, h);
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('r', 0, -h/2 + 4);
      ctx.fillText('h', 0, h/2 + 4);
    },
    cone: () => {
      const r = params.r, h = params.h;
      const slant = Math.sqrt(r*r + h*h);
      ctx.save();
      ctx.translate(0, -h/2);
      ctx.beginPath();
      ctx.moveTo(-r, 0);
      ctx.lineTo(0, slant);
      ctx.lineTo(r, 0);
      ctx.closePath();
      ctx.stroke();
      ctx.fillStyle = 'rgba(14,165,233,0.12)';
      ctx.fill();
      ctx.restore();
      ctx.strokeStyle = '#0ea5e9';
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(0, 0, r, 0, Math.PI * 2);
      ctx.stroke();
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('r', 0, r + 6);
      ctx.fillText('h', 0, -h/2 + 4);
    },
    prism: () => {
      const l = params.l, w = params.w, h = params.h;
      const x = -l/2, y = -w/2;
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.lineTo(x, y + h);
      ctx.lineTo(x + l, y + h);
      ctx.lineTo(x + l, y);
      ctx.closePath();
      ctx.stroke();
      ctx.fillStyle = 'rgba(74,108,247,0.12)';
      ctx.fill();
      // Labels
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('l', x + l/2, y + h/2);
      ctx.fillText('w', x + l/2, y + h/2);
      ctx.fillText('h', x + l/2, y + h/2);
    }
  };

  if (draw[state.shape]) draw[state.shape]();
  ctx.restore();

  // Dimension label
  ctx.save();
  ctx.translate(cx, cy);
  ctx.scale(scale, scale);
  ctx.fillStyle = '#1e293b';
  ctx.font = '14px sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText(state.shape.toUpperCase(), 0, 0);
  ctx.restore();
}

function renderAll() {
  renderPreview();
  renderResults();
  renderFormulas();
}

// ---------- Events ----------
shapeSelect.addEventListener('change', (e) => {
  const key = e.target.value;
  state.shape = key;
  Object.keys(SHAPES).forEach(k => {
    const group = document.getElementById(SHAPES[k].group);
    group.style.display = k === key ? '' : 'none';
  });
  canvasEmpty.style.display = 'none';
  canvas.style.display = '';
  renderAll();
});

CHIPS.forEach(chip => {
  document.querySelector(`.chip[data-chip="${chip}"]`).addEventListener('click', () => {
    document.querySelectorAll('.chip').forEach(c => c.classList.remove('active'));
    document.querySelector(`.chip[data-chip="${chip}"]`).classList.add('active');
  });
});

document.getElementById('calcBtn').addEventListener('click', () => {
  if (!validateInputs()) {
    showToast('Please enter valid non-negative dimensions.');
    return;
  }
  renderAll();
});

document.getElementById('resetBtn').addEventListener('click', () => {
  Object.keys(SHAPES).forEach(k => {
    const group = document.getElementById(SHAPES[k].group);
    group.style.display = 'none';
  });
  state.shape = 'circle';
  shapeSelect.value = 'circle';
  document.getElementById('c-radius').value = 5;
  canvasEmpty.style.display = '';
  canvas.style.display = 'none';
  renderAll();
});

showFormulas.addEventListener('change', renderFormulas);

// Input validation on blur
['c-radius','t-a','t-b','t-c','polySide','polySides','r-length','r-width','s-radius','cy-radius','cy-height','co-radius','co-height','pr-base','pr-width','pr-height'].forEach(id => {
  const el = document.getElementById(id);
  el.addEventListener('blur', () => {
    if (el.value === '' || el.value === '0') {
      el.classList.remove('valid','invalid');
    } else {
      const val = parseFloat(el.value);
      const ok = !isNaN(val) && val >= 0;
      el.classList.toggle('valid', ok);
      el.classList.toggle('invalid', !ok);
    }
  });
});

// Resize
let resizeTimer;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimer);
  resizeTimer = setTimeout(renderAll, 100);
});

// Initial
renderAll();
</script>

</body>
</html>
```

