    to { opacity: 1; transform: translateY(0); }
  }
</style>
</head>
<body>

<div class="card">
  <h1>Rhythm Trainer</h1>
  <p class="subtitle">Listen to the beat and tap the button in time. Your accuracy is scored by how close you are to the target.</p>

  <div class="controls">
    <label for="bpm">BPM: <strong id="bpmVal">120</strong></label>
    <input type="range" id="bpm" min="60" max="200" value="120" step="1">
  </div>

  <div class="controls">
    <label for="pattern">Pattern:</label>
    <select id="pattern">
      <option value="4">4/4</option>
      <option value="3">3/4</option>
      <option value="6">6/4</option>
    </select>
  </div>

  <div class="controls">
    <label for="bars">Bars:</label>
    <select id="bars">
      <option value="1">1 bar</option>
      <option value="2">2 bars</option>
      <option value="4" selected>4 bars</option>
      <option value="8">8 bars</option>
    </select>
  </div>

  <div class="metronome">
    <span class="label">Metronome</span>
    <div id="dots" class="dots"></div>
  </div>

  <div class="tap-area">
    <button id="startBtn" class="tap-btn">Start / Stop</button>
    <button id="resetBtn" class="reset-btn">Reset Round</button>
  </div>

  <div class="score">
    <span class="label">Current Score</span>
    <span id="scoreVal">0.00</span>
  </div>

  <div id="finalScore" class="final-score hidden">
    <h3>Round Complete</h3>
    <div class="value" id="finalScoreVal">0.00</div>
    <div class="meta" id="finalMeta">Beats: 0 | Accuracy: 0%</div>
  </div>

  <div class="stats">
    <div class="stat"><span class="k">Beats</span><span class="v" id="statBeats">0</span></div>
    <div class="stat"><span class="k">Hits</span><span class="v" id="statHits">0</span></div>
    <div class="stat"><span class="k">Accuracy</span><span class="v" id="statAcc">0%</span></div>
    <div class="stat"><span class="k">Avg. Offset</span><span class="v" id="statOffset">0ms</span></div>
  </div>
</div>

<script>
  (function () {
    'use strict';

    const bpmEl = document.getElementById('bpm');
    const bpmVal = document.getElementById('bpmVal');
    const patternEl = document.getElementById('pattern');
    const barsEl = document.getElementById('bars');
    const startBtn = document.getElementById('startBtn');
    const resetBtn = document.getElementById('resetBtn');
    const scoreVal = document.getElementById('scoreVal');
    const finalScore = document.getElementById('finalScore');
    const finalScoreVal = document.getElementById('finalScoreVal');
    const finalMeta = document.getElementById('finalMeta');
    const statBeats = document.getElementById('statBeats');
    const statHits = document.getElementById('statHits');
    const statAcc = document.getElementById('statAcc');
    const statOffset = document.getElementById('statOffset');
    const dotsContainer = document.getElementById('dots');

    const state = {
      bpm: 120,
      pattern: 4,
      bars: 4,
      totalBeats: 0,
      beatIndex: 0,
      nextBeatTime: 0,
      startTime: 0,
      playing: false,
      audioCtx: null,
      oscillators: [],
      hits: [],
      misses: [],
      yellow: [],
      elapsed: 0,
      score: 0,
      taps: 0,
      lastBeatMs: 0,
    };

    // Build dots row
    function buildDots() {
      dotsContainer.innerHTML = '';
      const total = state.bars * state.pattern;
      for (let i = 0; i < total; i++) {
        const d = document.createElement('span');
        d.className = 'dot';
        dotsContainer.appendChild(d);
      }
    }

    function setBpm(v) {
      state.bpm = Math.max(60, Math.min(200, parseInt(v, 10) || 120));
      bpmVal.textContent = state.bpm;
      // Recompute total beats
      state.totalBeats = state.bars * state.pattern;
      state.beatIndex = 0;
      state.nextBeatTime = 0;
      state.lastBeatMs = 0;
    }

    function scheduleBeats() {
      const barBeats = state.pattern;
      const beatsPerBar = barBeats;
      const beatsPerMinute = state.bpm;
      const beatDurationMs = (60 * 1000) / beatsPerMinute;
      const barDurationMs = beatDurationMs * beatsPerBar;

      state.totalBeats = state.bars * beatsPerBar;
      state.beatIndex = 0;
      state.nextBeatTime = performance.now() + 500; // offset start
      state.lastBeatMs = 0;

      // Reset feedback
      dotsContainer.querySelectorAll('.dot').forEach((d, i) => {
        d.classList.remove('active', 'hit', 'miss', 'yellow');
      });
    }

    function playBeat() {
      const ctx = state.audioCtx;
      if (!ctx) return;

      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.type = 'sine';
      osc.frequency.setValueAtTime(220 + Math.random() * 100, now);
      gain.gain.setValueAtTime(0.0001, now);
      gain.gain.exponentialRampToValueAtTime(0.15, now + 0.05);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.25);
      osc.connect(gain).connect(ctx.destination);
      osc.start(now);
      osc.stop(now + 0.3);

      state.oscillators.push(osc);
      state.lastBeatMs = performance.now();
    }

    function tick() {
      if (!state.playing || state.beatIndex >= state.totalBeats) return;
      const d = state.nextBeatTime - performance.now();
      if (d <= 0) {
        playBeat();
        const dot = dotsContainer.children[state.beatIndex];
        if (dot) dot.classList.add('active');
        state.beatIndex++;
        state.nextBeatTime = performance.now() + (60 * 1000) / state.bpm;
        requestAnimationFrame(tick);
      } else {
        requestAnimationFrame(tick);
      }
    }

    function startLoop() {
      if (!state.audioCtx) {
        try {
          state.audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        } catch (e) {
          alert('Audio not supported in this browser.');
          return;
        }
      }
      state.audioCtx.resume();
      scheduleBeats();
      state.playing = true;
      state.startTime = performance.now();
      state.hits = [];
      state.misses = [];
      state.yellow = [];
      state.taps = 0;
      state.score = 0;
      state.elapsed = 0;
      state.lastBeatMs = 0;
      scoreVal.textContent = '0.00';
      finalScore.classList.add('hidden');
      startBtn.textContent = 'Stop';
      tick();
    }

    function stopLoop() {
      state.playing = false;
      state.oscillators.forEach(o => {
        try { o.stop(); } catch (e) {}
      });
      state.oscillators = [];
      startBtn.textContent = 'Start';
    }

    function resetRound() {
      stopLoop();
      state.beatIndex = 0;
      state.nextBeatTime = 0;
      state.taps = 0;
      state.hits = [];
      state.misses = [];
      state.yellow = [];
      state.score = 0;
      state.elapsed = 0;
      scoreVal.textContent = '0.00';
      statBeats.textContent = '0';
      statHits.textContent = '0';
      statAcc.textContent = '0%';
      statOffset.textContent = '0ms';
      finalScore.classList.add('hidden');
      startBtn.textContent = 'Start';
    }

    function tolerance() {
      return 1200 / state.bpm; // tighter at higher BPM
    }

    function evaluateTap(ts) {
      if (!state.playing || state.beatIndex >= state.totalBeats) return;
      const target = state.nextBeatTime;
      const diff = Math.abs(ts - target);
      const tol = tolerance();
      const factor = Math.max(0, 1 - diff / tol);
      state.score += factor;
      state.taps++;

      const dot = dotsContainer.children[state.beatIndex];
      if (dot) {
        dot.classList.remove('active', 'hit', 'miss', 'yellow');
        if (factor >= 0.95) dot.classList.add('hit');
        else if (factor >= 0.5) dot.classList.add('yellow');
        else dot.classList.add('miss');
      }

      state.hits.push(factor >= 0.95 ? 1 : 0);
      state.misses.push(factor < 0.5 ? 1 : 0);
      state.yellow.push(factor >= 0.5 && factor < 0.95 ? 1 : 0);

      // Update stats
      statBeats.textContent = state.beatIndex;
      statHits.textContent = state.hits.length;
      statAcc.textContent = Math.round(state.score / Math.max(1, state.taps) * 100) + '%';
      statOffset.textContent = Math.round(diff) + 'ms';

      // Final score card
      if (state.beatIndex >= state.totalBeats) {
        const avg = state.taps > 0 ? state.score / state.taps : 0;
        const hitsPct = state.hits.length > 0 ? (state.hits.reduce((a, b) => a + b, 0) / state.hits.length) * 100 : 0;
        finalScoreVal.textContent = avg.toFixed(2);
        finalMeta.textContent = `Beats: ${state.totalBeats} | Accuracy: ${hitsPct.toFixed(1)}%`;
        finalScore.classList.remove('hidden');
      }

      // Schedule next
      state.nextBeatTime = performance.now() + (60 * 1000) / state.bpm;
      requestAnimationFrame(tick);
    }

    // Events
    bpmEl.addEventListener('input', e => setBpm(e.target.value));
    patternEl.addEventListener('change', () => {
      state.pattern = parseInt(patternEl.value, 10);
      state.totalBeats = state.bars * state.pattern;
      state.beatIndex = 0;
      state.nextBeatTime = 0;
      buildDots();
    });
    barsEl.addEventListener('change', () => {
      state.bars = parseInt(barsEl.value, 10);
      state.totalBeats = state.bars * state.pattern;
      state.beatIndex = 0;
      state.nextBeatTime = 0;
      buildDots();
    });
    startBtn.addEventListener('click', () => {
      if (state.playing) stopLoop();
      else startLoop();
    });
    resetBtn.addEventListener('click', resetRound);

    // Tap button
    const tapBtn = document.getElementById('startBtn');
    tapBtn.addEventListener('click', () => {
      if (state.playing) {
        const now = performance.now();
        evaluateTap(now);
      }
    });

    // Prevent double-fire on double-click
    let lastTap = 0;
    tapBtn.addEventListener('mousedown', (e) => {
      if (performance.now() - lastTap < 150) return;
      lastTap = performance.now();
      if (state.playing) {
        const now = performance.now();
        evaluateTap(now);
      }
    });

    // Keyboard tap (space)
    document.addEventListener('keydown', (e) => {
      if (e.code === 'Space' && document.activeElement !== tapBtn) {
        e.preventDefault();
        if (state.playing) {
          const now = performance.now();
          evaluateTap(now);
        }
      }
    });

    // Init
    buildDots();
    setBpm(bpmEl.value);
    scoreVal.textContent = '0.00';
    statAcc.textContent = '0%';
  })();
</script>

</body>
</html>
```

---

### 📱 How to Use

1. **Adjust BPM** (60–200) with the slider.
2. **Choose a pattern** (4/4, 3/4, 6/4) — 6/4 means 6 beats per bar (common in flamenco).
3. **Select bars** (1–8).
4. **Start** the round and tap the button as the dots pulse.
5. **Green** = perfect, **yellow** = good, **red** = missed.
6. **Stop** to see your score.
7. **Reset** to replay.

---

### 📊 Scoring Deep Dive

- **Tolerance** = `1200 / BPM` ms. At 120 BPM → 10ms; at 60 BPM → 20ms.
- **Score per tap** = `1 - (|user - target| / tolerance)`
- **Total score** = average of all taps.
- **Accuracy %** = percentage of taps within tolerance (not necessarily perfect).

---

### 🔊 Audio

Uses Web Audio API. If audio is muted or blocked, the app will alert.

