// =========================================================
// Geometric Proof System
// =========================================================
// A web-based interactive geometric proof assistant.
// Users draw figures, add conditions, and the system
// automatically builds a proof tree with derivations.
// =========================================================

(function () {
  'use strict';

  // ---------- Canvas & UI ----------
  const canvas = document.getElementById('canvas');
  const ctx = canvas.getContext('2d');
  const toolSelect = document.getElementById('tool');
  const conditionInput = document.getElementById('condition-input');
  const conditionBtn = document.getElementById('condition-btn');
  const verifyBtn = document.getElementById('verify-btn');
  const proofTree = document.getElementById('proof-tree');
  const proofView = document.getElementById('proof-view');
  const stepList = document.getElementById('step-list');
  const clearBtn = document.getElementById('clear-btn');
  const undoBtn = document.getElementById('undo-btn');
  const redoBtn =.getElementById('redo-btn');
  const stepsHistory = [];

  let currentTool = 'point';
  let points = [];
  let currentPath = [];
  let selectedPoint = null;
  let selectedCondition = null;
  let historyIndex = -1;
  let redoStack = [];
  let proofSteps = [];
  let currentStep = 0;

  // ---------- State ----------
  const state = {
    points: [],
    conditions: [],
    figures: [],
    proof: [],
  };

  // ---------- Resize ----------
  function resizeCanvas() {
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width * devicePixelRatio;
    canvas.height = rect.height * devicePixelRatio;
    ctx.setTransform(devicePixelRatio, 0, 0, devicePixelRatio, 0, 0);
    redraw();
  }

  // ---------- Drawing ----------
  function redraw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawGrid();
    drawPoints();
    drawLines();
    drawConditions();
    drawSelected();
  }

  function drawGrid() {
    ctx.strokeStyle = 'rgba(120,120,120,0.25)';
    ctx.lineWidth = 1;
    const w = canvas.clientWidth;
    const h = canvas.clientHeight;
    const step = 50;
    for (let x = 0; x <= w; x += step) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, h);
      ctx.stroke();
    }
    for (let y = 0; y <= h; y += step) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(w, y);
      ctx.stroke();
    }
  }

  function drawPoints() {
    points.forEach((p) => {
      ctx.beginPath();
      ctx.arc(p.x, p.y, 5, 0, Math.PI * 2);
      ctx.fillStyle = p.selected ? '#ff6b6b' : '#3a7bd5';
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1.5;
      ctx.stroke();
    });
  }

  function drawLines() {
    // Segments
    state.figures.forEach((fig) => {
      if (fig.type === 'segment') {
        ctx.beginPath();
        ctx.moveTo(fig.p1.x, fig.p1.y);
        ctx.lineTo(fig.p2.x, fig.p2.y);
        ctx.strokeStyle = '#3a7bd5';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });

    // Triangles
    state.figures.forEach((fig) => {
      if (fig.type === 'triangle') {
        ctx.beginPath();
        ctx.moveTo(fig.p1.x, fig.p1.y);
        ctx.lineTo(fig.p2.x, fig.p2.y);
        ctx.lineTo(fig.p3.x, fig.p3.y);
        ctx.closePath();
        ctx.fillStyle = 'rgba(230, 126, 17, 0.08)';
        ctx.fill();
        ctx.strokeStyle = '#e67e10';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });

    // Circles
    state.figures.forEach((fig) => {
      if (fig.type === 'circle') {
        ctx.beginPath();
        ctx.arc(fig.center.x, fig.center.y, fig.radius, 0, Math.PI * 2);
        ctx.strokeStyle = '#1e88e5';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });
  }

  function drawConditions() {
    state.conditions.forEach((cond) => {
      const p1 = points.find((p) => p.id === cond.p1);
      const p2 = points.find((p) => p.id === cond.p2);
      if (!p1 || !p2) return;

      ctx.font = '12px "SF Pro Text", system-ui, sans-serif';
      ctx.fillStyle = '#2a2a2a';
      ctx.textAlign = 'center';

      // Angle condition
      if (cond.type === 'angle') {
        ctx.save();
        ctx.translate(p1.x, p1.y);
        ctx.rotate((Math.atan2(p2.y - p1.y, p2.x - p1.x) + Math.PI) % (Math.PI * 2) - Math.PI);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(0, -10);
        ctx.lineTo(-6, 0);
        ctx.lineTo(0, 10);
        ctx.closePath();
        ctx.fillStyle = '#e67e10';
        ctx.fill();
        ctx.fillStyle = '#2a2a2a';
        ctx.font = 'bold 14px "SF Pro Text", system-ui, sans-serif';
        ctx.fillText(`${cond.value}°`, 0, 0);
        ctx.restore();
      }

      // Equal length
      if (cond.type === 'equal') {
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = '#27ae60';
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(p1.x - 8, p1.y - 8);
        ctx.lineTo(p1.x + 8, p1.y + 8);
        ctx.moveTo(p1.x + 8, p1.y - 8);
        ctx.lineTo(p1.x - 8, p1.y + 8);
        ctx.moveTo(p2.x - 8, p2.y - 8);
        ctx.lineTo(p2.x + 8, p2.y + 8);
        ctx.moveTo(p2.x + 8, p2.y - 8);
        ctx.lineTo(p2.x - 8, p2.y + 8);
        ctx.strokeStyle = '#27ae60';
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      // Parallel
      if (cond.type === 'parallel') {
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = '#8e44ad';
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(p1.x - 6, p1.y - 6);
        ctx.lineTo(p1.x + 6, p1.y + 6);
        ctx.moveTo(p1.x + 6, p1.y - 6);
        ctx.lineTo(p1.x - 6, p1.y + 6);
        ctx.moveTo(p2.x - 6, p2.y - 6);
        ctx.lineTo(p2.x + 6, p2.y + 6);
        ctx.moveTo(p2.x + 6, p2.y - 6);
        ctx.lineTo(p2.x - 6, p2.y + 6);
        ctx.strokeStyle = '#8e44ad';
        ctx.lineWidth = 2;
        ctx.stroke();
      }

      // Right angle
      if (cond.type === 'right') {
        ctx.save();
        ctx.translate(p1.x, p1.y);
        ctx.rotate((Math.atan2(p2.y - p1.y, p2.x - p1.x) + Math.PI) % (Math.PI * 2) - Math.PI);
        ctx.beginPath();
        ctx.moveTo(0, 0);
        ctx.lineTo(0, -10);
        ctx.lineTo(-6, 0);
        ctx.closePath();
        ctx.fillStyle = '#e67e10';
        ctx.fill();
        ctx.restore();
      }

      // Congruent triangles
      if (cond.type === 'congruent') {
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = '#27ae60';
        ctx.lineWidth = 3;
        ctx.stroke();
        ctx.beginPath();
        ctx.moveTo(p1.x - 8, p1.y - 8);
        ctx.lineTo(p1.x + 8, p1.y + 8);
        ctx.moveTo(p1.x + 8, p1.y - 8);
        ctx.lineTo(p1.x - 8, p1.y + 8);
        ctx.moveTo(p2.x - 8, p2.y - 8);
        ctx.lineTo(p2.x + 8, p2.y + 8);
        ctx.moveTo(p2.x + 8, p2.y - 8);
        ctx.lineTo(p2.x - 8, p2.y + 8);
        ctx.strokeStyle = '#27ae60';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    });
  }

  function drawSelected() {
    if (selectedPoint) {
      ctx.beginPath();
      ctx.arc(selectedPoint.x, selectedPoint.y, 8, 0, Math.PI * 2);
      ctx.fillStyle = '#ff6b6b';
      ctx.fill();
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 2;
      ctx.stroke();
    }
    if (selectedCondition) {
      const p1 = points.find((p) => p.id === selectedCondition.p1);
      const p2 = points.find((p) => p.id === selectedCondition.p2);
      if (p1 && p2) {
        ctx.beginPath();
        ctx.moveTo(p1.x, p1.y);
        ctx.lineTo(p2.x, p2.y);
        ctx.strokeStyle = '#ff6b6b';
        ctx.lineWidth = 3;
        ctx.stroke();
      }
    }
  }

  // ---------- Interaction ----------
  canvas.addEventListener('mousedown', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (currentTool === 'point') {
      const existing = points.find((p) => Math.hypot(p.x - x, p.y - y) < 8);
      if (existing) {
        selectedPoint = existing;
      } else {
        const newPoint = { id: Date.now() + Math.random(), x, y, selected: true };
        points.push(newPoint);
        selectedPoint = newPoint;
        state.points.push(newPoint);
      }
    } else if (currentTool === 'segment') {
      const existing = points.find((p) => Math.hypot(p.x - x, p.y - y) < 8);
      if (existing) {
        selectedPoint = existing;
      } else {
        const newPoint = { id: Date.now() + Math.random(), x, y, selected: true };
        points.push(newPoint);
        state.points.push(newPoint);
        selectedPoint = newPoint;
      }
    } else if (currentTool === 'condition') {
      // Try to select a condition
      const cond = state.conditions.find(
        (c) => (c.p1 && Math.hypot(points.find((p) => p.id === c.p1).x - x, points.find((p) => p.id === c.p1).y - y) < 10) ||
               (c.p2 && Math.hypot(points.find((p) => p.id === c.p2).x - x, points.find((p) => p.id === c.p2).y - y) < 10)
      );
      if (cond) {
        selectedCondition = cond;
      } else {
        // Create new condition
        const newCond = { id: Date.now() + Math.random(), type: 'angle', value: 90, p1: null, p2: null };
        state.conditions.push(newCond);
        selectedCondition = newCond;
      }
    } else if (currentTool === 'triangle') {
      const existing = points.find((p) => Math.hypot(p.x - x, p.y - y) < 8);
      if (existing) {
        selectedPoint = existing;
      } else {
        const newPoint = { id: Date.now() + Math.random(), x, y, selected: true };
        points.push(newPoint);
        state.points.push(newPoint);
        selectedPoint = newPoint;
      }
    }
    redraw();
  });

  canvas.addEventListener('mousemove', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    if (currentTool === 'point' || currentTool === 'segment' || currentTool === 'triangle') {
      if (selectedPoint) {
        selectedPoint.x = x;
        selectedPoint.y = y;
        redraw();
      }
    }
  });

  canvas.addEventListener('mouseup', () => {
    selectedPoint = null;
  });

  // ---------- Tools ----------
  function setTool(tool) {
    currentTool = tool;
    toolSelect.value = tool;
    redraw();
  }

  // ---------- Conditions ----------
  function addCondition(type, value, p1Id, p2Id) {
    const cond = { id: Date.now() + Math.random(), type, value, p1: p1Id, p2: p2Id };
    state.conditions.push(cond);
    selectedCondition = cond;
    redraw();
  }

  conditionBtn.addEventListener('click', () => {
    const type = conditionInput.value;
    const value = parseFloat(conditionInput.value2) || 90;
    if (type && value > 0) {
      addCondition(type, value, selectedPoint ? selectedPoint.id : null, null);
    }
    conditionInput.value = '';
    conditionInput.value2 = '';
  });

  // ---------- Proof Generation ----------
  function generateProof() {
    const pts = state.points;
    const cons = state.conditions;

    const steps = [];
    let stepId = 1;

    // 1. Mark all points as labeled
    pts.forEach((p) => {
      steps.push({
        id: stepId++,
        label: 'Point labeled',
        description: `Point ${p.id} is labeled on the plane.`,
        premises: [],
        conclusion: `Point ${p.id} is a labeled point.`,
      });
    });

    // 2. Mark segments
    cons.forEach((c) => {
      if (c.type === 'equal' || c.type === 'parallel' || c.type === 'right' || c.type === 'congruent') {
        const p1 = pts.find((p) => p.id === c.p1);
        const p2 = pts.find((p) => p.id === c.p2);
        if (p1 && p2) {
          steps.push({
            id: stepId++,
            label: `Segment ${p1.id}${p2.id}`,
            description: `Segment ${p1.id}${p2.id} has the property: ${c.type}.`,
            premises: [],
            conclusion: `Segment ${p1.id}${p2.id} is ${c.type}.`,
          });
        }
      }
    });

    // 3. Angle conditions
    cons.forEach((c) => {
      if (c.type === 'angle') {
        const p1 = pts.find((p) => p.id === c.p1);
        const p2 = pts.find((p) => p.id === c.p2);
        if (p1 && p2) {
          steps.push({
            id: stepId++,
            label: `Angle ${p1.id} = ${c.value}°`,
            description: `Angle at ${p1.id} is ${c.value}°.`,
            premises: [],
            conclusion: `∠${p1.id} = ${c.value}°.`,
          });
        }
      }
    });

    // 4. Triangle congruence (SSS, SAS, ASA, AAS, HL)
    const triCons = cons.filter((c) => c.type === 'congruent');
    triCons.forEach((c) => {
      const p1 = pts.find((p) => p.id === c.p1);
      const p2 = pts.find((p) => p.id === c.p2);
      if (p1 && p2) {
        steps.push({
          id: stepId++,
          label: `△${p1.id} ≅ △${p2.id}`,
          description: `Triangles ${p1.id} and ${p2.id} are congruent by ${getCongruenceRule(c)}`,
          premises: [],
          conclusion: `△${p1.id} ≅ △${p2.id}`,
        });
      }
    });

    // 5. Angle sum
    const angles = cons.filter((c) => c.type === 'angle');
    angles.forEach((c) => {
      const p1 = pts.find((p) => p.id === c.p1);
      if (p1) {
        steps.push({
          id: stepId++,
          label: `Sum of angles around ${p1.id}`,
          description: `Angles around point ${p1.id} sum to 360°.`,
          premises: [],
          conclusion: `Sum of angles around ${p1.id} = 360°.`,
        });
      }
    });

    proofSteps = steps;
    currentStep = 0;
    renderProof();
  }

  function getCongruenceRule(cond) {
    // Simplified heuristic
    return 'SSS';
  }

  // ---------- Proof Rendering ----------
  function renderProof() {
    proofTree.innerHTML = '';
    stepList.innerHTML = '';

    if (!proofSteps.length) {
      proofView.innerHTML = '<p class="empty">No proof yet. Draw a figure and add conditions.</p>';
      return;
    }

    const tree = document.createElement('div');
    tree.className = 'proof-tree';
    proofSteps.forEach((step, i) => {
      const el = document.createElement('div');
      el.className = 'proof-step';
      el.dataset.index = i;
      el.innerHTML = `
        <div class="step-num">${step.id}</div>
        <div class="step-label">${step.label}</div>
        <div class="step-desc">${step.description}</div>
      `;
      tree.appendChild(el);
    });
    proofTree.appendChild(tree);

    // Step list
    const list = document.createElement('ul');
    proofSteps.forEach((step, i) => {
      const li = document.createElement('li');
      li.innerHTML = `<span class="step-num">${step.id}</span> ${step.label}`;
      li.addEventListener('click', () => showStep(i));
      list.appendChild(li);
    });
    stepList.appendChild(list);

    showStep(0);
  }

  function showStep(index) {
    currentStep = index;
    if (index >= proofSteps.length) return;
    const step = proofSteps[index];
    proofView.innerHTML = `
      <div class="step-header">
        <span class="step-num">${step.id}</span>
        <span class="step-label">${step.label}</span>
      </div>
      <div class="step-desc">${step.description}</div>
      <div class="step-conclusion">${step.conclusion}</div>
    `;
  }

  // ---------- Verify ----------
  verifyBtn.addEventListener('click', () => {
    const allSteps = proofSteps.length;
    const doneSteps = proofSteps.filter((s) => s.conclusion).length;
    if (allSteps === 0) {
      alert('Add some conditions first!');
      return;
    }
    if (doneSteps === allSteps) {
      alert('Proof complete! All steps are filled.');
    } else {
      alert(`Proof incomplete. ${allSteps - doneSteps} steps remain.`);
    }
  });

  // ---------- Clear / Undo / Redo ----------
  clearBtn.addEventListener('click', () => {
    if (confirm('Clear everything?')) {
      state.points = [];
      state.conditions = [];
      state.figures = [];
      points = [];
      selectedPoint = null;
      selectedCondition = null;
      proofSteps = [];
      currentStep = 0;
      historyIndex = -1;
      redoStack = [];
      redraw();
      renderProof();
    }
  });

  undoBtn.addEventListener('click', () => {
    if (historyIndex > 0) {
      historyIndex--;
      redoStack.push(JSON.parse(JSON.stringify(state)));
      redraw();
    }
  });

  redoBtn.addEventListener('click', () => {
    if (redoStack.length > 0) {
      historyIndex++;
      const s = redoStack.pop();
      Object.assign(state, s);
      redraw();
    }
  });

  // ---------- Init ----------
  resizeCanvas();
  setTool('point');
  renderProof();
})();
```

Creating a full terrain destruction shooting game with Perlin noise terrain, bullet impact deformation, and fluid simulation using WebGL is a substantial project. Below is a **complete, runnable codebase** using **Three.js** (WebGL wrapper) that demonstrates:

1. **Perlin noise terrain generation** with heightmap.
2. **Bullet impact** creating realistic depressions (using signed distance field + softening).
3. **Water containers** that break on impact and release **fluid particles** (simple SPH-style simulation).
4. **Player and enemy movement affected by water depth**.
5. **Real-time rendering** with lighting, shadows, and post-processing.

---

## ✅ Features Implemented

- Perlin noise terrain with multiple octaves.
- Bullet physics with damping and penetration.
- Terrain deformation via signed distance field + softening kernel.
- Water containers (cylinders) with breakable hulls.
- Fluid particles simulated via SPH (Smoothed Particle Hydrodynamics) with density, pressure, and viscosity.
- Water affects player/enemy speed (slows in deep water).
- Post-processing bloom + depth of field.

