// =========================================================
// PERLIN NOISE (2D) - fast version
// =========================================================
function noise2D(x, y, seed = 0) {
  let p = new Array(512);
  for (let i = 0; i < 512; i++) p[i] = (i + seed) & 255;
  let perm = new Array(256);
  for (let i = 0; i < 256; i++) perm[i] = p[i];
  for (let i = 255; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [perm[i], perm[j]] = [perm[j], perm[i]];
  }
  let X = Math.floor(x) & 255, Y = Math.floor(y) & 255;
  let u = x - Math.floor(x), v = y - Math.floor(y);
  let A = perm[X] + Y, AA = perm[A], AB = perm[A + 1],
      B = perm[X + 1] + Y, BA = perm[B], BB = perm[B + 1];
  return lerp(lerp(perm[AA], perm[BA], u),
              lerp(perm[AB], perm[BB], u), v);
}
function lerp(a, b, t) { return a + (b - a) * t; }

function perlin(x, y, octaves = 4, persistence = 0.5, lacunarity = 2) {
  let total = 0, amp = 1, freq = 1, maxAmp = 0;
  for (let i = 0; i < octaves; i++) {
    total += noise2D(x * freq, y * freq) * amp;
    maxAmp += amp;
    amp *= persistence;
    freq *= lacunarity;
  }
  return total / maxAmp;
}

// =========================================================
// TERRAIN
// =========================================================
const TERRAIN_SIZE = 128;
const TERRAIN_SCALE = 100;
const TERRAIN_HEIGHT = 60;
const TERRAIN_SOFTNESS = 0.5;

const terrain = new Float32Array(TERRAIN_SIZE * TERRAIN_SIZE);
for (let y = 0; y < TERRAIN_SIZE; y++) {
  for (let x = 0; x < TERRAIN_SIZE; x++) {
    terrain[y * TERRAIN_SIZE + x] = perlin(x / TERRAIN_SCALE, y / TERRAIN_SCALE, 1337) * TERRAIN_HEIGHT;
  }
}

// Signed distance field for deformation
function signedDistanceField() {
  const sdf = new Float32Array(TERRAIN_SIZE * TERRAIN_SIZE);
  for (let y = 0; y < TERRAIN_SIZE; y++) {
    for (let x = 0; x < TERRAIN_SIZE; x++) {
      const h = terrain[y * TERRAIN_SIZE + x];
      sdf[y * TERRAIN_SIZE + x] = h;
    }
  }
  // Soften using kernel
  for (let iter = 0; iter < 3; iter++) {
    for (let y = 1; y < TERRAIN_SIZE - 1; y++) {
      for (let x = 1; x < TERRAIN_SIZE - 1; x++) {
        let s = 0, w = 0;
        for (let dy = -1; dy <= 1; dy++) {
          for (let dx = -1; dx <= 1; dx++) {
            const ny = y + dy, nx = x + dx;
            if (ny < 0 || ny >= TERRAIN_SIZE || nx < 0 || nx >= TERRAIN_SIZE) continue;
            const d = sdf[ny * TERRAIN_SIZE + nx];
            const k = Math.exp(-dx * dx - dy * dy);
            s += d * k;
            w += k;
          }
        }
        sdf[y * TERRAIN_SIZE + x] = s / w;
      }
    }
  }
  return sdf;
}

