// Heightmap vertex shader (signed distance field)
const vertexShader = `
attribute float height;
varying float vHeight;
void main() {
  vHeight = height;
  vec4 pos = modelMatrix * vec4(position, 1.0);
  pos.y = height;
  gl_Position = projectionMatrix * viewMatrix * pos;
}
`;

const fragmentShader = `
varying float vHeight;
void main() {
  vec3 worldPos = (inverseModelMatrix * vec4(position, 1.0)).xyz;
  float h = height;
  float d = 0.0;
  vec2 p = (worldPos.xz + 0.5) / 100.0;
  // signed distance field
  float s = texture2D(sdfTexture, p).x;
  d = s;
  // erosion
  if (h > 0.0) {
    d = max(d, h - 0.1);
  }
  gl_FragColor = vec4(vec3(0.5) + 0.5 * (d / 60.0), 1.0);
}
`;

const sdfTexture = new THREE.DataTexture(new Float32Array(sdf.buffer), TERRAIN_SIZE, TERRAIN_SIZE, THREE.RGBAFormat);
