  const speed = 6;
  if (keys['KeyW']) player.position.y += speed;
  if (keys['KeyS']) player.position.y -= speed;
  if (keys['KeyD']) player.position.x += speed;
  if (keys['KeyA']) player.position.x -= speed;

  // Enemy movement
  const enemySpeed = 2;
  if (player.position.x > enemy.position.x) enemy.position.x += enemySpeed;
  else enemy.position.x -= enemySpeed;

  // Water container break detection
  const playerPos = new THREE.Vector3(player.position.x, player.position.y, player.position.z);
  const enemyPos = new THREE.Vector3(enemy.position.x, enemy.position.y, enemy.position.z);
  containers.forEach((c) => {
    const dx = playerPos.x - c.mesh.position.x;
    const dz = playerPos.z - c.mesh.position.z;
    const d = Math.sqrt(dx * dx + dz * dz);
    if (d < containerRadius + 0.5 && !c.broken) {
      c.broken = true;
      c.mesh.material.opacity = 0.2;
      c.mesh.material.color.setHex(0x888888);
      spawnParticles(c.mesh.position.x, c.mesh.position.y, c.mesh.position.z, 60);
    }
  });

  // Bullet update
  for (let i = bullets.length - 1; i >= 0; i--) {
    const b = bullets[i];
    b.position.addScaledVector(b.userData.vel, b.userData.life);
    b.userData.vel.x *= b.userData.damping;
    b.userData.vel.y *= b.userData.damping;
    b.userData.vel.z *= b.userData.damping;
    b.userData.life -= 0.016;
    if (b.userData.life <= 0) {
      scene.remove(b);
      bullets.splice(i, 1);
    }
  }

  // Bullet terrain impact
  bullets.forEach((b) => {
    const px = b.position.x, pz = b.position.z;
    const hx = Math.floor(px), hy = Math.floor(pz);
    if (hx < 0 || hy < 0 || hx >= TERRAIN_SIZE - 1 || hy >= TERRAIN_SIZE - 1) return;
    const h = terrain[hy * TERRAIN_SIZE + hx];
    const d = b.position.y - h;
    if (d < 0.5) {
      // Soften impact
      for (let x = -2; x <= 2; x++) {
        for (let z = -2; z <= 2; z++) {
          const nx = Math.max(0, Math.min(TERRAIN_SIZE - 1, hx + x));
          const nz = Math.max(0, Math.min(TERRAIN_SIZE - 1, hy + z));
          const weight = Math.exp(-(x * x + z * z));
          terrain[nz * TERRAIN_SIZE + nx] = Math.max(terrain[nz * TERRAIN_SIZE + nx], h - 0.3);
        }
      }
      // Break containers
      containers.forEach((c) => {
        const dx = b.position.x - c.mesh.position.x;
        const dz = b.position.z - c.mesh.position.z;
        if (Math.sqrt(dx * dx + dz * dz) < containerRadius) {
          c.broken = true;
          c.mesh.material.opacity = 0.2;
          c.mesh.material.color.setHex(0x888888);
          spawnParticles(c.mesh.position.x, c.mesh.position.y, c.mesh.position.z, 60);
        }
      });
      scene.remove(b);
      bullets.splice(bullets.indexOf(b), 1);
    }
  });

  // Fluid simulation
  for (let i = 0; i < fluidParticles.length; i++) {
    const p = fluidParticles[i];
    if (!p.alive) continue;
    // Density
    let rho = 0;
    for (let j = 0; j < fluidParticles.length; j++) {
      const q = fluidParticles[j];
      if (q === p) continue;
      const d = p.pos.distanceTo(q.pos);
      if (d < h) {
        rho += m / (h * h * h) * (1 - d / h) * (1 - d / h) * (1 - d / h);
      }
    }
    p.density = rho;
    p.pressure = Math.max(0, k * (Math.pow(p.density, 0.6) - 1));

    // Pressure force
    const force = new THREE.Vector3();
    for (let j = 0; j < fluidParticles.length; j++) {
      const q = fluidParticles[j];
      if (q === p) continue;
      const d = p.pos.distanceTo(q.pos);
      if (d < h) {
        const r = d / h;
        const w = (1 - 3 * r * r + 3 * r * r * r) * m;
        const dir = p.pos.clone().sub(q.pos).normalize();
        force.add(dir.multiplyScalar(w * (p.pressure - q.pressure)));
      }
    }
    p.vel.addScaledVector(force, 0.016);

    // Viscosity
    for (let j = 0; j < fluidParticles.length; j++) {
      const q = fluidParticles[j];
      if (q === p) continue;
      const d = p.pos.distanceTo(q.pos);
      if (d < h) {
        const r = d / h;
        const w = (1 - 3 * r * r + 3 * r * r * r) * m;
        p.vel.addScaledVector(q.vel.sub(p.vel), c * w);
      }
    }

    // Gravity
    p.vel.addScaledVector(gravity, 0.016);

    // Boundary (floor)
    if (p.pos.y < 0.1) {
      p.vel.y = Math.abs(p.vel.y);
      p.pos.y = 0.1;
    }

    // Update position
    p.pos.addScaledVector(p.vel, 0.016);

    // Water affects player/enemy speed
    const waterDepth = Math.max(0, p.pos.y - 0.1);
    if (waterDepth > 0.5) {
      player.position.y -= 0.01;
      enemy.position.y -= 0.01;
    }
  }

  // Render
  composer.render();
  requestAnimationFrame(update);
}

// =========================================================
// SPAWN PARTICLES
// =========================================================
function spawnParticles(x, y, z, count) {
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = 4 + Math.random() * 8;
    fluidParticles.push({
      pos: new THREE.Vector3(x, y + 0.5, z),
      vel: new THREE.Vector3(Math.cos(angle) * speed, 10, Math.sin(angle) * speed),
      radius: particleRadius,
      mass: m,
      density: 0,
      pressure: 0,
      alive: true,
    });
  }
}

// =========================================================
// RESIZE
// =========================================================
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
  composer.setSize(window.innerWidth, window.innerHeight);
});

// =========================================================
// START
// =========================================================
update();
</script>
</body>
</html>
```

