## 📁 server/app.js

```javascript
const express = require('express');
const cors = require('cors');
const bodyParser = require('body-parser');
const path = require('path');
const session = require('express-session');
const app = express();

const PORT = process.env.PORT || 3000;

// Middleware
app.use(cors());
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));
app.use(express.static(path.join(__dirname, '../public')));

// Sessions
app.use(session({
  secret: 'meeting-room-secret-key-2025',
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false, httpOnly: true, maxAge: 1000 * 60 * 60 * 24 }
}));

// Routes
const authRoutes = require('./routes/auth');
const userRoutes = require('./routes/user');
const adminRoutes = require('./routes/admin');

app.use('/api/auth', authRoutes);
app.use('/api/user', userRoutes);
app.use('/api/admin', adminRoutes);

// Serve static admin UI
app.get('/admin', (req, res) => {
  res.sendFile(path.join(__dirname, '../public/admin.html'));
});

// Serve static user UI
app.get('/', (req, res) => {
  res.sendFile(path.join(__dirname, '../public/index.html'));
});

// SSE endpoint for real-time updates
app.get('/api/sse', (req, res) => {
  res.writeHead(200, {
    'Content-Type': 'text/event-stream',
    'Cache-Control': 'no-cache',
    'Connection': 'keep-alive'
  });
  const stream = res;
  stream.write('event: init\ndata: {"message":"Connected to real-time stream"}\n\n');

  const broadcast = (data) => {
    stream.write(`event: update\ndata: ${JSON.stringify(data)}\n\n`);
  };

  const cleanup = () => {
    stream.destroy();
  };

  req.on('close', cleanup);
  req.on('error', cleanup);

  // Simulate periodic broadcast of room statuses
  const interval = setInterval(() => {
    broadcast({ type: 'status', payload: { rooms: getAllRoomsStatus() } });
  }, 5000);

  // Cleanup on disconnect
  setTimeout(() => clearInterval(interval), 60000);
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
