## 📁 server/controllers/user.js

```javascript
const Reservation = require('../models/Reservation');
const Room = require('../models/Room');

const userController = {
  getRooms: async (req, res) => {
    const rooms = await Room.getAll();
    res.json({ rooms });
  },
  getSlots: async (req, res) => {
    const { roomId, date } = req.query;
    if (!roomId || !date) return res.status(400).json({ error: 'roomId and date required' });
    const slots = await Room.getAvailableSlots(roomId, date);
    res.json({ slots });
  },
  reserve: async (req, res) => {
    const { roomId, date, startTime, endTime, reason } = req.body;
    if (!req.session.userId) return res.status(401).json({ error: 'Not logged in' });

    const existing = await Reservation.getAll();
    const occupied = existing.filter(r => r.room_id === parseInt(roomId) && r.date === date);
    for (const r of occupied) {
      if ((startTime >= r.start_time && startTime < r.end_time) ||
          (endTime > r.start_time && endTime <= r.end_time) ||
          (startTime < r.start_time && endTime > r.end_time)) {
        return res.status(409).json({ error: 'Room is already reserved during this time' });
      }
    }

    await Reservation.create(req.session.userId, roomId, date, startTime, endTime, reason);
    res.json({ success: true });
  },
  myReservations: async (req, res) => {
    if (!req.session.userId) return res.status(401).json({ error: 'Not logged in' });
    const reservations = await Reservation.getAll();
    const mine = reservations.filter(r => r.user_id === req.session.userId);
    res.json({ reservations: mine });
  }
};

module.exports = userController;
