## 📁 public/script.js

```javascript
// ---------- Utilities ----------
const $ = (sel) => document.querySelector(sel);
const $$ = (sel) => document.querySelectorAll(sel);

const showView = (id) => {
  $$('.view').forEach(v => v.classList.add('hidden'));
  $(`#view-${id}`).classList.remove('hidden');
  const nav = id === 'login' ? 'navLogin' : id === 'home' ? 'navHome' : 'navLogout';
  $$('.topnav a').forEach(a => a.style.display = 'none');
  if (nav) $(`#${nav}`).style.display = 'inline-block';
};

// ---------- Login ----------
$('#login-form').addEventListener('submit', async (e) => {
  e.preventDefault();
  const u = $('#l-username').value.trim();
  const p = $('#l-password').value.trim();
  const res = await fetch('/api/auth/login', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ username: u, password: p })
  });
  const data = await res.json();
  if (data.success) {
    window.location.href = '#home';
  } else {
    alert('Login failed: ' + data.error);
  }
});

$('#navLogin').addEventListener('click', (e) => {
  e.preventDefault();
  window.location.href = '#login';
});
$('#navLogout').addEventListener('click', (e) => {
  e.preventDefault();
  fetch('/api/auth/logout').then(() => window.location.href = '#login');
});

// ---------- Home ----------
const slots = ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'];

async function renderHome() {
  const rooms = await fetch('/api/user/rooms').then(r => r.json());
  const grid = $('#rooms-grid');
  grid.innerHTML = '';
  rooms.rooms.forEach(r => {
    const card = document.createElement('div');
    card.className = 'room-card';
    card.innerHTML = `
      <h4>${r.name}</h4>
      <p>${r.capacity} seats · ${r.description || 'Available'}</p>
      <button class="btn btn-ghost reserve-btn" data-id="${r.id}">Reserve</button>
    `;
    grid.appendChild(card);
  });

  // Populate quick reserve
  const qRoom = $('#q-room');
  rooms.rooms.forEach(r => {
    const opt = document.createElement('option');
    opt.value = r.id; opt.textContent = r.name;
    qRoom.appendChild(opt);
  });
  slots.forEach(s => {
    ['#q-start', '#q-end'].forEach(sel => {
      const el = $(sel);
      const opt = document.createElement('option');
      opt.value = s; opt.textContent = s;
      el.appendChild(opt);
    });
  });

  $('#quick-reserve').addEventListener('submit', async (e) => {
    e.preventDefault();
    const data = {
      roomId: $('#q-room').value,
      date: $('#q-date').value,
      startTime: $('#q-start').value,
      endTime: $('#q-end').value,
      reason: $('#q-reason').value || 'No reason'
    };
    const res = await fetch('/api/user/reserve', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    const ok = await res.json();
    if (ok.success) {
      alert('Reservation created successfully');
      window.location.href = '#my';
    } else {
      alert(ok.error || 'Failed to reserve');
    }
  });

  // Reserve buttons
  grid.addEventListener('click', async (e) => {
    const btn = e.target.closest('.reserve-btn');
    if (!btn) return;
    const roomId = btn.dataset.id;
    const date = prompt('Select a date (YYYY-MM-DD):', new Date().toISOString().slice(0,10));
    if (!date) return;
    const res = await fetch('/api/user/slots', {
      method: 'GET', params: { roomId, date }
    }).then(r => r.json());
    if (res.slots.length === 0) {
      alert('All slots are taken. Try another time.');
      return;
    }
    const start = prompt('Start time:', slots[0]);
    const end = prompt('End time:', slots[1]);
    if (!start || !end) return;
    const data = { roomId, date, startTime: start, endTime: end, reason: 'No reason' };
    const r = await fetch('/api/user/reserve', {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(data)
    });
    const ok = await r.json();
    if (ok.success) {
      alert('Reservation created successfully');
      window.location.href = '#my';
    } else {
      alert(ok.error || 'Failed to reserve');
    }
  });
}

// ---------- My Reservations ----------
async function renderMy() {
  const list = $('#my-reservations');
  list.innerHTML = '';
  const res = await fetch('/api/user/my').then(r => r.json());
  if (res.reservations.length === 0) {
    list.innerHTML = '<p class="muted">No reservations yet.</p>';
    return;
  }
  res.reservations.forEach(r => {
    const el = document.createElement('div');
    el.className = 'reservation';
    el.innerHTML = `
      <div>
        <h4>${r.reason || 'No reason'}</h4>
        <p>${r.room_name} · ${r.date} · ${r.start_time}–${r.end_time}</p>
      </div>
      <span class="status-pill ${r.status}">${r.status}</span>
    `;
    list.appendChild(el);
  });
}

// ---------- Navigation ----------
$('#navHome').addEventListener('click', (e) => {
  e.preventDefault();
  window.location.href = '#home';
});
$('#navMy').addEventListener('click', (e) => {
  e.preventDefault();
  window.location.href = '#my';
});

// ---------- Init ----------
document.addEventListener('DOMContentLoaded', () => {
  const view = window.location.hash || '#login';
  showView(view.replace('#', ''));
  if (view === '#home') renderHome();
  if (view === '#my') renderMy();
});
