```javascript
const slots = ['09:00', '10:00', '11:00', '14:00', '15:00', '16:00'];

async function renderAdmin() {
  const list = $('#admin-list');
  list.innerHTML = '';
  const res = await fetch('/api/admin/all').then(r => r.json());
  if (res.reservations.length === 0) {
    list.innerHTML = '<p class="muted">No reservations yet.</p>';
    return;
  }
  res.reservations.forEach(r => {
    const row = document.createElement('div');
    row.className = 'admin-row';
    row.innerHTML = `
      <div><h4>${r.reason || 'No reason'}</h4><p>${r.room_name} · ${r.date}</p></div>
      <div><p>${r.start_time}–${r.end_time}</p></div>
      <div><p>by ${r.username}</p></div>
      <div><span class="status-pill ${r.status}">${r.status}</span></div>
      <div class="admin-actions">
        <button class="btn btn-ghost approve-btn" data-id="${r.id}" ${r.status === 'approved' ? 'disabled' : ''}>Approve</button>
        <button class="btn btn-ghost cancel-btn" data-id="${r.id}" ${r.status === 'cancelled' ? 'disabled' : ''}>Cancel</button>
        <button class="btn btn-ghost edit-btn" data-id="${r.id}" ${r.status === 'pending' ? 'disabled' : ''}>Edit</button>
      </div>
    `;
    list.appendChild(row);
  });

  // Actions
  list.addEventListener('click', async (e) => {
    const btn = e.target.closest('.approve-btn');
    if (btn) { await approve(btn.dataset.id); return; }
    const cancel = e.target.closest('.cancel-btn');
    if (cancel) { await cancelReservation(cancel.dataset.id); return; }
    const edit = e.target.closest('.edit-btn');
    if (edit) { await editReservation(edit.dataset.id); return; }
  });

  $('#export-btn').addEventListener('click', async () => {
    const res = await fetch('/api/admin/export').then(r => r.text());
    const blob = new Blob([res], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'reservations.csv';
    a.click();
    URL.revokeObjectURL(url);
  });
}

async function approve(id) {
  const res = await fetch('/api/admin/approve', { method: 'POST', body: JSON.stringify({ id }) });
  const ok = await res.json();
  if (ok.success) {
    renderAdmin();
    alert('Reservation approved');
  }
}

async function cancelReservation(id) {
  const res = await fetch('/api/admin/cancel', { method: 'POST', body: JSON.stringify({ id }) });
  const ok = await res.json();
  if (ok.success) {
    renderAdmin();
    alert('Reservation cancelled');
  }
}

async function editReservation(id) {
  const res = await fetch('/api/admin/edit', { method: 'POST', body: JSON.stringify({ id, reason: 'Updated' }) });
  const ok = await res.json();
  if (ok.success) {
    renderAdmin();
    alert('Reservation updated');
  }
}

// Filters
$('#f-search').addEventListener('input', (e) => {
  const q = e.target.value.toLowerCase();
  const rows = $$('.admin-row');
  rows.forEach(r => {
    const text = r.textContent.toLowerCase();
    r.style.display = text.includes(q) ? '' : 'none';
  });
});

$('#f-room').addEventListener('change', (e) => {
  const val = e.target.value;
  const rows = $$('.admin-row');
  rows.forEach(r => {
    r.style.display = val === '' || r.querySelector('h4').textContent.toLowerCase().includes(val) ? '' : 'none';
  });
});

$('#f-status').addEventListener('change', (e) => {
  const val = e.target.value;
  const rows = $$('.admin-row');
  rows.forEach(r => {
    r.style.display = val === '' || r.querySelector('.status-pill').textContent === val ? '' : 'none';
  });
});

// ---------- Navigation ----------
$('#navHomeA').addEventListener('click', (e) => {
  e.preventDefault();
  window.location.href = '#home';
});
$('#navLogoutA').addEventListener('click', (e) => {
  e.preventDefault();
  fetch('/api/auth/logout').then(() => window.location.href = '#login');
});

// ---------- Init ----------
document.addEventListener('DOMContentLoaded', () => {
  showView('admin');
  renderAdmin();
});
