const db = require('./db');

const seed = async () => {
  // Seed rooms
  const rooms = [
    { name: 'Boardroom A', capacity: 10, description: 'Main conference room with projector' },
    { name: 'Boardroom B', capacity: 8, description: 'Small private meeting room' },
    { name: 'Conference Hall', capacity: 30, description: 'Large hall for presentations' },
    { name: 'Team Room 1', capacity: 6, description: 'Collaboration space' },
    { name: 'Team Room 2', capacity: 6, description: 'Collaboration space' }
  ];
  for (const r of rooms) {
    db.run('INSERT OR IGNORE INTO rooms (name, capacity, description) VALUES (?, ?, ?)', r.name, r.capacity, r.description);
  }

  // Seed admin user
  db.get('SELECT * FROM users WHERE username = ?', 'admin', (err, row) => {
    if (!row) {
      db.run('INSERT INTO users (username, password, role) VALUES (?, ?, ?)', 'admin', 'admin123', 'admin');
    }
  });

  console.log('Database seeded');
};

seed();
