## 🧩 Core Features

### 1. **PDF Format Auto-Check**

Uses `pdf-lib` to parse PDF metadata and layout. Checks:

- Page count (min 4, max 12)
- Font family (Times New Roman / Arial / Helvetica)
- Margins (≥ 1 inch on all sides)
- Line spacing (≥ 1.5)
- Title size (≥ 24pt)

```typescript
// server/services/pdfService.ts
import { pdf } from 'pdf-lib';

export async function analyzePDF(buffer: Buffer): Promise<PDFAnalysis> {
  const pdfDoc = await pdf.load(buffer);
  const pages = pdfDoc.getPages();
  const firstPage = pages[0];

  // Page count
  const pageCount = pages.length;

  // Font detection (simple heuristic: extract text and sample glyphs)
  const text = firstPage.getTextContent().items.map(i => i.str).join(' ');
  const fonts = detectFonts(text);

  // Margin estimation via bounding box of first page text
  const margin = estimateMargins(firstPage);

  // Title detection: first 3 lines of text
  const titleLines = firstPage.getTextContent().items
    .slice(0, 12)
    .map(i => i.str)
    .filter(Boolean);

  const title = titleLines.join(' ').trim();
  const titleSize = estimateTitleSize(firstPage, titleLines);

  return {
    pageCount,
    fonts,
    margin,
    title,
    titleSize,
    layout: classifyLayout(firstPage, text),
  };
}

function detectFonts(text: string): string[] {
  const patterns = [
    /Times\s+New\s+Roman/i,
    /Arial/i,
    /Helvetica/i,
    /Georgia/i,
    /Courier/i,
  ];
  return patterns.map(p => text.match(p)?.[0] || '').filter(Boolean);
}

function estimateMargins(page: any): Margins {
  const bbox = page.getBBox();
  return {
    top: bbox.top,
    bottom: bbox.bottom,
    left: bbox.left,
    right: bbox.right,
  };
}

function estimateTitleSize(page: any, lines: string[]): number {
  if (lines.length < 2) return 0;
  // heuristic: larger lines = larger title
  const avgLen = lines.reduce((s, l) => s + l.length, 0) / lines.length;
  return Math.max(12, Math.min(48, avgLen * 0.3));
}

function classifyLayout(page: any, text: string): Layout {
  const words = text.split(/\s+/).filter(Boolean);
  const wordCount = words.length;
  const lines = text.split('\n').filter(Boolean);
  const lineCount = lines.length;
  const ratio = wordCount / lineCount;
  if (ratio < 2.5) return 'wide';
  if (ratio > 4.5) return 'narrow';
  return 'balanced';
}
```

