### 2. **Double-Blind Review**

When enabled, strips:

- Author names
- Affiliations
- Emails
- ORCID identifiers
- Contact info blocks

```typescript
// server/services/pdfService.ts (continued)
export async function anonymizePDF(buffer: Buffer): Promise<Buffer> {
  const pdfDoc = await pdf.load(buffer);
  const pages = pdfDoc.getPages();

  for (const page of pages) {
    const content = page.getTextContent();
    const items = content.items;

    // Remove text matching common author patterns
    const authorPatterns = [
      /\b[A-Z][a-z]+\s+[A-Z][a-z]+\b/g,
      /\bAuthor\s+[\w\s]+/g,
      /\bAffiliation\s+[\w\s]+/g,
      /\bEmail:\s+\S+@/g,
      /\bORCID:\s+\S+/g,
      /\bCorresponding\s+author\b/g,
      /\bSubmitted\s+by\b/g,
    ];

    for (const item of items) {
      item.str = authorPatterns
        .map(p => item.str.replace(p, ''))
        .join('');
    }

    // Remove contact blocks (heuristic: text starting with "Author", "Corresponding")
    const cleaned = items
      .map(i => i.str)
      .join(' ')
      .replace(/Author\s*[\w\s,;:\-]+[\.\n]/gi, '')
      .replace(/Corresponding\s+author\s*[\w\s,;:\-]+[\.\n]/gi, '');

    const newItems = [];
    const words = cleaned.split(/\s+/);
    for (const w of words) {
      if (w.length > 0) newItems.push({ str: w });
    }
    page.setTextContent({ items: newItems });
  }

  return await pdfDoc.save();
}
```

