### 3. **Plagiarism Detection (Simulated Turnitin)**

Uses a **simulated similarity index** based on:

- TF-IDF vectorization of paper text
- Cosine similarity against a small corpus
- Returns similarity score (0–100%)

```typescript
// server/services/plagiarismService.ts
import { cosineSimilarity } from './tfidf';

const corpus = [
  { id: 'c1', text: 'Deep learning has revolutionized computer vision.' },
  { id: 'c2', text: 'Neural networks are powerful tools for image recognition.' },
  { id: 'c3', text: 'Transformers have become the backbone of modern NLP.' },
  { id: 'c4', text: 'Reinforcement learning enables agents to learn from rewards.' },
  { id: 'c5', text: 'Graph neural networks model relationships between entities.' },
  { id: 'c6', text: 'Attention mechanisms improve sequence modeling.' },
];

export async function checkPlagiarism(text: string): Promise<PlagiarismReport> {
  const vectors = await tfidf(text);
  let maxScore = 0;
  let bestMatch = null;

  for (const doc of corpus) {
    const v = await tfidf(doc.text);
    const s = cosineSimilarity(v, vectors);
    if (s > maxScore) {
      maxScore = s;
      bestMatch = doc;
    }
  }

  return {
    similarity: Math.round(maxScore * 100),
    bestMatchId: bestMatch?.id,
    bestMatchText: bestMatch?.text,
    flags: maxScore > 0.55 ? ['potential_duplicate'] : [],
  };
}
```

