## 2. 📜 Backend: `screenshot.js`

```javascript
// screenshot.js
const { chromium } = require('playwright');

const PORT = 3001;
const BASE_URL = 'http://localhost:3001';

const launchBrowser = async () => {
  const browser = await chromium.launch({
    headless: true,
    args: [
      '--no-sandbox',
      '--disable-setuid-sandbox',
      '--disable-dev-shm-usage',
      '--disable-gpu',
      '--remote-debugging-port=9222',
    ],
  });
  return browser;
};

const capture = async (url) => {
  const browser = await launchBrowser();
  const context = await browser.newContext({
    viewport: { width: 1200, height: 630 },
  });
  const page = await context.newPage();

  try {
    await page.goto(url, { waitUntil: 'networkidle' });
    const dataUrl = await page.screenshot({ type: 'png', quality: 80 });
    return dataUrl;
  } catch (err) {
    console.error('Capture failed:', err);
    throw new Error('Failed to capture screenshot');
  } finally {
    await context.close();
    await browser.close();
  }
};

const server = require('http').createServer(async (req, res) => {
  const url = req.url.slice(1);
  if (!url) {
    res.writeHead(400, { 'Content-Type': 'text/plain' });
    res.end('Missing URL');
    return;
  }

  try {
    const dataUrl = await capture(url);
    res.writeHead(200, {
      'Content-Type': 'image/png',
      'Content-Disposition': `attachment; filename=screenshot-${Date.now()}.png`,
    });
    res.end(dataUrl, 'base64');
  } catch (err) {
    res.writeHead(500, { 'Content-Type': 'text/plain' });
    res.end(err.message);
  }
});

server.listen(PORT, () => {
  console.log(`Screenshot server running at http://localhost:${PORT}`);
});
```

