        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        setTimeout(() => URL.revokeObjectURL(urlStr), 2000);

        urlInput.value = '';
      } catch (err) {
        errorEl.textContent = 'Failed to capture: ' + err.message;
      } finally {
        captureBtn.disabled = false;
        captureBtn.textContent = '📸 Capture & Download';
      }
    });
  </script>
