## 🧩 CRUD: Documents

### `backend/app/crud/document.py`

```python
from sqlalchemy.orm import Session
from app.models import Document, Version
from app.schemas import DocumentCreate, DocumentUpdate, VersionCreate
from typing import List, Optional
import uuid

def create_document(db: Session, obj_in: DocumentCreate, user_id: str) -> Document:
    db_obj = Document(
        id=str(uuid.uuid4()),
        title=obj_in.title,
        slug=obj_in.slug or slugify(obj_in.title),
        markdown=obj_in.markdown,
        project_id=obj_in.project_id,
        author_id=user_id,
    )
    db.add(db_obj)
    db.commit()
    db.refresh(db_obj)
    return db_obj

def get_document(db: Session, id: str) -> Optional[Document]:
    return db.query(Document).filter(Document.id == id).first()

def get_documents_by_project(db: Session, project_id: str, skip: int = 0, limit: int = 100) -> List[Document]:
    return db.query(Document).filter(Document.project_id == project_id).offset(skip).limit(limit).all()

def update_document(db: Session, id: str, obj_in: DocumentUpdate, user_id: str) -> Document:
    db_obj = get_document(db, id)
    if not db_obj:
        raise HTTPException(status_code=404, detail="Document not found")
    for field, value in obj_in.dict(exclude_unset=True).items():
        if field == "markdown":
            db_obj.markdown = value
        elif field == "title":
            db_obj.title = value
            db_obj.slug = slugify(value)
        elif field == "is_draft":
            db_obj.is_draft = value
        elif field == "is_public":
            db_obj.is_public = value
    db_obj.updated_at = datetime.utcnow()
    db_obj.author_id = user_id
    db.commit()
    db.refresh(db_obj)
    return db_obj

def create_version(db: Session, document_id: str, content: str, user_id: str) -> Version:
    db_obj = Version(
        id=str(uuid.uuid4()),
        document_id=document_id,
        content=content,
        author_id=user_id,
        is_head=True,
    )
    db.add(db_obj)
    db.commit()
    db.refresh(db_obj)
    return db_obj

def get_versions(db: Session, document_id: str, skip: int = 0, limit: int = 100) -> List[Version]:
    return db.query(Version).filter(Version.document_id == document_id).order_by(Version.created_at.desc()).offset(skip).limit(limit).all()

def set_head_version(db: Session, document_id: str, version_id: str) -> None:
    db.query(Version).filter(Version.document_id == document_id).update({"is_head": False})
    db.query(Version).filter(Version.id == version_id).update({"is_head": True})
    db.commit()
