## 🧠 Markdown Rendering + API Docs Generation

### `backend/app/services/markdown.py`

```python
import mistune
import re
from typing import Optional
from app.models import Document

def render_markdown(md_text: str) -> str:
    renderer = mistune.Renderer(
        escape=False,
        hard_wrap=False,
        xhtml=True,
    )
    markdown = mistune.Markdown(renderer=renderer, escape_html=False)
    return markdown(md_text)

def extract_api_definitions(md_text: str) -> dict:
    """Simple regex-based API extractor: `### POST /api/users`"""
    apis = {}
    pattern = r"### (GET|POST|PUT|PATCH|DELETE) (?P<method>\b(?:GET|POST|PUT|PATCH|DELETE)\b)\s+(?P<endpoint>/[^#\n]+)"
    for match in re.finditer(pattern, md_text, re.MULTILINE):
        method = match.group("method").upper()
        endpoint = match.group("endpoint").strip()
        apis[endpoint] = apis.get(endpoint, {}) | {method: method}
    return apis
```

---

### `backend/app/services/api_generator.py`

```python
from typing import Dict, List
import re

def generate_swagger_spec(document: Document) -> Dict:
    """Generate OpenAPI-style spec from markdown API definitions."""
    apis = extract_api_definitions(document.markdown)
    spec = {
        "openapi": "3.0.3",
        "info": {
            "title": document.title,
            "description": "API documentation generated from document: " + document.title,
            "version": "1.0.0",
        },
        "servers": [{"url": "https://api.example.com"}],
        "paths": {},
    }
    for endpoint, methods in apis.items():
        if endpoint not in spec["paths"]:
            spec["paths"][endpoint] = {}
        for method in methods:
            spec["paths"][endpoint][method] = {
                "operationId": f"{method}_{endpoint.replace('/', '_')}",
                "responses": {"200": {"description": "Success"}},
            }
    return spec
```

