from fastapi import APIRouter, Depends, HTTPException, Query, UploadFile, File
from sqlalchemy.orm import Session
from app.core.deps import get_db
from app.core.security import get_current_user
from app.schemas import DocumentCreate, DocumentUpdate, DocumentOut, VersionOut
from app.crud import document as crud
from app.services.markdown import render_markdown, extract_api_definitions
from app.services.api_generator import generate_swagger_spec
from app.tasks.render import render_markdown_async

router = APIRouter()

@router.post("/documents", response_model=DocumentOut)
def create_document(
    obj_in: DocumentCreate,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    return crud.create_document(db, obj_in, current_user["id"])

@router.get("/documents/{id}", response_model=DocumentOut)
def read_document(id: str, db: Session = Depends(get_db)):
    doc = crud.get_document(db, id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    return doc

@router.put("/documents/{id}", response_model=DocumentOut)
def update_document(
    id: str,
    obj_in: DocumentUpdate,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    return crud.update_document(db, id, obj_in, current_user["id"])

@router.post("/documents/{id}/versions")
def create_version(
    id: str,
    content: str,
    current_user: dict = Depends(get_current_user),
    db: Session = Depends(get_db),
):
    doc = crud.get_document(db, id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    version = crud.create_version(db, id, content, current_user["id"])
    return version

@router.get("/documents/{id}/versions", response_model=List[VersionOut])
def read_versions(id: str, skip: int = 0, limit: int = 100, db: Session = Depends(get_db)):
    return crud.get_versions(db, id, skip, limit)

@router.get("/documents/{id}/versions/head", response_model=VersionOut)
def read_head_version(id: str, db: Session = Depends(get_db)):
    versions = crud.get_versions(db, id)
    if not versions:
        raise HTTPException(status_code=404, detail="No versions found")
    head = next((v for v in versions if v.is_head), None)
    if not head:
        raise HTTPException(status_code=404, detail="No head version")
    return head

@router.get("/documents/{id}/api-spec", response_model=dict)
def read_api_spec(id: str, db: Session = Depends(get_db)):
    doc = crud.get_document(db, id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    return generate_swagger_spec(doc)

@router.get("/documents/{id}/render", response_model=dict)
def render_document(id: str, db: Session = Depends(get_db)):
    doc = crud.get_document(db, id)
    if not doc:
        raise HTTPException(status_code=404, detail="Document not found")
    html = render_markdown(doc.markdown)
    return {"html": html}
