### ⚙️ JavaScript

```javascript
/* =========================================================
   Video Timeline Bookmarking Tool
   ========================================================= */
(() => {
  'use strict';

  // ---------- DOM ----------
  const $ = (id) => document.getElementById(id);
  const video = $('video');
  const bookmarkList = $('bookmarkList');
  const emptyState = $('emptyState');
  const bookmarkCount = $('bookmarkCount');
  const editor = $('editor');
  const editorTimestamp = $('editorTimestamp');
  const editorNote = $('editorNote');
  const thumbDrop = $('thumbDrop');
  const thumbInput = $('thumbInput');
  const saveBtn = $('saveBookmarkBtn');
  const deleteBtn = $('deleteBookmarkBtn');
  const addBtn = $('addBookmarkBtn');
  const exportBtn = $('exportBtn');
  const importBtn = $('importBtn');
  const clearBtn = $('clearBtn');
  const videoOverlay = $('videoOverlay');
  const playBtn = $('playBtn');
  const playIcon = $('playIcon');

  // ---------- State ----------
  const STORAGE_KEY = 'framemarker.bookmarks.v1';
  const state = {
    bookmarks: [],
    currentId: null,
    nextId: 1,
    editing: false,
  };

  // ---------- Persistence ----------
  function load() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) state.bookmarks = parsed;
      }
    } catch (e) { /* ignore */ }
  }
  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(state.bookmarks));
    } catch (e) { /* ignore */ }
  }

  // ---------- Bookmark model ----------
  function createBookmark() {
    const ts = video.currentTime || 0;
    return {
      id: state.nextId++,
      timestamp: Math.max(0, Math.round(ts * 1000)) / 1000,
      note: '',
      thumbnail: null,
    };
  }

  // ---------- Rendering ----------
  function renderBookmarks() {
    bookmarkList.innerHTML = '';
    if (state.bookmarks.length === 0) {
      emptyState.style.display = '';
      bookmarkCount.textContent = '0';
      return;
    }
    emptyState.style.display = 'none';
    bookmarkCount.textContent = state.bookmarks.length;

    state.bookmarks.forEach((b, idx) => {
      const li = document.createElement('li');
      li.className = 'bookmark-item';
      li.dataset.id = b.id;
      li.setAttribute('role', 'button');
      li.setAttribute('tabindex', '0');
      li.innerHTML = `
        <div class="num">${String(idx + 1).padStart(2, '0')}</div>
        <div class="thumb">
          ${b.thumbnail ? `<img src="${b.thumbnail}" alt="">` : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>'}
        </div>
        <div class="info">
          <div class="title"></div>
          <div class="note"></div>
        </div>
        <button class="remove" title="Delete" aria-label="Delete bookmark">
          <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6"/></svg>
        </button>
      `;
      li.querySelector('.title').textContent = formatTime(b.timestamp);
      li.querySelector('.note').textContent = b.note || 'No note';

      // Active highlight
      if (state.currentId === b.id) {
        li.classList.add('active');
      }

      // Events
      li.addEventListener('click', () => selectBookmark(b.id));
      li.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); selectBookmark(b.id); }
      });
      li.querySelector('.remove').addEventListener('click', (e) => {
        e.stopPropagation();
        deleteBookmark(b.id);
      });

      bookmarkList.appendChild(li);
    });
  }

  function formatTime(ts) {
    const h = Math.floor(ts / 3600);
    const m = Math.floor((ts % 3600) / 60);
    const s = Math.floor(ts % 60);
    const ms = Math.floor((ts - Math.floor(ts)) * 100);
    if (h > 0) return `${h}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${ms}`;
    return `${m}:${String(s).padStart(2,'0')}.${ms}`;
  }

  function selectBookmark(id) {
    state.currentId = id;
    const b = state.bookmarks.find(x => x.id === id);
    if (!b) return;
    editorTimestamp.value = b.timestamp;
    editorNote.value = b.note;
    thumbDrop.querySelector('.thumb-preview').innerHTML = b.thumbnail
      ? `<img src="${b.thumbnail}" alt="">`
      : '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>';
    editorTimestamp.disabled = false;
    editorNote.disabled = false;
    saveBtn.disabled = false;
    deleteBtn.disabled = false;
    renderBookmarks();
    // Scroll to selected
    const item = bookmarkList.querySelector(`[data-id="${id}"]`);
    if (item) item.scrollIntoView({ block: 'nearest' });
    video.currentTime = b.timestamp;
    video.play().catch(() => {});
  }

  function clearSelection() {
    state.currentId = null;
    editorTimestamp.value = '';
    editorNote.value = '';
    thumbDrop.querySelector('.thumb-preview').innerHTML = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="9" cy="9" r="2"/><path d="M21 15l-5-5L5 21"/></svg>';
    editorTimestamp.disabled = true;
    editorNote.disabled = true;
    saveBtn.disabled = true;
    deleteBtn.disabled = true;
    renderBookmarks();
  }

  // ---------- Actions ----------
  function addBookmark() {
    const b = createBookmark();
    state.bookmarks.push(b);
    state.currentId = b.id;
    renderBookmarks();
    video.currentTime = b.timestamp;
    video.play().catch(() => {});
    save();
  }

  function deleteBookmark(id) {
    state.bookmarks = state.bookmarks.filter(b => b.id !== id);
    if (state.currentId === id) clearSelection();
    renderBookmarks();
    save();
  }

  function saveBookmark() {
    const b = state.bookmarks.find(x => x.id === state.currentId);
    if (!b) return;
    b.timestamp = parseFloat(editorTimestamp.value) || 0;
    b.note = editorNote.value.trim();
    save();
    renderBookmarks();
  }

  function updateThumbnail(file) {
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
      const b = state.bookmarks.find(x => x.id === state.currentId);
      if (!b) return;
      b.thumbnail = e.target.result;
      thumbDrop.querySelector('.thumb-preview').innerHTML = `<img src="${b.thumbnail}" alt="">`;
      save();
      renderBookmarks();
    };
    reader.readAsDataURL(file);
  }

  // ---------- Export / Import ----------
  function exportProject() {
    const data = {
      version: 1,
      bookmarks: state.bookmarks.map(b => ({
        id: b.id,
        timestamp: b.timestamp,
        note: b.note,
        thumbnail: b.thumbnail,
      })),
      createdAt: Date.now(),
    };
    const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `framemarker-${Date.now()}.json`;
    a.click();
    URL.revokeObjectURL(url);
  }

  function importProject(file) {
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = JSON.parse(e.target.result);
        if (data.version !== 1) {
          alert('Unsupported project version.');
          return;
        }
        state.bookmarks = data.bookmarks.map(b => ({
          id: b.id,
          timestamp: b.timestamp,
          note: b.note || '',
          thumbnail: b.thumbnail,
        }));
        state.nextId = Math.max(0, ...state.bookmarks.map(b => b.id)) + 1;
        renderBookmarks();
        save();
      } catch (err) {
        alert('Invalid JSON file.');
      }
    };
    reader.readAsText(file);
  }

  // ---------- Keyboard shortcuts ----------
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
      e.preventDefault();
      addBookmark();
    }
    if (e.key === 'Escape') {
      clearSelection();
    }
  });

  // ---------- Video events ----------
  video.addEventListener('timeupdate', () => {
    // Auto-save current time if editing
    if (state.editing && state.currentId) {
      const b = state.bookmarks.find(x => x.id === state.currentId);
      if (b) b.timestamp = video.currentTime;
    }
  });
  video.addEventListener('play', () => video.classList.add('playing'));
  video.addEventListener('pause', () => video.classList.remove('playing'));
  video.addEventListener('ended', () => video.currentTime = 0);

  // ---------- UI wiring ----------
  addBtn.addEventListener('click', addBookmark);
  saveBtn.addEventListener('click', saveBookmark);
  deleteBtn.addEventListener('click', () => deleteBookmark(state.currentId));
  clearBtn.addEventListener('click', () => {
    if (state.bookmarks.length === 0) return;
    if (confirm('Clear all bookmarks?')) {
      state.bookmarks = [];
      state.currentId = null;
      renderBookmarks();
      save();
    }
  });
  exportBtn.addEventListener('click', exportProject);
  importBtn.addEventListener('click', () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = '.json';
    input.onchange = (e) => {
      if (e.target.files && e.target.files[0]) importProject(e.target.files[0]);
    };
    input.click();
  });

  thumbDrop.addEventListener('click', (e) => {
    if (e.target.closest('svg') || e.target.closest('span')) {
      thumbInput.click();
    }
  });
  thumbInput.addEventListener('change', (e) => {
    if (e.target.files && e.target.files[0]) updateThumbnail(e.target.files[0]);
    thumbInput.value = '';
  });
  thumbDrop.addEventListener('dragover', (e) => { e.preventDefault(); thumbDrop.classList.add('drag'); });
  thumbDrop.addEventListener('dragleave', () => thumbDrop.classList.remove('drag'));
  thumbDrop.addEventListener('drop', (e) => {
    e.preventDefault();
    thumbDrop.classList.remove('drag');
    if (e.dataTransfer.files && e.dataTransfer.files[0]) updateThumbnail(e.dataTransfer.files[0]);
  });

  // Live clear editor when switching bookmarks
  bookmarkList.addEventListener('click', (e) => {
    if (e.target.closest('.remove')) return;
    const item = e.target.closest('.bookmark-item');
    if (item) selectBookmark(parseInt(item.dataset.id, 10));
  });

  // Drag to reorder
  bookmarkList.addEventListener('dragstart', (e) => {
    const item = e.target.closest('.bookmark-item');
    if (!item) return;
    item.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', item.dataset.id);
  });
  bookmarkList.addEventListener('dragend', (e) => e.target.classList.remove('dragging'));

  // ---------- Init ----------
  load();
  renderBookmarks();
})();
```

