### `backend/models/Drone.js`
```javascript
const db = require('../db');

class Drone {
    static getAll() {
        return db.prepare('SELECT * FROM drones ORDER BY last_updated DESC').all();
    }

    static getById(id) {
        return db.prepare('SELECT * FROM drones WHERE id = ?').get(id);
    }

    static create(name, model, serial) {
        return db.prepare('INSERT INTO drones (name, model, serial) VALUES (?, ?, ?)').run(name, model, serial);
    }

    static update(id, status, battery, lat, lon) {
        return db.prepare('UPDATE drones SET status = ?, battery = ?, latitude = ?, longitude = ?, last_updated = CURRENT_TIMESTAMP WHERE id = ?')
            .run(status, battery, lat, lon, id);
    }

    static delete(id) {
        return db.prepare('DELETE FROM drones WHERE id = ?').run(id);
    }
}

module.exports = Drone;
```

### `backend/middleware/auth.js`
```javascript
const db = require('../db');

function requireAuth(req, res, next) {
    const auth = req.headers.authorization;
    if (!auth) return res.status(401).json({ error: 'Authorization required' });

    const [bearer, token] = auth.split(' ');
    if (bearer !== 'Bearer') return res.status(401).json({ error: 'Invalid token format' });

    db.prepare('SELECT * FROM users WHERE username = ? AND password = ?').get(token, token, (err, row) => {
        if (err) return res.status(500).json({ error: 'Server error' });
        if (!row) return res.status(401).json({ error: 'Invalid credentials' });
        req.user = row;
        next();
    });
}

function requireAdmin(req, res, next) {
    if (req.user.role !== 'admin') return res.status(403).json({ error: 'Admin access required' });
    next();
}

module.exports = { requireAuth, requireAdmin };
```

### `backend/routes/drones.js`
```javascript
const express = require('express');
const router = express.Router();
const Drone = require('../models/Drone');
const { requireAuth, requireAdmin } = require('../middleware/auth');

// GET all drones
router.get('/', requireAuth, async (req, res) => {
    const drones = await Drone.getAll();
    res.json(drones);
});

// GET single drone
router.get('/:id', requireAuth, async (req, res) => {
    const drone = await Drone.getById(req.params.id);
    if (!drone) return res.status(404).json({ error: 'Drone not found' });
    res.json(drone);
});

// POST new drone (admin only)
router.post('/', requireAuth, requireAdmin, async (req, res) => {
    const { name, model, serial } = req.body;
    if (!name || !model || !serial) return res.status(400).json({ error: 'Missing required fields' });
    try {
        await Drone.create(name, model, serial);
        res.status(201).json({ message: 'Drone added successfully' });
    } catch (e) {
        res.status(409).json({ error: 'Drone name already exists' });
    }
});

// PUT update drone status (simulate flight actions)
router.put('/:id', requireAuth, async (req, res) => {
    const { status, battery, latitude, longitude } = req.body;
    const drone = await Drone.getById(req.params.id);
    if (!drone) return res.status(404).json({ error: 'Drone not found' });

    if (status === 'in-flight' || status === 'landing') {
        // Simulate battery drain
        const drain = status === 'in-flight' ? 5 : 2;
        battery = Math.max(0, Math.min(100, battery - drain));
    }

    await Drone.update(req.params.id, status, battery, latitude, longitude);
    res.json({ message: 'Drone status updated', drone });
});

// DELETE drone
router.delete('/:id', requireAuth, requireAdmin, async (req, res) => {
    await Drone.delete(req.params.id);
    res.json({ message: 'Drone removed' });
});

module.exports = router;
```

