      </span>
    </div>

    <div class="drone-map">
      <div class="map-dot" :style="{ left: latPct + '%', top: lonPct + '%' }"></div>
      <div class="map-label">📍 {{ latLabel }}°, {{ lonLabel }}°</div>
    </div>

    <div class="drone-actions">
      <button @click="takeoff" :disabled="drone.status === 'in-flight' || drone.status === 'landing'">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M12 19V5M5 12l7-7 7 7"/>
        </svg>
        Takeoff
      </button>
      <button @click="land" :disabled="drone.status === 'idle'">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
          <path d="M12 5v14M5 12l7 7 7-7"/>
        </svg>
        Land
      </button>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import StatusBadge from './StatusBadge.vue';

const props = defineProps({
  drone: Object,
});
const latPct = ref(50);
const lonPct = ref(50);
const latLabel = ref(0);
const lonLabel = ref(0);

const updateMap = () => {
  if (!props.drone.latitude || !props.drone.longitude) return;
  const lat = props.drone.latitude;
  const lon = props.drone.longitude;
  latLabel.value = Math.round(lat * 10000) / 10000;
  lonLabel.value = Math.round(lon * 10000) / 10000;
  // Clamp to 50% (center) for demo simplicity
  latPct.value = 50;
  lonPct.value = 50;
};

const takeoff = () => {
  const status = props.drone.status;
  if (status === 'in-flight' || status === 'landing') return;
  updateDrone('in-flight', 95);
};
const land = () => {
  const status = props.drone.status;
  if (status === 'idle') return;
  updateDrone('idle', 100);
};

const updateDrone = async (status, battery) => {
  const id = props.drone.id;
  try {
    const res = await fetch(`/api/drones/${id}`, {
      method: 'PUT',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ status, battery }),
    });
    const data = await res.json();
    if (res.ok) {
      // Update local props
      Object.assign(props.drone, { status: data.drone.status, battery: data.drone.battery });
    }
  } catch (e) {
    console.error(e);
  }
};

onMounted(updateMap);
</script>

