        <button class="btn btn-secondary" id="resetBtn">Reset</button>
      </div>
    </div>
  </div>

  <div class="panel">
    <h1>Style</h1>
    <p>Customize the appearance of your subtitles.</p>

    <div class="style-row">
      <label for="fontFamily">Font Family</label>
      <input type="text" id="fontFamilyS" value="'Inter', system-ui, sans-serif">
      <label for="fontSize">Size (px)</label>
      <input type="number" id="fontSizeS" value="24" min="10" max="100">
      <label for="color">Color</label>
      <input type="color" id="colorS" value="#ffffff">
      <label for="bgColor">Background</label>
      <input type="color" id="bgColorS" value="#000000">
      <label for="opacity">Opacity (%)</label>
      <input type="number" id="opacityS" value="85" min="0" max="100" step="1">
    </div>

    <div class="preview" id="preview">
      <div style="font-family: 'Inter', system-ui, sans-serif; font-size: 24px; color: #ffffff; background: #000000; opacity: 0.85; padding: 12px; border-radius: 6px; letter-spacing: 0.01em;">
        Hello world! This is a preview of your subtitle style.
      </div>
    </div>

    <div class="actions">
      <button class="btn btn-primary" id="exportBtn">Export as .VTT</button>
      <button class="btn btn-secondary" id="mergeBtn">Export merged .webm</button>
    </div>

    <div class="status" id="status"></div>
  </div>

</div>

<script>
// ---------- State ----------
const state = {
  video: null,
  subtitles: [],
  style: {
    fontFamily: "'Inter', system-ui, sans-serif",
    fontSize: 24,
    color: '#ffffff',
    bgColor: '#000000',
    opacity: 0.85
  }
};

// ---------- DOM ----------
const $ = (id) => document.getElementById(id);
const video = $('video');
const subEditor = $('subEditor');
const subDisplay = $('subDisplay');
const timeInfo = $('timeInfo');
const playBtn = $('playBtn');
const muteBtn = $('muteBtn');
const applyBtn = $('applyBtn');
const resetBtn = $('resetBtn');
const exportBtn = $('exportBtn');
const mergeBtn = $('mergeBtn');
const status = $('status');
const videoWrap = $('videoWrap');

// ---------- Video ----------
$('input[type="file"]').addEventListener('change', (e) => {
  const file = e.target.files[0];
  if (!file) return;
  const url = URL.createObjectURL(file);
  video.src = url;
  video.load();
  status.textContent = `Loaded: ${file.name} (${(file.size/1024/1024).toFixed(2)} MB)`;
  status.className = 'status';
});

playBtn.addEventListener('click', () => video.play().catch(() => {}));
muteBtn.addEventListener('click', () => video.muted = !video.muted);

// ---------- Subtitle parser ----------
function parseSubs(text) {
  const lines = text.split('\n');
  const subs = [];
  let current = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      if (current.length >= 2) {
        const [start, end] = current.map(s => s.trim());
        subs.push({ start, end, text: current.slice(2).join('\n').trim() });
      }
      current = [];
      continue;
    }
    if (/^\d{2}:\d{2}:\d{2}\.\d{3}\s*-->\s*\d{2}:\d{2}:\d{2}\.\d{3}$/.test(trimmed)) {
      if (current.length >= 2) {
        const [start, end] = current.map(s => s.trim());
        subs.push({ start, end, text: current.slice(2).join('\n').trim() });
      }
      current = [trimmed];
    } else {
      current.push(trimmed);
    }
  }
  if (current.length >= 2) {
    const [start, end] = current.map(s => s.trim());
    subs.push({ start, end, text: current.slice(2).join('\n').trim() });
  }
  return subs;
}

// ---------- Apply ----------
applyBtn.addEventListener('click', () => {
  const text = subEditor.value;
  const subs = parseSubs(text);
  state.subtitles = subs;
  // Reset video time
  video.currentTime = 0;
  // Update display
  updateDisplay();
  status.textContent = `Applied ${subs.length} subtitle(s).`;
  status.className = 'status';
});

resetBtn.addEventListener('click', () => {
  subEditor.value = '';
  state.subtitles = [];
  video.currentTime = 0;
  updateDisplay();
  status.textContent = 'Subtitles reset.';
  status.className = 'status';
});

// ---------- Display sync ----------
function updateDisplay() {
  if (!state.subtitles.length) {
    subDisplay.textContent = '';
    subDisplay.classList.remove('active');
    return;
  }
  const now = video.currentTime;
  const current = state.subtitles.find(s => now >= parseTime(s.start) && now < parseTime(s.end));
  if (current) {
    subDisplay.textContent = current.text;
    subDisplay.classList.add('active');
  } else {
    subDisplay.textContent = '';
    subDisplay.classList.remove('active');
  }
}

function parseTime(t) {
  const [hms, ms] = t.split('.');
  const [h, m, s] = hms.split(':').map(Number);
  return h * 3600 + m * 60 + s + Number(ms) / 1000;
}

video.addEventListener('timeupdate', updateDisplay);

// ---------- Style sync ----------
function applyStyle() {
  state.style.fontFamily = $('fontFamilyS').value;
  state.style.fontSize = parseInt($('fontSizeS').value, 10) || 24;
  state.style.color = $('colorS').value;
  state.style.bgColor = $('bgColorS').value;
  state.style.opacity = parseFloat($('opacityS').value) / 100;
  updatePreview();
}

$('fontFamilyS').addEventListener('input', applyStyle);
$('fontSizeS').addEventListener('input', applyStyle);
$('colorS').addEventListener('input', applyStyle);
$('bgColorS').addEventListener('input', applyStyle);
$('opacityS').addEventListener('input', applyStyle);

function updatePreview() {
  const p = $('preview');
  const text = p.querySelector('div');
  if (!text) return;
  text.style.fontFamily = state.style.fontFamily;
  text.style.fontSize = state.style.fontSize + 'px';
  text.style.color = state.style.color;
  text.style.background = state.style.bgColor;
  text.style.opacity = state.style.opacity;
  text.textContent = 'Hello world! This is a preview of your subtitle style.';
}

// ---------- Export VTT ----------
exportBtn.addEventListener('click', () => {
  if (!state.subtitles.length) {
    status.textContent = 'No subtitles to export.';
    status.className = 'status error';
    return;
  }
  const header = 'WEBVTT\n\n';
  const body = state.subtitles.map(s => {
    const start = formatTime(parseTime(s.start));
    const end = formatTime(parseTime(s.end));
    return `${start} --> ${end}\n${s.text}\n`;
  }).join('\n');
  const blob = new Blob([header + body], { type: 'text/vtt' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'subtitles.vtt';
  a.click();
  URL.revokeObjectURL(url);
  status.textContent = 'VTT exported successfully.';
  status.className = 'status';
});

function formatTime(sec) {
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  const ms = Math.floor((sec - Math.floor(sec)) * 1000);
  return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;
}

// ---------- Merge video + VTT (blob-based, simple) ----------
mergeBtn.addEventListener('click', () => {
  if (!state.subtitles.length) {
    status.textContent = 'No subtitles to export.';
    status.className = 'status error';
    return;
  }
  status.textContent = 'Preparing merged video...';
  status.className = 'status';

  const videoUrl = video.src;
  const videoBlob = new Blob([videoUrl], { type: 'video/mp4' });
  const vttBlob = new Blob([generateVtt()], { type: 'text/vtt' });

  const reader = new FileReader();
  reader.onload = async () => {
    const videoData = reader.result;
    const vttData = vttBlob;

    // Create a temporary video element to read as array buffer
    const tmpVideo = document.createElement('video');
    tmpVideo.src = URL.createObjectURL(videoData);
    tmpVideo.muted = true;
    tmpVideo.playsInline = true;
    tmpVideo.preload = 'auto';

    await new Promise((res) => tmpVideo.addEventListener('loadedmetadata', res, { once: true }));

    const duration = tmpVideo.duration;
    const canvas = document.createElement('canvas');
    canvas.width = tmpVideo.videoWidth;
    canvas.height = tmpVideo.videoHeight;
    const ctx = canvas.getContext('2d');

    // Draw frames + subtitles
    const tracks = [];
    for (let i = 0; i < state.subtitles.length; i++) {
      const s = state.subtitles[i];
      const start = parseTime(s.start);
      const end = parseTime(s.end);
      const track = {
        id: 'sub' + i,
        start,
        end,
        text: s.text,
        style: state.style
      };
      tracks.push(track);
    }

    // Sort by start
    tracks.sort((a, b) => a.start - b.start);

    // Render
    const totalFrames = Math.floor(duration * 60);
    const frameDuration = 1 / 60;
    const frames = [];
    for (let f = 0; f < totalFrames; f++) {
      const t = f * frameDuration;
      let active = null;
      for (const track of tracks) {
        if (t >= track.start && t < track.end) active = track;
      }
      frames.push({ t, active });
    }

    tmpVideo.pause();
    tmpVideo.src = '';
    tmpVideo.remove();

    // Render to canvas
    for (let f = 0; f < frames.length; f++) {
      const { t, active } = frames[f];
      tmpVideo.currentTime = t;
      await new Promise((res) => tmpVideo.addEventListener('seeked', res, { once: true }));
      ctx.drawImage(tmpVideo, 0, 0, canvas.width, canvas.height);
      if (active) {
        ctx.fillStyle = active.style.bgColor;
        ctx.globalAlpha = active.style.opacity;
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.globalAlpha = 1;
        ctx.fillStyle = active.style.color;
        ctx.font = `${active.style.fontSize}px ${active.style.fontFamily}`;
        ctx.textBaseline = 'middle';
        ctx.textAlign = 'center';
        const lines = wrapText(active.text, canvas.width, ctx);
        for (let i = 0; i < lines.length; i++) {
          const y = (canvas.height / 2) - (lines.length - 1) * 28 - i * 28;
          ctx.fillText(lines[i], canvas.width / 2, y);
        }
      }
    }

    canvas.toBlob((blob) => {
      if (!blob) {
        status.textContent = 'Failed to render merged video.';
        status.className = 'status error';
        return;
      }
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'video-with-subtitles.webm';
      a.click();
      URL.revokeObjectURL(url);
      status.textContent = 'Merged video exported successfully.';
      status.className = 'status';
    }, 'image/webp');
  };
  reader.onerror = () => {
    status.textContent = 'Failed to read video.';
    status.className = 'status error';
  };
  reader.readAsArrayBuffer(videoBlob);
});

function generateVtt() {
  const header = 'WEBVTT\n\n';
  const body = state.subtitles.map(s => {
    const start = formatTime(parseTime(s.start));
    const end = formatTime(parseTime(s.end));
    return `${start} --> ${end}\n${s.text}\n`;
  }).join('\n');
  return header + body;
}

function wrapText(text, maxWidth, ctx) {
  const words = text.split(' ');
  const lines = [];
  let currentLine = '';
  for (const word of words) {
    const test = currentLine + (currentLine ? ' ' : '') + word;
    const w = ctx.measureText(test).width;
    if (w > maxWidth) {
      if (currentLine) lines.push(currentLine);
      currentLine = word;
    } else {
      currentLine = test;
    }
  }
  if (currentLine) lines.push(currentLine);
  return lines;
}

// ---------- Keyboard shortcuts ----------
document.addEventListener('keydown', (e) => {
  if (e.target.tagName === 'TEXTAREA') return;
  if (e.code === 'Space') { e.preventDefault(); video.paused ? video.play() : video.pause(); }
  if (e.key === 'Enter' && e.target === subEditor) { e.preventDefault(); subEditor.blur(); }
});
</script>
</body>
</html>
```

