## 📦 Cart (useCart.js)

```javascript
// hooks/useCart.js
import { useContext, useEffect, useReducer } from "react";
import { AuthContext } from "../hooks/useAuth";
import { storage } from "../services/storage";

const CART_KEY = "cart";

const initialState = {
  items: [],
  negotiations: [],
};

const cartReducer = (state, action) => {
  switch (action.type) {
    case "ADD_ITEM":
      const existing = state.items.find(
        (it) => it.id === action.payload.id
      );
      if (existing) {
        return {
          ...state,
          items: state.items.map((it) =>
            it.id === action.payload.id
              ? { ...it, quantity: it.quantity + action.payload.quantity }
              : it
          ),
        };
      }
      return { ...state, items: [...state.items, action.payload] };

    case "REMOVE_ITEM":
      return {
        ...state,
        items: state.items.filter((it) => it.id !== action.payload),
      };

    case "UPDATE_QUANTITY":
      return {
        ...state,
        items: state.items.map((it) =>
          it.id === action.payload.id
            ? { ...it, quantity: action.payload.quantity }
            : it
        ),
      };

    case "START_NEGOTIATION":
      return {
        ...state,
        negotiations: [
          ...state.negotiations,
          { id: Date.now(), ...action.payload },
        ],
      };

    case "CANCEL_NEGOTIATION":
      return {
        ...state,
        negotiations: state.negotiations.filter(
          (n) => n.id !== action.payload
        ),
      };

    case "COMPLETE_NEGOTIATION":
      return {
        ...state,
        negotiations: state.negotiations.filter(
          (n) => n.id !== action.payload
        ),
        items: state.items.map((it) =>
          it.id === action.payload.productId
            ? { ...it, negotiated: true, finalPrice: action.payload.finalPrice }
            : it
        ),
      };

    case "CLEAR":
      return { items: [], negotiations: [] };

    default:
      return state;
  }
};

export const useCart = () => {
  const { user } = useContext(AuthContext);
  const [state, dispatch] = useReducer(cartReducer, initialState);

  useEffect(() => {
    if (!user) return;
    try {
      const saved = storage.getItem(CART_KEY);
      if (saved) dispatch({ type: "CLEAR" });
    } catch (e) {}
  }, [user]);

  useEffect(() => {
    if (user) {
      try {
        storage.setItem(CART_KEY, JSON.stringify(state));
      } catch (e) {}
    }
  }, [state, user]);

  const addItem = (item, quantity = 1) => {
    dispatch({ type: "ADD_ITEM", payload: { ...item, quantity } });
  };

  const removeItem = (id) => dispatch({ type: "REMOVE_ITEM", payload: id });

  const updateQuantity = (id, quantity) => {
    if (quantity <= 0) removeItem(id);
    else dispatch({ type: "UPDATE_QUANTITY", payload: { id, quantity } });
  };

  const startNegotiation = (item, offer) =>
    dispatch({
      type: "START_NEGOTIATION",
      payload: {
        productId: item.id,
        sellerId: item.sellerId,
        sellerName: item.sellerName,
        originalPrice: item.price,
        offerPrice: offer,
        status: "pending",
      },
    });

  const cancelNegotiation = (id) =>
    dispatch({ type: "CANCEL_NEGOTIATION", payload: id });

  const completeNegotiation = (id, finalPrice) =>
    dispatch({
      type: "COMPLETE_NEGOTIATION",
      payload: { productId: id, finalPrice },
    });

  const getTotal = () =>
    state.items.reduce(
      (sum, it) => sum + it.price * it.quantity,
      0
    );

  const getNegotiationCount = () =>
    state.negotiations.filter((n) => n.status === "pending").length;

  const getNegotiatedCount = () =>
    state.items.filter((it) => it.negotiated).length;

  return {
    items: state.items,
    negotiations: state.negotiations,
    total: getTotal(),
    negotiationCount: getNegotiationCount(),
    negotiatedCount: getNegotiatedCount(),
    addItem,
    removeItem,
    updateQuantity,
    startNegotiation,
    cancelNegotiation,
    completeNegotiation,
  };
};
