## 🔍 Product Filters & Sorting

```javascript
// utils/sort.js
export const sortProducts = (products, sortKey, sortDir = "asc") => {
  const dir = sortDir === "asc" ? 1 : -1;
  const sorted = [...products].sort((a, b) => {
    switch (sortKey) {
      case "price":
        return (a.price - b.price) * dir;
      case "rating":
        return (b.rating - a.rating) * dir;
      case "newest":
        return (b.createdAt - a.createdAt) * dir;
      default:
        return 0;
    }
  });
  return sorted;
};
```

