### 5. Cart

```javascript
// components/Cart/Cart.jsx
import { useCart } from "../../hooks/useCart";
import { useAuth } from "../../hooks/useAuth";
import { Button } from "./UI/Button";
import { Link } from "react-router-dom";
import { CartItem } from "./CartItem";
import { NegotiationModal } from "./NegotiationModal";
import { SellerInfo } from "./Seller/SellerInfo";

export const Cart = () => {
  const cart = useCart();
  const { user } = useAuth();
  const [openNegotiation, setOpenNegotiation] = useState(false);
  const [negotiation, setNegotiation] = useState(null);

  const handleStartNegotiation = (item) => {
    cart.startNegotiation(item, item.price * 0.85);
    setNegotiation({ ...item, offerPrice: item.price * 0.85 });
    setOpenNegotiation(true);
  };

  const handleCompleteNegotiation = (finalPrice) => {
    cart.completeNegotiation(negotiation.id, finalPrice);
    setNegotiation(null);
    setOpenNegotiation(false);
  };

  const handleCancelNegotiation = () => {
    cart.cancelNegotiation(negotiation.id);
    setNegotiation(null);
    setOpenNegotiation(false);
  };

  if (cart.items.length === 0 && cart.negotiations.length === 0) {
    return (
      <div className="cart-empty">
        <div className="empty-illustration">
          <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5">
            <path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>
            <path d="M9 22V12h6v10"/>
          </svg>
        </div>
        <h2>Your cart is empty</h2>
        <p>Start browsing products to add them here.</p>
        <Link to="/products" className="btn-primary">Browse Products</Link>
      </div>
    );
  }

  return (
    <div className="cart">
      <div className="cart-items">
        {cart.items.map((item) => (
          <CartItem
            key={item.id}
            item={item}
            onNegotiate={() => handleStartNegotiation(item)}
          />
        ))}
        {cart.negotiations.map((n) => (
          <div key={n.id} className="negotiation-item">
            <div className="negotiation-head">
              <h3>{n.title}</h3>
              <span className="negotiation-status pending">Pending</span>
            </div>
            <p className="negotiation-desc">Negotiation with <strong>{n.sellerName}</strong> at ${formatPrice(n.offerPrice)}</p>
            <div className="negotiation-actions">
              <button onClick={() => cart.cancelNegotiation(n.id)}>Cancel</button>
              <button onClick={() => handleCompleteNegotiation(n.id, n.offerPrice)}>Accept</button>
            </div>
          </div>
        ))}
      </div>

      <div className="cart-summary">
        <div className="summary-row">
          <span>Subtotal</span>
          <span>${cart.total.toFixed(2)}</span>
        </div>
        <div className="summary-row">
          <span>Items</span>
          <span>{cart.items.length}</span>
        </div>
        <div className="summary-row">
          <span>Negotiations</span>
          <span>{cart.negotiationCount}</span>
        </div>
        <div className="summary-row total">
          <span>Total</span>
          <span>${cart.total.toFixed(2)}</span>
        </div>
        <Button onClick={() => setOpenNegotiation(true)} disabled={cart.negotiationCount === 0}>
          Complete Negotiation
        </Button>
      </div>

      <NegotiationModal
        isOpen={openNegotiation}
        negotiation={negotiation}
        onClose={handleCancelNegotiation}
        onConfirm={handleCompleteNegotiation}
      />
    </div>
  );
};
