  const markerStart = $('markerStart');
  const markerEnd = $('markerEnd');
  const zoomIn = $('zoomIn');
  const zoomOut = $('zoomOut');
  const zoomLabel = $('zoomLabel');
  const status = $('status');

  const effectReverse = $('effectReverse');
  const effectEcho = $('effectEcho');
  const effectDistort = $('effectDistort');
  const echoVal = $('echoVal');
  const distortVal = $('distortVal');

  const state = {
    audioCtx: null,
    stream: null,
    source: null,
    recorder: null,
    chunks: [],
    recording: false,
    recordingStart: 0,
    audioBuffer: null,
    samples: [],
    markers: { start: 0, end: 0 },
    zoom: 100,
    zoomMax: 300,
    zoomMin: 50,
  };

  // ---------- Audio context helpers ----------
  const ensureCtx = () => {
    if (!state.audioCtx) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      state.audioCtx = new Ctx();
    }
    if (state.audioCtx.state === 'suspended') state.audioCtx.resume();
    return state.audioCtx;
  };

  // ---------- MediaRecorder setup ----------
  const setupRecorder = () => {
    const ctx = ensureCtx();
    const bufferSize = 4096;
    const source = ctx.createScriptProcessor(bufferSize, 1, 1);
    source.onaudioprocess = (e) => {
      const input = e.inputBuffer.getChannelData(0);
      const output = e.outputBuffer.getChannelData(0);
      for (let i = 0; i < bufferSize; i++) {
        output[i] = input[i] * 0.95;
      }
      state.samples.push(input);
    };
    source.connect(ctx.destination);

    if (state.stream) {
      const newSource = ctx.createMediaStreamSource(state.stream);
      newSource.connect(source);
      state.source = newSource;
    }

    // Stop existing recorder if any
    if (state.recorder) {
      state.recorder.stop();
      state.recorder = null;
    }

    const mime = 'audio/webm;codecs=opus';
    state.recorder = new MediaRecorder(state.stream, { mimeType: mime });
    state.recorder.ondataavailable = (e) => {
      if (e.data.size > 0) state.chunks.push(e.data);
    };
    state.recorder.onstop = () => {
      state.recording = false;
      startBtn.disabled = false;
      stopBtn.disabled = true;
      status.textContent = 'Recording stopped. Ready to trim.';
    };
  };

  // ---------- Start / Stop ----------
  const startRecording = async () => {
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      status.textContent = 'Microphone not supported in this browser.';
      return;
    }
    try {
      state.stream = await navigator.mediaDevices.getUserMedia({
        audio: { echoCancellation: true, noiseSuppression: true },
      });
      state.recordingStart = performance.now();
      state.chunks = [];
      state.samples = [];
      setupRecorder();
      state.recorder.start(100);
      state.recording = true;
      startBtn.disabled = true;
      stopBtn.disabled = false;
      status.textContent = 'Recording...';
    } catch (err) {
      status.textContent = 'Permission denied. Please allow microphone access.';
    }
  };

  const stopRecording = () => {
    if (state.recorder) {
      state.recorder.stop();
    }
    if (state.source) {
      state.source.disconnect();
      state.source = null;
    }
  };

  // ---------- Trim ----------
  const trim = () => {
    if (!state.audioBuffer) {
      status.textContent = 'No recording yet. Start recording first.';
      return;
    }
    const start = state.markers.start;
    const end = state.markers.end;
    if (start >= end) {
      status.textContent = 'End marker must be after start marker.';
      return;
    }
    const len = state.audioBuffer.length;
    const cutStart = Math.max(0, Math.floor(start * len));
    const cutEnd = Math.min(len, Math.ceil(end * len));
    const trimmed = state.audioBuffer.copyMakeWhole(cutStart, cutEnd - cutStart);
    state.audioBuffer = trimmed;
    renderWaveform();
    status.textContent = `Trimmed to ${cutEnd - cutStart} samples.`;
  };

  // ---------- Effects ----------
  const applyEffects = () => {
    if (!state.audioBuffer) {
      status.textContent = 'No audio to process.';
      return;
    }
    const ctx = ensureCtx();
    const numChannels = state.audioBuffer.numberOfChannels;
    const channels = [];
    for (let i = 0; i < numChannels; i++) channels.push(state.audioBuffer.getChannelData(i));

    const reverse = effectReverse.checked;
    const echoMs = parseInt(effectEcho.value, 10);
    const distortPct = parseInt(effectDistort.value, 10) / 100;

    const outputBuffer = ctx.createBuffer(numChannels, state.audioBuffer.length, state.audioBuffer.sampleRate);
    const output = [];
    for (let i = 0; i < numChannels; i++) output.push(outputBuffer.getChannelData(i));

    for (let c = 0; c < numChannels; c++) {
      const inData = channels[c];
      const outData = output[c];
      const len = inData.length;

      if (reverse) {
        for (let i = 0; i < len; i++) outData[len - 1 - i] = inData[i];
      } else {
        for (let i = 0; i < len; i++) outData[i] = inData[i];
      }

      // Echo
      if (echoMs > 0) {
        const delaySamples = Math.floor(echoMs * state.audioBuffer.sampleRate / 1000);
        for (let i = 0; i < len; i++) {
          const delayIdx = i + delaySamples;
          if (delayIdx < len) {
            outData[i] += inData[i] * 0.5;
          }
        }
      }

      // Distortion
      for (let i = 0; i < len; i++) {
        const v = outData[i];
        const distorted = Math.tanh(v * (1 + distortPct));
        outData[i] = distorted;
      }
    }

    state.audioBuffer = outputBuffer;
    renderWaveform();
    status.textContent = 'Effects applied.';
  };

  // ---------- Export WAV ----------
  const exportWAV = () => {
    if (!state.audioBuffer) {
      status.textContent = 'No audio to export.';
      return;
    }
    try {
      const ctx = ensureCtx();
      const array = new Float32Array(state.audioBuffer.length * state.audioBuffer.numberOfChannels);
      for (let c = 0; c < state.audioBuffer.numberOfChannels; c++) {
        const data = state.audioBuffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) array[i * state.audioBuffer.numberOfChannels + c] = data[i];
      }
      const wav = Wav.encode(array, state.audioBuffer.sampleRate, 16);
      const blob = new Blob([new Uint8Array(wav)], { type: 'audio/wav' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'edited-audio.wav';
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      setTimeout(() => URL.revokeObjectURL(url), 1000);
      status.textContent = 'Download started.';
    } catch (err) {
      status.textContent = 'Export failed: ' + err.message;
    }
  };

  // ---------- Waveform rendering ----------
  const drawWaveform = () => {
    const ctx = waveform.getContext('2d');
    const w = waveform.width;
    const h = waveform.height;
    const padding = 10;
    const bw = w - padding * 2;
    const bh = h - padding * 2;
    const maxAmp = Math.max(1, state.audioBuffer ? state.audioBuffer.maxValue : 1);

    ctx.clearRect(0, 0, w, h);

    if (!state.audioBuffer) {
      ctx.fillStyle = '#94a3b8';
      ctx.fillRect(padding, padding, bw, bh);
      return;
    }

    const channels = state.audioBuffer.numberOfChannels;
    const step = Math.max(1, Math.ceil(bw / state.audioBuffer.length));
    const scale = bh / (2 * maxAmp);

    ctx.fillStyle = '#94a3b8';
    ctx.fillRect(padding, padding, bw, bh);

    const colors = ['#3b82f6', '#8b5cf6', '#ec4899', '#10b981'];

    for (let c = 0; c < channels; c++) {
      const data = state.audioBuffer.getChannelData(c);
      ctx.strokeStyle = colors[c % colors.length];
      ctx.lineWidth = 1;
      ctx.beginPath();
      let prev = null;
      for (let i = 0; i < data.length; i += step) {
        const v = data[i];
        const y = padding + bh / 2 + (v > 0 ? v : -v) * scale;
        if (prev) ctx.lineTo(prev.x, prev.y);
        ctx.lineTo(i, y);
        prev = { x: i, y };
      }
      ctx.stroke();
    }
  };

  const renderWaveform = () => {
    drawWaveform();
    updateMarkers();
  };

  const updateMarkers = () => {
    const ctx = waveform.getContext('2d');
    const w = waveform.width;
    const h = waveform.height;
    const padding = 10;
    const bw = w - padding * 2;
    const bh = h - padding * 2;

    if (!state.audioBuffer) return;

    const channels = state.audioBuffer.numberOfChannels;
    const step = Math.max(1, Math.ceil(bw / state.audioBuffer.length));
    const scale = bh / (2 * state.audioBuffer.maxValue);

    const startPx = padding + (state.markers.start * bw) / state.audioBuffer.length;
    const endPx = padding + (state.markers.end * bw) / state.audioBuffer.length;

    ctx.fillStyle = 'rgba(239, 68, 68, 0.25)';
    ctx.fillRect(startPx, padding, endPx - startPx, bh);

    // Channel lines
    for (let c = 0; c < channels; c++) {
      const data = state.audioBuffer.getChannelData(c);
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 1;
      ctx.beginPath();
      let prev = null;
      for (let i = 0; i < data.length; i += step) {
        const v = data[i];
        const y = padding + bh / 2 + (v > 0 ? v : -v) * scale;
        if (prev) ctx.lineTo(prev.x, prev.y);
        ctx.lineTo(i, y);
        prev = { x: i, y };
      }
      ctx.stroke();
    }
  };

  // ---------- Zoom ----------
  const setZoom = (z) => {
    state.zoom = Math.max(state.zoomMin, Math.min(state.zoomMax, z));
    zoomLabel.textContent = state.zoom + '%';
    renderWaveform();
  };

  // ---------- Drag markers ----------
  const makeDraggable = (el, min, max) => {
    let dragging = false;
    let startX = 0, startLeft = 0, startSample = 0;

    const onDown = (e) => {
      if (state.recording) return;
      e.preventDefault();
      dragging = true;
      startX = e.clientX;
      startLeft = parseFloat(el.style.left);
      startSample = state.markers[el.id === 'markerStart' ? 'start' : 'end'];
      el.classList.add('dragging');
    };
    const onMove = (e) => {
      if (!dragging) return;
      const dx = e.clientX - startX;
      const w = waveform.clientWidth;
      const ratio = (startLeft + dx / w) / 100;
      const newSample = Math.max(min, Math.min(max, ratio * state.audioBuffer.length));
      state.markers[el.id === 'markerStart' ? 'start' : 'end'] = newSample;
      el.style.left = (ratio * 100) + '%';
    };
    const onUp = () => {
      if (!dragging) return;
      dragging = false;
      el.classList.remove('dragging');
    };
    el.addEventListener('mousedown', onDown);
    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  makeDraggable(markerStart, 0, state.audioBuffer.length);
  makeDraggable(markerEnd, 0, state.audioBuffer.length);

  // ---------- Event wiring ----------
  startBtn.addEventListener('click', startRecording);
  stopBtn.addEventListener('click', stopRecording);
  trimBtn.addEventListener('click', trim);
  applyBtn.addEventListener('click', applyEffects);
  downloadBtn.addEventListener('click', exportWAV);
  zoomIn.addEventListener('click', () => setZoom(state.zoom + 10));
  zoomOut.addEventListener('click', () => setZoom(state.zoom - 10));
  effectEcho.addEventListener('input', () => {
    echoVal.textContent = effectEcho.value + ' ms';
  });
  effectDistort.addEventListener('input', () => {
    distortVal.textContent = effectDistort.value + '%';
  });

  // ---------- Init ----------
  status.textContent = 'Ready. Click "Start Recording" to begin.';
})();
```

---

## ✅ How to Use

1. **Start Recording** — Click the green "Start Recording" button and grant microphone access.
2. **Record** — Speak or play audio into the microphone.
3. **Stop** — Click "Stop".
4. **Trim** — Drag the red markers on the waveform to select a segment. Click "Trim".
5. **Apply Effects** — Toggle reverse, echo, or distortion, then click "Apply Effects".
6. **Download** — Click "Download" to save the edited audio as a WAV file.

---

## ⚠️ Limitations

- Only mono output (stereo is supported but uses mono channel).
- Effects are applied in real time on the buffer (no Web Audio node graph — uses simple math).
- WAV encoding is lossless but may be large (mono 44.1kHz ~ 4MB per minute).
- Chrome requires a click to start recording (autoplay policy).

