// payment_state.dart
class PaymentState {
  final String id;
  final String platform;
  final String title;
  final String icon;
  final String mockUrl;

  PaymentState({
    required this.id,
    required this.platform,
    required this.title,
    required this.icon,
    required this.mockUrl,
  });

  PaymentState copyWith({
    String? id,
    String? platform,
    String? title,
    String? icon,
    String? mockUrl,
  }) {
    return PaymentState(
      id: id ?? this.id,
      platform: platform ?? this.platform,
      title: title ?? this.title,
      icon: icon ?? this.icon,
      mockUrl: mockUrl ?? this.mockUrl,
    );
  }
}
