// payment_flow.dart
import 'package:flutter/material.dart';
import '../models/platform.dart';

class PaymentFlowScreen extends StatefulWidget {
  final PaymentState platform;
  final String orderId;

  const PaymentFlowScreen({
    super.key,
    required this.platform,
    required this.orderId,
  });

  @override
  State<PaymentFlowScreen> createState() => _PaymentFlowScreenState();
}

class _PaymentFlowScreenState extends State<PaymentFlowScreen> {
  String _status = 'pending'; // pending | success | cancelled | expired | delivered

  void _simulatePayment() {
    setState(() {
      _status = 'pending';
    });
    Future.delayed(const Duration(seconds: 1), () {
      setState(() {
        _status = 'success';
      });
      Future.delayed(const Duration(seconds: 2), () {
        setState(() {
          _status = 'delivered';
        });
      });
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(
        title: Text('${widget.platform.title} 支付'),
        centerTitle: true,
      ),
      body: Padding(
        padding: const EdgeInsets.all(16.0),
        child: Column(
          children: [
            const SizedBox(height: 16),
            Text(
