## 📄 `server.js`

```javascript
const express = require('express');
const multer = require('multer');
const path = require('path');
const fs = require('fs').promises;
const { v4: uuidv4 } = require('uuid');

const app = express();
const PORT = process.env.PORT || 3000;

// --- Storage for chunks ---
const CHUNK_DIR = path.join(__dirname, 'file');
if (!fs.existsSync(CHUNK_DIR)) {
  fs.mkdir(CHUNK_DIR, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, CHUNK_DIR);
  },
  filename: (req, file, cb) => {
    const { id } = req.body;
    const ext = path.extname(file.originalname);
    const name = `${id}-${Date.now()}-${uuidv4()}${ext}`;
    cb(null, name);
  }
});

const upload = multer({ storage });

// --- Endpoint to receive a chunk ---
app.post('/upload', upload.single('file'), async (req, res) => {
  const { id, chunkIndex, chunkTotal, fileName } = req.body;

  if (!id || !chunkIndex || !chunkTotal || !fileName) {
    return res.status(400).json({ error: 'Missing required fields' });
  }

  try {
    // Check if final file exists — if not, create it as empty
    const finalPath = path.join(CHUNK_DIR, `${id}-${fileName}`);
    if (!fs.existsSync(finalPath)) {
      await fs.writeFile(finalPath, '');
    }

    // Append chunk
    const chunkPath = req.file.path;
    const chunkData = await fs.promises.readFile(chunkPath);
    await fs.promises.appendFile(finalPath, chunkData);

    // Delete chunk file
    await fs.promises.unlink(chunkPath);

    const progress = Math.round(((chunkIndex) / chunkTotal) * 100);
    res.json({
      ok: true,
      progress,
      received: chunkIndex,
      total: chunkTotal
    });

  } catch (err) {
    console.error(err);
    res.status(500).json({ error: 'Server error' });
  }
});

// --- Endpoint to check completion ---
app.get('/status/:id', async (req, res) => {
  const { id } = req.params;
  const finalPath = path.join(CHUNK_DIR, `${id}-final`);
  if (fs.existsSync(finalPath)) {
    res.json({ completed: true, path: finalPath });
  } else {
    res.json({ completed: false });
  }
});

// --- Serve static files ---
app.use(express.static('public'));

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

