## 🧠 `public/script.js`

```javascript
(function () {
  'use strict';

  const dropzone = document.getElementById('dropzone');
  const fileInput = document.getElementById('fileInput');
  const progress = document.getElementById('progress');
  const progressFill = document.getElementById('progressFill');
  const progressText = document.getElementById('progressText');
  const progressCount = document.getElementById('progressCount');
  const completed = document.getElementById('completed');
  const completedPath = document.getElementById('completedPath');
  const error = document.getElementById('error');
  const errorMessage = document.getElementById('errorMessage');

  const CHUNK_SIZE = 4 * 1024 * 1024; // 4MB
  const SERVER_URL = 'http://localhost:3000';
  const UPLOAD_URL = `${SERVER_URL}/upload`;

  let id = null;
  let fileName = null;
  let chunkIndex = 0;
  let chunkTotal = 0;
  let isUploading = false;

  function getChunks(file) {
    const size = file.size;
    chunkTotal = Math.ceil(size / CHUNK_SIZE);
    const chunks = [];
    for (let i = 0; i < chunkTotal; i++) {
      const start = i * CHUNK_SIZE;
      const end = Math.min(start + CHUNK_SIZE, size);
      chunks.push({
        start,
        end,
        blob: file.slice(start, end),
        index: i
      });
    }
    return chunks;
  }

  function readFileAsArrayBuffer(blob) {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = () => reject(reader.error);
      reader.readAsArrayBuffer(blob);
    });
  }

  async function uploadChunk(index, blob) {
    const fd = new FormData();
    fd.append('file', blob);
    fd.append('chunkIndex', index);
    fd.append('chunkTotal', chunkTotal);
    fd.append('fileName', fileName);

    const res = await fetch(UPLOAD_URL, {
      method: 'POST',
      body: fd
    });

    if (!res.ok) {
      throw new Error(`Upload failed: ${res.status}`);
    }
    return res.json();
  }

  async function handleFile(file) {
    if (!file) return;
    if (file.size === 0) {
      showError('File is empty');
      return;
    }
    if (file.size > 500 * 1024 * 1024) {
      showError('File exceeds 500MB limit');
      return;
    }

    id = Date.now() + '-' + Math.random().toString(36).slice(2, 8);
    fileName = file.name;

    const chunks = getChunks(file);
    chunkIndex = 0;

    progress.hidden = false;
    completed.hidden = true;
    error.hidden = true;

    const totalSize = file.size;
    const startTime = Date.now();

    for (const chunk of chunks) {
      if (isUploading) {
        const result = await uploadChunk(chunk.index, chunk.blob);
        const elapsed = Date.now() - startTime;
        const remaining = (chunks.length - chunkIndex - 1) * (totalSize / chunks.length);
        const eta = remaining > 0 ? Math.ceil(remaining / (elapsed / chunkIndex)) : 0;
        progressText.textContent = `${Math.round(((chunkIndex + 1) / chunkTotal) * 100)}% complete`;
        progressCount.textContent = `${chunkIndex + 1} / ${chunkTotal} chunks`;
        progressFill.style.width = `${Math.round(((chunkIndex + 1) / chunkTotal) * 100)}%`;
      }
      chunkIndex++;
    }

    // Finalize: check status
    const status = await fetch(`${SERVER_URL}/status/${id}`);
    const statusJson = await status.json();
    if (statusJson.completed) {
      completedPath.textContent = `Final file: ${fileName}`;
      completed.hidden = false;
    } else {
      showError('Upload did not complete successfully');
    }
  }

  function showError(msg) {
    errorMessage.textContent = msg;
    error.hidden = false;
  }

  function hideError() {
    error.hidden = true;
  }

  dropzone.addEventListener('click', () => fileInput.click());
  dropzone.addEventListener('keydown', (e) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      fileInput.click();
    }
  });

  fileInput.addEventListener('change', (e) => {
    const file = e.target.files[0];
    if (file) handleFile(file);
    fileInput.value = '';
  });

  ['dragenter', 'dragover'].forEach(evt => {
    dropzone.addEventListener(evt, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.add('dragover');
    });
  });

  ['dragleave', 'drop'].forEach(evt => {
    dropzone.addEventListener(evt, (e) => {
      e.preventDefault();
      e.stopPropagation();
      dropzone.classList.remove('dragover');
    });
  });

  dropzone.addEventListener('drop', (e) => {
    const file = e.dataTransfer.files[0];
    if (file) handleFile(file);
  });

  window.addEventListener('dragover', (e) => e.preventDefault());
  window.addEventListener('drop', (e) => e.preventDefault());
})();
```

